(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,858469,693179,e=>{"use strict";let t={itsfail:{lawFullRu:"законодательство Эстонии",lawFullEn:"the laws of Estonia",lawShortRu:"законодательством Эстонии",lawShortEn:"the laws of Estonia",courtsRu:"компетентными судами Эстонии",courtsEn:"the competent courts of Estonia"},gemgame:{lawFullRu:"законодательство Республики Кипр",lawFullEn:"the laws of the Republic of Cyprus",lawShortRu:"законодательством Республики Кипр",lawShortEn:"the laws of the Republic of Cyprus",courtsRu:"компетентными судами Республики Кипр",courtsEn:"the competent courts of the Republic of Cyprus"},cognito:{lawFullRu:"законодательство Специального административного района Гонконг Китайской Народной Республики",lawFullEn:"the laws of the Hong Kong Special Administrative Region of the People’s Republic of China",lawShortRu:"законодательством Специального административного района Гонконг",lawShortEn:"the laws of the Hong Kong Special Administrative Region",courtsRu:"компетентными судами Гонконга",courtsEn:"the competent courts of Hong Kong"},transtrade:{lawFullRu:"законодательство Кыргызской Республики",lawFullEn:"the laws of the Kyrgyz Republic",lawShortRu:"законодательством Кыргызской Республики",lawShortEn:"the laws of the Kyrgyz Republic",courtsRu:"компетентными судами Кыргызской Республики",courtsEn:"the competent courts of the Kyrgyz Republic"},costaRica:{lawFullRu:"законодательство Республики Коста-Рика",lawFullEn:"the laws of the Republic of Costa Rica",lawShortRu:"законодательством Республики Коста-Рика",lawShortEn:"the laws of the Republic of Costa Rica",courtsRu:"компетентными судами Республики Коста-Рика",courtsEn:"the competent courts of the Republic of Costa Rica"}},a=(e,t,a)=>e.map(e=>((e,t,a)=>{if(!a)return e.details.beneficiary;let{beneficiary:n,regNumber:o,address:r}=e.details,i="taxId"in e.details?e.details.taxId:null;return"ru"===t?i?`${n} (регистрационный номер: ${o}, налоговый номер: ${i}, адрес: ${r})`:`${n} (регистрационный номер: ${o}, адрес: ${r})`:i?`${n} (registration number: ${o}, tax ID: ${i}, address: ${r})`:`${n} (registration number: ${o}, address: ${r})`})(e,t,a)).join("ru"===t?" и ":" and "),n=(e,t={})=>e.replace(/\{(\w+)\}/g,(e,a)=>t[a]??e);e.s(["getContent",0,(e,o,r=[],i={})=>e.legalBlock?0===r.length?"":n(((e,n,o)=>{if("operatorHeader"===e){let e;return e=a(o,n,!0),"ru"===n?`Оператор: ${e}. Сайт: {brandTosSite}`:`Operator: ${e}. Website: {brandTosSite}`}if("parties"===e){let e;return e=a(o,n,!0),"ru"===n?`1.1. Настоящее Пользовательское соглашение (далее — \xabСоглашение\xbb) представляет собой юридически обязательный договор, заключаемый между ${e} (далее — \xabОператор\xbb), с одной стороны, и дееспособным физическим лицом, осуществляющим доступ к сайту {brandTosSite}, использующим его программные компоненты, интерфейсы, информационные системы и (или) иные доступные посредством него функциональные возможности (далее — \xabПользователь\xbb), с другой стороны, совместно именуемыми в дальнейшем \xabСтороны\xbb, а по отдельности — \xabСторона\xbb.`:`1.1. This User Agreement (the “Agreement”) constitutes a legally binding contract between ${e} (the “Operator”), on the one part, and a legally competent individual accessing the website {brandTosSite} and using its software components, interfaces, information systems and/or other functionality made available through it (the “User”), on the other part, jointly referred to as the “Parties” and individually as a “Party”.`}let r=o[0],i=r?t[r.id]:void 0;return"applicableLawDef"===e?"ru"===n?`\xabПрименимое законодательство\xbb — ${i?.lawFullRu??"законодательство страны регистрации Оператора Платформы"} в той мере, в которой оно избрано Сторонами в качестве права, регулирующего настоящее Соглашение и возникающие из него отношения, а также любые императивные нормы законодательства иной юрисдикции, которые в силу соответствующих коллизионных норм, статуса Пользователя, места его нахождения, характера конкретной операции либо иных юридически значимых обстоятельств подлежат обязательному применению независимо от выбранного Сторонами права.`:`“Applicable Law” means ${i?.lawFullEn??"the laws of the country where the Platform Operator is registered"} to the extent chosen by the Parties to govern this Agreement and the relationships arising out of it, together with any mandatory provisions of another jurisdiction that, by virtue of applicable conflict-of-laws rules, the User’s status, location, the nature of a particular transaction or other legally relevant circumstances, apply regardless of the Parties’ choice of law.`:"ru"===n?`19.3. Настоящее Соглашение и возникающие из него или в связи с ним договорные отношения регулируются ${i?.lawShortRu??"законодательством страны регистрации Оператора Платформы"} без учета его коллизионных норм. Споры подлежат рассмотрению ${i?.courtsRu??"компетентными судами по месту регистрации Оператора"}, если императивные нормы Применимого законодательства не предоставляют Пользователю право на рассмотрение спора иным компетентным судом. Выбор применимого права и юрисдикции не лишает Пользователя, являющегося потребителем, защиты, от которой он не может отказаться в силу обязательных норм законодательства страны его обычного места проживания, если такие нормы применимы к соответствующим отношениям независимо от выбора права сторонами.`:`19.3. This Agreement and any contractual relationship arising out of or in connection with it shall be governed by ${i?.lawShortEn??"the laws of the country where the Platform Operator is registered"}, without regard to its conflict-of-laws rules. Any dispute shall be submitted to ${i?.courtsEn??"the competent courts at the place where the Operator is registered"}, unless mandatory provisions of Applicable Law entitle the User to bring the dispute before another competent court. This choice of law and jurisdiction does not deprive a User acting as a consumer of any protection that cannot be waived under the mandatory laws of the country of the User’s habitual residence, where those laws apply irrespective of the Parties’ choice of law.`})(e.legalBlock,o,r),i):n(("ru"===o?e.contentRu:e.contentEn)??"",i),"getItems",0,(e,t,a={})=>(("ru"===t?e.itemsRu:e.itemsEn)??[]).map(e=>n(e,a)),"interpolateTosText",0,n,"tosData",0,[{type:"paragraph",legalBlock:"operatorHeader"},{type:"paragraph",contentRu:"До момента осуществления регистрации учетной записи на Платформе, внесения денежных средств и (или) иных предусмотренных функционалом Платформы активов, а равно до совершения любых Игровых операций Пользователь обязан внимательно и в полном объеме ознакомиться с условиями настоящего Соглашения и оценить правовые, имущественные и иные последствия его принятия.",contentEn:"Before registering an Account on the Platform, adding funds and/or other assets supported by the Platform, or performing any Game Operation, the User shall carefully review this Agreement in full and assess the legal, financial and other consequences of accepting it."},{type:"paragraph",contentRu:"Пользователь настоящим подтверждает и безоговорочно принимает к сведению, что использование функциональных возможностей Платформы, включая совершение Игровых операций, предполагает формирование (определение) цифрового результата, содержание, характеристики и (или) иные параметры которого объективно не могут быть достоверно определены Пользователем до момента завершения соответствующей Игровой операции.",contentEn:"The User acknowledges that using the Platform, including performing Game Operations, involves generating or determining a digital result whose content, characteristics and/or other parameters cannot be known with certainty until the relevant Game Operation is completed."},{type:"paragraph",contentRu:"Совершение Игровой операции само по себе не влечет возникновения у Пользователя права требовать предоставления Предмета, обладающего заранее определенной, минимальной, эквивалентной внесенным средствам либо иной предполагаемой Пользователем стоимостью, и не является гарантией получения Предмета, соответствующего ожиданиям Пользователя в отношении его вида, характеристик, потребительской, рыночной или иной стоимости.",contentEn:"Completion of a Game Operation does not, by itself, entitle the User to an Item of any predetermined or minimum value, any value equivalent to the amount paid, or any other value anticipated by the User, nor does it guarantee an Item meeting the User's expectations as to type, characteristics, utility, market value or otherwise."},{type:"paragraph",contentRu:"Настоящее Пользовательское соглашение устанавливает юридически обязательные условия предоставления доступа к Платформе и использования ее функциональных возможностей, определяет объем прав, обязанностей и ответственности Оператора и Пользователя, устанавливает порядок совершения операций посредством Платформы, а также закрепляет распределение между Сторонами правовых, имущественных, технических и иных рисков, возникающих в связи с использованием Платформы.",contentEn:"This User Agreement sets out the legally binding terms governing access to and use of the Platform, defines the rights, obligations and liabilities of the Operator and the User, establishes the procedure for transactions conducted through the Platform, and allocates between the Parties the legal, financial, technical and other risks arising from use of the Platform."},{type:"paragraph",contentRu:"Настоящее Соглашение подлежит применению в системной взаимосвязи с Политикой конфиденциальности, Политикой использования файлов cookie, AML/KYC-политикой, правилами проведения отдельных акций, специальными условиями использования отдельных функций Платформы и иными документами, размещенными Оператором на Сайте и прямо определенными в качестве составной части договорных отношений между Оператором и Пользователем.",contentEn:"This Agreement shall be read together with the Privacy Policy, Cookie Policy, AML/KYC Policy, rules of individual promotions, special terms governing specific Platform functions, and any other documents posted by the Operator on the Site and expressly incorporated into the contractual relationship between the Operator and the User."},{type:"paragraph",contentRu:"До момента регистрации Аккаунта, Пополнения Внутреннего баланса и (или) совершения любых Игровых операций Пользователь обязан самостоятельно, внимательно и в полном объеме ознакомиться с условиями настоящего Соглашения и связанных с ним документов, оценить правовые, имущественные, экономические, технические и иные последствия их принятия, а также удостовериться в наличии у него необходимого объема дееспособности и законных оснований для использования Платформы.",contentEn:"Before registering an Account, making a Top-Up to the Internal Balance and/or performing any Game Operation, the User shall independently and carefully review this Agreement and the related documents in full, assess the legal, financial, economic, technical and other consequences of accepting them, and ensure that the User has the necessary legal capacity and lawful grounds to use the Platform."},{type:"paragraph",contentRu:"Регистрация Аккаунта, Пополнение Внутреннего баланса, совершение Игровой операции либо иное фактическое использование функциональных возможностей Платформы в случаях и порядке, предусмотренных настоящим Соглашением, означает полное, безусловное и безоговорочное принятие Пользователем условий настоящего Соглашения в пределах, допускаемых применимым законодательством.",contentEn:"Registration of an Account, a Top-Up to the Internal Balance, performance of a Game Operation or other actual use of the functionality of the Platform in the cases and manner provided for in this Agreement means the full, unconditional and unreserved acceptance by the User of the terms of this Agreement to the extent permitted by Applicable Law."},{type:"paragraph",contentRu:"Пользователь обязан воздержаться от регистрации и прекратить использование Платформы в случае, если он не понимает юридического значения или содержания отдельных положений настоящего Соглашения, не соответствует установленным требованиям к возрасту и дееспособности, не обладает необходимыми полномочиями либо использование Платформы или отдельных ее функций запрещено или ограничено законодательством государства или территории его фактического нахождения, гражданства, резидентства либо иной применимой к нему юрисдикции.",contentEn:"The User shall not register and shall stop using the Platform if the User does not understand the legal meaning or content of any provision of this Agreement, does not satisfy applicable age or legal-capacity requirements, lacks the necessary authority, or if use of the Platform or any function is prohibited or restricted under the laws of the User's location, citizenship, residence or any other jurisdiction applicable to the User."},{type:"subtitle",contentRu:"1. Общие положения",contentEn:"1. General Provisions",level:1},{type:"paragraph",legalBlock:"parties"},{type:"paragraph",contentRu:"1.2. Настоящее Соглашение определяет условия и порядок предоставления Пользователю доступа к Платформе и регулирует отношения Сторон, возникающие в связи с регистрацией, созданием и использованием Аккаунта, Пополнением Внутреннего баланса, совершением Игровых операций, а также получением, хранением, улучшением, обменом, выводом, автоматической реализацией и совершением иных предусмотренных функционалом Платформы действий в отношении Предметов.",contentEn:"1.2. This Agreement defines the conditions and procedure for providing the User with access to the Platform and regulates the relations of the Parties arising in connection with the registration, creation and use of the Account, a Top-Up to the Internal Balance, performance of Game Operations, as well as receipt, storage, improvement, exchange, withdrawal, automatic implementation and performance of other actions provided for by the functionality of the Platform in relation to Items."},{type:"paragraph",contentRu:"1.3. Действие настоящего Соглашения распространяется также на отношения, связанные с предоставлением, начислением, использованием, ограничением, аннулированием и иным распоряжением бонусами, промокодами, поощрениями и иными предоставляемыми Оператором преимуществами, а равно на любые иные отношения, непосредственно обусловленные использованием Пользователем Платформы, если иное прямо не предусмотрено специальными условиями соответствующей функции.",contentEn:"1.3. This Agreement also applies to relations related to the provision, accrual, use, limitation, cancellation and other disposal of bonuses, promotional codes, incentives and other benefits provided by the Operator, as well as to any other relations directly related to the User’s use of the Platform, unless otherwise expressly provided for by the special conditions of the relevant function."},{type:"paragraph",contentRu:"1.4. Оператор является единственной стороной настоящего Соглашения, предоставляющей Пользователю доступ к Платформе. Привлечение Оператором для обеспечения функционирования Платформы третьих лиц, включая платежные организации, платежных агентов и провайдеров, поставщиков и разработчиков программного обеспечения, операторов информационной инфраструктуры, хостинг-провайдеров, поставщиков услуг идентификации и верификации, сервисов противодействия мошенничеству, Steam-ботов и иных подрядчиков, не означает вступления таких лиц в настоящее Соглашение и само по себе не создает самостоятельных договорных отношений между Пользователем и соответствующими лицами, если иное прямо не доведено до сведения Пользователя до совершения соответствующей операции.",contentEn:"1.4. The Operator is the sole party to this Agreement that provides the User with access to the Platform. The Operator's engagement of third parties to support Platform operations, including payment organizations, payment agents and providers, software suppliers and developers, hosting providers, verification providers, anti-fraud services, Steam bots and other contractors, does not make those persons parties to this Agreement or create a separate contractual relationship with the User unless expressly stated otherwise before the relevant transaction."},{type:"paragraph",contentRu:"1.5. Функции, фактически исполняемые третьими лицами в рамках обеспечения деятельности Платформы, могут регулироваться самостоятельными условиями использования, политиками и иными документами соответствующих третьих лиц. В случаях, когда для использования соответствующей функции требуется принятие таких условий, Пользователь самостоятельно осуществляет ознакомление с ними и принимает решение об использовании соответствующего стороннего сервиса.",contentEn:"1.5. The functions actually performed by third parties as part of the operation of the Platform may be regulated by independent terms of use, policies and other documents of the relevant third parties. In cases where the use of the corresponding function requires acceptance of such conditions, the User independently familiarizes himself with them and decides to use the corresponding third-party service."},{type:"paragraph",contentRu:"1.6. Платформа является самостоятельным и независимым интернет-сервисом. Если иное прямо не указано Оператором, Платформа, Оператор и связанные с Оператором лица не являются аффилированными, уполномоченными, спонсируемыми, контролируемыми или иным образом официально связанными с Valve Corporation, Steam, разработчиками или правообладателями соответствующих компьютерных игр либо иными владельцами упоминаемых на Платформе товарных знаков и объектов интеллектуальной собственности.",contentEn:"1.6. The Platform is a separate and independent Internet service. Unless otherwise expressly stated by the Operator, the Platform, the Operator and persons associated with the Operator are not affiliated, authorized, sponsored, controlled or otherwise officially associated with Valve Corporation, Steam, the developers or copyright holders of the relevant computer games, or other owners of trademarks and intellectual property mentioned on the Platform."},{type:"paragraph",contentRu:"1.7. Используемые на Платформе наименования, товарные знаки, коммерческие обозначения, изображения, элементы интерфейсов, наименования компьютерных игр и цифровых объектов, принадлежащие третьим лицам, используются исключительно в информационных и идентификационных целях, в том числе для обозначения совместимых сервисов, соответствующих цифровых объектов и их принадлежности к определенной компьютерной игре или сторонней экосистеме, если иное прямо не следует из соответствующего обозначения.",contentEn:"1.7. The names, trademarks, commercial designations, images, interface elements, names of computer games and digital objects owned by third parties used on the Platform are used solely for informational and identification purposes, including to designate compatible services, corresponding digital objects and their belonging to a specific computer game or third-party ecosystem, unless otherwise directly indicated by the corresponding designation."},{type:"paragraph",contentRu:"1.8. Настоящее Соглашение применяется совместно с Политикой конфиденциальности, Политикой использования файлов cookie, AML/KYC-политикой, правилами отдельных рекламных и стимулирующих мероприятий, специальными условиями отдельных Игровых операций, а также иными правилами, политиками и документами, размещенными Оператором на Сайте и прямо отнесенными к регулированию использования Платформы.",contentEn:"1.8. This Agreement is applied in conjunction with the Privacy Policy, Cookie Policy, AML/KYC Policy, rules for individual advertising and promotional events, special conditions for individual Game Operations, as well as other rules, policies and documents posted by the Operator on the Site and directly related to regulating the use of the Platform."},{type:"paragraph",contentRu:"1.9. В случае возникновения противоречия между положениями настоящего Соглашения и специальными условиями, установленными Оператором в отношении конкретной функции, акции, бонусной программы или отдельного вида операции, специальные условия имеют преимущественную силу исключительно применительно к соответствующей функции, акции, программе или операции. Во всех остальных случаях применяются положения настоящего Соглашения, если иное не предусмотрено императивными нормами применимого законодательства.",contentEn:"1.9. In the event of a conflict between the provisions of this Agreement and the special terms established by the Operator in relation to a particular feature, promotion, bonus program or particular type of transaction, the special terms shall prevail solely in relation to the relevant feature, promotion, program or transaction. In all other cases, the provisions of this Agreement apply, unless otherwise provided by mandatory provisions of the Applicable Law."},{type:"paragraph",contentRu:"1.10. Ни одно положение настоящего Соглашения, а равно предоставление доступа к Платформе, наличие Внутреннего баланса либо возможность совершения предусмотренных Платформой операций не должны толковаться как предложение, предоставление или оказание Оператором банковских, платежных, инвестиционных, брокерских, дилерских, депозитарных, страховых, доверительных либо иных регулируемых финансовых услуг, если соответствующая квалификация прямо не вытекает из императивных требований применимого законодательства.",contentEn:"1.10. No provision of this Agreement, nor access to the Platform, the existence of an Internal Balance or the availability of a Platform transaction, shall be construed as an offer or provision by the Operator of banking, payment, investment, brokerage, dealing, custody, insurance, trust or another regulated financial service, unless Applicable Law mandatorily requires that classification."},{type:"paragraph",contentRu:"1.11. Внутренний баланс представляет собой исключительно предусмотренный функционалом Платформы технический и учетный показатель объема доступных Пользователю возможностей в пределах Платформы и не является банковским счетом, вкладом, депозитом, электронным кошельком либо самостоятельным финансовым продуктом, если иное прямо не установлено применимым законодательством.",contentEn:"1.11. Internal Balance is solely a technical and accounting indicator of the volume of opportunities available to the User within the Platform, provided for by the functionality of the Platform, and is not a bank account, deposit, electronic wallet or an independent financial product, unless otherwise expressly provided by Applicable Law."},{type:"paragraph",contentRu:"1.12. Оператор не принимает денежные средства Пользователя во вклад, не осуществляет начисление процентов или иного гарантированного дохода на Внутренний баланс и не предоставляет самостоятельную услугу по хранению денежных средств Пользователя исключительно в целях их последующего востребования или вывода, если иное прямо не предусмотрено отдельными условиями Оператора и допускается применимым законодательством.",contentEn:"1.12. The Operator does not accept the User’s funds as a deposit, does not accrue interest or other guaranteed income on the Internal Balance, and does not provide an independent service for storing the User’s funds solely for the purpose of their subsequent withdrawal or withdrawal, unless otherwise expressly provided for by the Operator’s individual terms and conditions and permitted by Applicable Law."},{type:"paragraph",contentRu:"1.13. Отображение какой-либо функции, способа Пополнения, Игровой операции, Предмета либо иной возможности в интерфейсе Платформы само по себе не является безусловной гарантией ее постоянной или безотзывной доступности для конкретного Пользователя.",contentEn:"1.13. The display of any function, Top-Up method, Game Operation, Item or other feature in the Platform interface does not in itself constitute an unconditional guarantee of its constant or irrevocable availability for a particular User."},{type:"paragraph",contentRu:"1.14. Оператор вправе в пределах, допускаемых применимым законодательством, устанавливать и изменять технические, территориальные, возрастные, операционные, транзакционные, риск-ориентированные, комплаенс- и иные обоснованные ограничения использования Платформы, включая ограничения в отношении отдельных Аккаунтов, государств и территорий, способов оплаты, категорий Предметов, Игровых операций, лимитов и функциональных возможностей.",contentEn:"1.14. The Operator has the right, to the extent permitted by Applicable Law, to establish and change technical, territorial, age-related, operational, transactional, risk-based, compliance and other reasonable restrictions on the use of the Platform, including restrictions in relation to individual Accounts, states and territories, payment methods, categories of Items, Game Operations, limits and functionality."},{type:"paragraph",contentRu:"1.15. Пользователь самостоятельно несет обязанность до начала и в течение всего периода использования Платформы удостоверяться в том, что использование Платформы и каждой конкретной функции допускается законодательством, применимым к Пользователю с учетом его гражданства, резидентства, места нахождения и иных юридически значимых обстоятельств.",contentEn:"1.15. The User independently bears the responsibility, before and during the entire period of use of the Platform, to make sure that the use of the Platform and each specific function is permitted by the legislation applicable to the User, taking into account his citizenship, residence, location and other legally significant circumstances."},{type:"paragraph",contentRu:"1.16. Пользователь обязуется использовать Платформу исключительно от собственного имени, в собственных интересах и с использованием принадлежащих ему либо правомерно находящихся в его распоряжении Аккаунта, платежных инструментов и учетных записей сторонних сервисов, если иное предварительно и прямо не согласовано с Оператором и не противоречит применимому законодательству.",contentEn:"1.16. The User undertakes to use the Platform solely on his own behalf, in his own interests and using the Account, payment instruments and accounts of third-party services belonging to him or legally at his disposal, unless otherwise previously and directly agreed with the Operator and does not contradict Applicable Law."},{type:"paragraph",contentRu:"1.17. Использование Пользователем платежного средства, банковской карты, электронного кошелька, Steam-аккаунта, учетной записи либо иных средств идентификации, принадлежащих третьему лицу, равно как совершение операций от имени или в интересах третьего лица без предварительного разрешения Оператора в случаях, когда такое разрешение требуется, является нарушением настоящего Соглашения и может являться основанием для применения предусмотренных им ограничительных мер.",contentEn:"1.17. The User's use of a payment instrument, bank card, electronic wallet, Steam Account, account or other means of identification belonging to a third party, as well as performing transactions on behalf of or in the interests of a third party without the prior permission of the Operator in cases where such permission is required, is a violation of this Agreement and may be the basis for the application of restrictive measures provided for by it."},{type:"paragraph",contentRu:"1.18. Пользователь несет ответственность за достоверность предоставляемых Оператору сведений и обязан по требованию Оператора в случаях, предусмотренных настоящим Соглашением или применимым законодательством, подтвердить принадлежность используемых им платежных инструментов, Аккаунта и связанных с ним учетных записей.",contentEn:"1.18. The User is responsible for the accuracy of the information provided to the Operator and is obliged, at the request of the Operator in cases provided for by this Agreement or Applicable Law, to confirm the ownership of the payment instruments, Account and related accounts used by him."},{type:"paragraph",contentRu:"1.19. Наименования разделов, подразделов и отдельных положений настоящего Соглашения используются исключительно для удобства навигации и систематизации текста, не обладают самостоятельным нормативным значением и не могут использоваться для ограничения, изменения либо расширения содержания соответствующих положений.",contentEn:"1.19. The names of sections, subsections and individual provisions of this Agreement are used solely for ease of navigation and systematization of the text, do not have independent regulatory significance and cannot be used to limit, change or expand the content of the relevant provisions."},{type:"paragraph",contentRu:"1.20. Если иное прямо не следует из содержания или существа соответствующего положения, используемые в настоящем Соглашении термины в единственном числе включают соответствующие термины во множественном числе и наоборот, а указание на лицо включает его допустимых правопреемников в той мере, в какой соответствующее правопреемство допускается характером правоотношения и применимым законодательством.",contentEn:"1.20. Unless otherwise expressly implied by the content or substance of the relevant provision, terms used in this Agreement in the singular include the corresponding terms in the plural and vice versa, and references to a person include its permitted successors to the extent that such succession is permitted by the nature of the legal relationship and Applicable Law."},{type:"paragraph",contentRu:"1.21. Никакое положение настоящего Соглашения не направлено на исключение, ограничение или лишение Пользователя прав и гарантий, предоставленных ему императивными нормами применимого законодательства и не подлежащих изменению или отмене соглашением Сторон.",contentEn:"1.21. No provision of this Agreement is intended to exclude, limit or deprive the User of the rights and guarantees granted to him by mandatory rules of Applicable Law and not subject to amendment or cancellation by agreement of the Parties."},{type:"paragraph",contentRu:"1.22. В случае если какое-либо положение настоящего Соглашения полностью или частично признается недействительным, неисполнимым либо не подлежащим применению в силу императивных требований применимого законодательства, такое обстоятельство не влечет недействительности остальных положений Соглашения, которые продолжают действовать в максимально допустимом законом объеме.",contentEn:"1.22. If any provision of this Agreement is held wholly or partly invalid, illegal, unenforceable or inapplicable under mandatory provisions of Applicable Law, the remaining provisions shall remain effective to the fullest extent permitted by law."},{type:"paragraph",contentRu:"1.23. При наличии нескольких юридически допустимых вариантов толкования положения настоящего Соглашения такое положение подлежит толкованию способом, позволяющим в максимально допустимой применимым законодательством степени сохранить его действительность, исполнимость, первоначальную договорную цель и установленное настоящим Соглашением распределение прав, обязанностей и рисков между Сторонами.",contentEn:"1.23. If there are several legally permissible interpretations of a provision of this Agreement, such provision shall be interpreted in a manner that allows, to the maximum extent permitted by Applicable Law, to preserve its validity, enforceability, original contractual purpose and the distribution of rights, obligations and risks between the Parties established by this Agreement."},{type:"paragraph",contentRu:"1.24. Пользователь подтверждает, что до начала использования Платформы ему предоставлена возможность ознакомиться с настоящим Соглашением. Продолжение использования Платформы после принятия Соглашения означает согласие Пользователя соблюдать установленные им правила в течение всего периода использования Платформы.",contentEn:"1.24. The User confirms that before using the Platform, he has been given the opportunity to familiarize himself with this Agreement. Continued use of the Platform after accepting the Agreement means the User agrees to comply with the rules established by him throughout the entire period of use of the Platform."},{type:"paragraph",contentRu:"1.25. Если Пользователь не согласен полностью или частично с настоящим Соглашением либо не способен самостоятельно определить правовые последствия его принятия, Пользователь обязан отказаться от регистрации Аккаунта, Пополнения Внутреннего баланса, совершения Игровых операций и любого иного использования функциональных возможностей Платформы.",contentEn:"1.25. If the User does not agree in whole or in part with this Agreement or is unable to independently determine the legal consequences of its acceptance, the User shall refuse to register an Account, replenish the Internal Balance, perform Game Operations and any other use of the functionality of the Platform."},{type:"subtitle",contentRu:"Термины и определения",contentEn:"Terms and definitions",level:1},{type:"paragraph",contentRu:"Для целей настоящего Соглашения нижеприведенные термины и определения имеют указанное ниже значение, если иное прямо не предусмотрено отдельным положением настоящего Соглашения либо не следует из существа соответствующего правоотношения или контекста. Термины, используемые с заглавной буквы, применяются в установленном настоящим разделом значении во всем тексте Соглашения, включая приложения, специальные условия, политики и иные документы Оператора, являющиеся его неотъемлемой частью.",contentEn:"For the purposes of this Agreement, the following terms and definitions have the meaning indicated below, unless otherwise expressly provided by a separate provision of this Agreement or follows from the essence of the relevant legal relationship or context. Capitalized terms are used in the meaning established by this section throughout the entire text of the Agreement, including appendices, special conditions, policies and other documents of the Operator that are an integral part of it."},{type:"paragraph",contentRu:"«Сайт» — принадлежащий Оператору и (или) используемый им в целях предоставления доступа к функциональным возможностям Платформы интернет-ресурс, доступный по адресу {brandTosSite}, включая, в зависимости от применимости, его языковые и региональные версии, доменные имена, поддомены, отдельные веб-страницы, программные и пользовательские веб-интерфейсы, а также иные официально обозначенные Оператором электронные точки доступа. Указанное определение не распространяется на сайты, приложения и иные информационные ресурсы третьих лиц, переход к которым может осуществляться посредством размещенных на Сайте гиперссылок или иных технических средств.",contentEn:"“Site” is an Internet resource owned by the Operator and/or used by it to provide access to the functionality of the Platform, available at {brandTosSite}, including, depending on applicability, its language and regional versions, domain names, subdomains, individual web pages, software and user web interfaces, as well as other electronic access points officially designated by the Operator. This definition does not apply to sites, applications and other information resources of third parties, which can be accessed through hyperlinks or other technical means posted on the Site."},{type:"paragraph",contentRu:"«Платформа» — принадлежащая Оператору, находящаяся под его управлением либо правомерно используемая им совокупность программных, программно-аппаратных, информационных и технологических средств, включающая Сайт, серверную и сетевую инфраструктуру, базы данных, программные модули, алгоритмы, пользовательские и программные интерфейсы, механизмы обработки операций, системы учета и иные сервисные функции, посредством которых Пользователю предоставляется возможность использования предусмотренного настоящим Соглашением функционала.",contentEn:"“Platform” means the collection of software, hardware, information and technology resources owned, controlled or lawfully used by the Operator, including the Site, server and network infrastructure, databases, software modules, algorithms, user and application programming interfaces, transaction-processing mechanisms, accounting systems and other service functions through which the functionality contemplated by this Agreement is made available to the User."},{type:"paragraph",contentRu:"«Аккаунт» — индивидуальная учетная запись Пользователя на Платформе, создаваемая и (или) активируемая в установленном Оператором порядке, в том числе посредством авторизации с использованием Steam-аккаунта, и содержащая совокупность относящихся к Пользователю учетных и технических сведений, включая сведения о Внутреннем балансе, Инвентаре, совершенных операциях, примененных ограничениях, настройках и иных данных, предусмотренных функционалом Платформы. Аккаунт является средством технического учета и предоставления доступа к Платформе и сам по себе не представляет собой самостоятельный объект имущественных прав Пользователя.",contentEn:"“Account” means the User's individual account on the Platform, created and/or activated in accordance with the Operator's procedure, including through authentication with a Steam Account, and containing accounting and technical information relating to the User, including the Internal Balance, Inventory, transactions, restrictions and settings. The Account is a technical record and means of access and does not, by itself, constitute a separate item of property."},{type:"paragraph",contentRu:"«Steam-аккаунт» — принадлежащая либо правомерно используемая Пользователем учетная запись в информационно-цифровом сервисе Steam, посредством которой в предусмотренных Платформой случаях осуществляется авторизация, идентификация и (или) взаимодействие Пользователя с отдельными функциями Платформы. Steam-аккаунт создается, обслуживается и регулируется соответствующими документами, правилами и техническими требованиями Valve Corporation и (или) иных лиц, осуществляющих управление Steam, не принадлежит Оператору и не находится под его техническим или юридическим контролем.",contentEn:"“Steam Account” is an account owned or lawfully used by the User in the Steam information and digital service, through which, in cases provided for by the Platform, the User is authorized, identified and/or interacts with certain functions of the Platform. The Steam Account is created, maintained and regulated by the relevant documents, rules and technical requirements of Valve Corporation and/or other persons managing Steam, and is not owned by the Operator and is not under its technical or legal control."},{type:"paragraph",contentRu:"«Внутренний баланс» — формируемый и учитываемый информационными системами Платформы технический учетный показатель количества условных единиц, доступных Пользователю для совершения предусмотренных функционалом Платформы операций. Внутренний баланс предназначен исключительно для внутреннего учета и использования функциональных возможностей Платформы и, если иное прямо не предусмотрено императивными нормами Применимого законодательства, не является законным средством платежа, валютой, иностранной валютой, электронными деньгами, цифровой валютой, криптовалютой, платежным инструментом, банковским счетом, банковским вкладом, депозитом, ценной бумагой, финансовым инструментом или иным самостоятельным финансовым активом, а также сам по себе не удостоверяет безусловного денежного требования Пользователя к Оператору о выплате соответствующей суммы денежных средств.",contentEn:"“Internal Balance” means the technical accounting record, generated and maintained by the Platform, of the number of notional units available to the User for supported transactions. Unless mandatory provisions of Applicable Law require otherwise, it is not legal tender, currency, electronic money, cryptocurrency, a payment instrument, bank account, deposit, security, financial instrument or other standalone financial asset, and does not evidence an unconditional monetary claim against the Operator."},{type:"paragraph",contentRu:"«Пополнение» — совершаемая Пользователем с использованием одного из доступных на соответствующий момент способов оплаты операция, направленная на увеличение Внутреннего баланса на количество условных единиц, определяемое Платформой в соответствии с условиями, отображаемыми Пользователю до подтверждения соответствующей операции. Пополнение не является внесением денежных средств на банковский счет или во вклад и не предполагает возникновения у Оператора обязанности по начислению процентов либо иной доходности на сумму Внутреннего баланса.",contentEn:"“Top-Up” means a transaction made by the User using an available payment method to increase the Internal Balance by the number of notional units displayed before confirmation. A Top-Up is not a bank deposit and does not require the Operator to pay interest or another return on the Internal Balance."},{type:"paragraph",contentRu:"«Игровая операция» — инициируемое и подтверждаемое Пользователем действие по использованию отдельной функциональной или игровой механики Платформы, результат которого формируется, определяется и (или) фиксируется посредством программно-технических средств Платформы в соответствии с параметрами соответствующей функции и отражается в Аккаунте Пользователя. К Игровым операциям относятся, в частности, открытие Кейса, Апгрейд, Контракт, а также иные доступные на соответствующий момент функциональные механики, предусматривающие получение цифрового результата.",contentEn:"“Game Operation” is an action initiated and confirmed by the User to use individual functional or game mechanics of the Platform, the result of which is generated, determined and/or recorded using the software and hardware of the Platform in accordance with the parameters of the corresponding function and is reflected in the User Account. Game Operations include, in particular, opening a Case, Upgrade, Contract, as well as other functional mechanics available at the relevant time that provide for obtaining a digital result."},{type:"paragraph",contentRu:"«Кейс» — предусмотренная функционалом Платформы цифровая сервисная механика, при инициировании которой Пользователь на установленных и отображаемых Платформой условиях получает один из результатов, входящих в предусмотренную для соответствующего Кейса совокупность возможных результатов, при этом конкретный результат соответствующей операции заранее Пользователю не известен и определяется программными средствами Платформы в порядке, предусмотренном условиями соответствующей функции.",contentEn:"“Case” is a digital service mechanic provided for by the functionality of the Platform, upon initiation of which the User, under the conditions established and displayed by the Platform, receives one of the results included in the set of possible results provided for the corresponding Case, while the specific result of the corresponding operation is not known to the User in advance and is determined by the Platform software in the manner prescribed by the conditions of the corresponding function."},{type:"paragraph",contentRu:"«Апгрейд» — предусмотренная Платформой функциональная механика, посредством которой Пользователь вправе использовать один или несколько Предметов, условные единицы Внутреннего баланса либо их допустимую комбинацию в целях совершения операции, предполагающей возможность получения иного Предмета в соответствии с параметрами, условиями и иными существенными характеристиками, отображаемыми Пользователю непосредственно до подтверждения соответствующей операции. Совершение Апгрейда не означает и не создает гарантии получения Пользователем желаемого Предмета или результата.",contentEn:"“Upgrade” is a functional mechanics provided by the Platform, through which the User may use one or more Items, notional units of Internal Balance, or an acceptable combination thereof for the purpose of performing an operation that implies the possibility of obtaining another Item in accordance with the parameters, conditions and other significant characteristics displayed to the User immediately before confirmation of the corresponding operation. Making an Upgrade does not mean or create a guarantee that the User will receive the desired Item or result."},{type:"paragraph",contentRu:"«Контракт» — предусмотренная функционалом Платформы цифровая сервисная механика, позволяющая Пользователю объединить, предоставить для использования и (или) иным предусмотренным интерфейсом способом задействовать установленное количество соответствующих требованиям Платформы Предметов в целях формирования нового цифрового результата на условиях и в соответствии с параметрами, отображаемыми Пользователю до момента окончательного подтверждения операции.",contentEn:"“Contract” is a digital service mechanism provided for by the functionality of the Platform, which allows the User to combine, provide for use and/or use in another manner provided by the interface a set number of Items that meet the requirements of the Platform in order to generate a new digital result on the terms and in accordance with the parameters displayed to the User until the final confirmation of the operation."},{type:"paragraph",contentRu:"«Предмет» — визуально и (или) информационно отображаемый посредством интерфейса Платформы цифровой объект, связанный с игровым контентом, соответствующей компьютерной игрой и (или) инфраструктурой Steam и идентифицируемый посредством совокупности предусмотренных соответствующими информационными системами характеристик. Если иное не следует из императивных требований Применимого законодательства, Предмет не является денежными средствами, электронными деньгами, ценной бумагой, финансовым инструментом либо иным регулируемым финансовым активом. Возможность владения, использования, передачи, обмена и совершения иных действий с соответствующим Предметом определяется, помимо настоящего Соглашения, техническими возможностями и правилами Steam, соответствующей компьютерной игры и иных применимых сторонних сервисов, которые не находятся под контролем Оператора.",contentEn:"“Item” is a digital object visually and/or informationally displayed through the Platform interface, associated with game content, the corresponding computer game and/or Steam infrastructure and identified through a set of characteristics provided by the relevant information systems. Unless otherwise required by the Applicable Law, the Item is not cash, electronic money, security, financial instrument or other regulated financial asset. The ability to own, use, transfer, exchange and perform other actions with the relevant Item is determined, in addition to this Agreement, by the technical capabilities and rules of Steam, the corresponding computer game and other applicable third-party services that are not under the control of the Operator."},{type:"paragraph",contentRu:"«Инвентарь» — специализированный раздел Аккаунта и соответствующая ему совокупность серверных учетных записей, посредством которых отображаются Предметы, учитываемые Платформой как доступные конкретному Пользователю до момента их использования в Игровой операции, Вывода, обмена, Автоматической продажи либо иного предусмотренного настоящим Соглашением списания, прекращения отображения или изменения их учетного статуса. Отображение Предмета в Инвентаре само по себе не является безусловной гарантией технической возможности его передачи посредством Steam в любой момент времени.",contentEn:"“Inventory” means the Account section and corresponding server-side records through which the Platform displays Items recorded as available to a User until they are used, withdrawn, exchanged, sold through Automatic Sale or otherwise debited or reclassified under this Agreement. Display does not guarantee that an Item can be transferred through Steam at a particular time."},{type:"paragraph",contentRu:"«Вывод» — инициируемая Пользователем посредством предусмотренного Платформой функционала техническая процедура, направленная на передачу соответствующего Предмета на Связанный Steam-аккаунт с использованием доступных технических механизмов Steam и (или) связанных с ним сервисов, при условии соблюдения Пользователем требований настоящего Соглашения, прохождения необходимых проверок и отсутствия технических, правовых, комплаенс-, антифрод-, санкционных или иных ограничений со стороны Оператора, Steam либо соответствующих третьих лиц. Инициирование Вывода не означает гарантии его успешного завершения, если исполнение соответствующей операции зависит от инфраструктуры или действий третьих лиц.",contentEn:"“Withdrawal” means a technical procedure initiated by the User through Platform functionality to transfer an Item to the Linked Steam Account using available Steam mechanisms, subject to this Agreement, required checks and applicable technical, legal, compliance, anti-fraud, sanctions or other restrictions. Initiation does not guarantee completion where execution depends on third-party infrastructure or conduct."},{type:"paragraph",contentRu:"«Связанный Steam-аккаунт» — Steam-аккаунт, посредством которого Пользователь был авторизован на Платформе в момент совершения соответствующей Игровой операции и который информационными системами Платформы был зафиксирован в качестве учетной записи, связанной с Пользователем применительно к Предмету, полученному в результате такой Игровой операции. Если иное прямо не предусмотрено Оператором, изменение Пользователем связанного Steam-аккаунта после получения Предмета не влечет автоматического изменения Steam-аккаунта, на который допускается Вывод такого Предмета.",contentEn:"“Linked Steam Account” - a Steam Account through which the User was authorized on the Platform at the time of the relevant Game Operation and which was recorded by the Platform information systems as an account associated with the User in relation to the Item received as a result of such Game Operation. Unless otherwise expressly provided by the Operator, a change by the User to the associated Steam Account after receiving an Item does not automatically change the Steam Account to which the Withdrawal of such an Item is allowed."},{type:"paragraph",contentRu:"«Автоматическая продажа» — предусмотренная настоящим Соглашением автоматизированная сервисная операция, совершаемая информационными системами Платформы без необходимости получения дополнительного подтверждения Пользователя непосредственно в момент ее совершения, в результате которой Предмет, не выведенный Пользователем в течение установленного Соглашением или интерфейсом Платформы срока, исключается из Инвентаря, прекращает учитываться в нем как доступный для Вывода, а на Внутренний баланс Пользователя зачисляется количество условных единиц, определяемое Платформой в соответствии с применимыми на момент совершения такой операции правилами и параметрами. Применение Автоматической продажи допускается исключительно при условии, что соответствующий механизм и существенные условия его применения были надлежащим образом доведены до сведения Пользователя.",contentEn:"“Automatic Sale” means the automated operation described in this Agreement under which an Item not withdrawn within the prescribed period is removed from the Inventory and the number of notional units determined under the applicable rules is credited to the Internal Balance without further confirmation at execution. The mechanism may be used only if its material terms were properly disclosed."},{type:"paragraph",contentRu:"«Серверные данные» — совокупность формируемых, получаемых, регистрируемых, обрабатываемых и сохраняемых информационными системами Оператора электронных и технических сведений, относящихся к функционированию Платформы и действиям Пользователя, включая журналы событий и операций, уникальные идентификаторы транзакций и запросов, временные метки, сведения о последовательности действий, технические параметры запросов и ответов, данные Аккаунта, сведения о состоянии Внутреннего баланса и Инвентаря, результаты Игровых операций, сведения о технических ошибках и иную информацию, необходимую для функционирования, обеспечения безопасности, аудита и разрешения спорных ситуаций в отношении Платформы.",contentEn:"“Server Data” means electronic and technical information generated, recorded, processed and stored by the Operator's information systems in connection with Platform operations and User actions, including logs, identifiers, timestamps, request and response parameters, Account data, Internal Balance and Inventory status, results and Technical Error information."},{type:"paragraph",contentRu:"«Техническая ошибка» — объективно существующее и подтвержденное Оператором на основании Серверных данных и (или) иных доступных технических сведений нарушение предусмотренного штатного порядка функционирования программного обеспечения, алгоритмов, серверной, сетевой или иной инфраструктуры Платформы, которое непосредственно повлекло дублирование операции, отсутствие ее надлежащего исполнения, некорректное списание или зачисление, искажение результата либо иное технически ошибочное отражение операции в информационных системах Платформы. Само по себе изменение рыночной, расчетной или иной стоимости Предмета, несоответствие полученного результата субъективным ожиданиям Пользователя, отсутствие ожидаемой экономической выгоды, изменение условий или ограничений Steam, временная недоступность стороннего сервиса либо иное обстоятельство, не обусловленное нарушением штатного функционирования Платформы, Технической ошибкой не является.",contentEn:"“Technical Error” means an objectively verifiable departure from the intended operation of the Platform's software, algorithms, servers, network or other infrastructure, confirmed on the basis of Server Data and/or other technical information, that directly causes duplication, non-performance, an incorrect debit or credit, distortion of a result, or another technically incorrect record. A market-value change, an outcome that does not meet subjective expectations, a Steam change or third-party unavailability is not, by itself, a Technical Error."},{type:"paragraph",legalBlock:"applicableLawDef"},{type:"paragraph",contentRu:"Если из контекста настоящего Соглашения прямо не следует иное, термины, производные от приведенных выше определений, подлежат толкованию в значении, соответствующем основному определяемому термину. Технические, коммерческие либо иные обозначения, не получившие самостоятельного определения в настоящем разделе, толкуются с учетом содержания настоящего Соглашения, фактического функционала Платформы и, в применимой части, общепринятого значения соответствующих терминов.",contentEn:"Unless the context of this Agreement clearly indicates otherwise, terms derived from the above definitions shall be construed to have the meaning corresponding to the primary term defined. Technical, commercial or other designations that are not independently defined in this section are interpreted taking into account the content of this Agreement, the actual functionality of the Platform and, to the extent applicable, the generally accepted meaning of the relevant terms."},{type:"subtitle",contentRu:"2. Акцепт Соглашения",contentEn:"2. Acceptance of the Agreement",level:1},{type:"paragraph",contentRu:"2.1. Настоящее Соглашение приобретает обязательную силу для Пользователя с момента совершения им действия, которое в соответствии с применяемым на Платформе интерфейсом и требованиями Применимого законодательства однозначно свидетельствует о принятии условий Соглашения, включая регистрацию Аккаунта, авторизацию на Платформе, проставление соответствующей отметки (флажка) в предусмотренном интерфейсом поле, нажатие кнопки подтверждения, подтверждение отдельной операции, Пополнение Внутреннего баланса, совершение Игровой операции либо продолжение использования Платформы после предоставления Пользователю возможности ознакомиться с актуальной редакцией Соглашения.",contentEn:"2.1. This Agreement becomes binding on the User when the User takes an action that, in the relevant Platform interface and under Applicable Law, clearly signifies acceptance, including registering an Account, authenticating on the Platform, selecting the relevant checkbox, pressing a confirmation button, confirming a transaction, making a Top-Up, performing a Game Operation, or continuing to use the Platform after being given access to the then-current version of this Agreement."},{type:"paragraph",contentRu:"2.2. В случаях, когда Применимое законодательство предусматривает необходимость получения отдельного, явно выраженного согласия Пользователя с условиями настоящего Соглашения либо отдельными его положениями, принятие Соглашения осуществляется исключительно посредством предусмотренного Платформой активного подтверждающего действия, отвечающего требованиям соответствующего законодательства.",contentEn:"2.2. In cases where Applicable Law provides for the need to obtain a separate, explicit consent of the User with the terms of this Agreement or its individual provisions, acceptance of the Agreement is carried out solely through the active confirmation action provided for by the Platform that meets the requirements of the relevant legislation."},{type:"paragraph",contentRu:"2.3. Совершая действие, направленное на принятие настоящего Соглашения, Пользователь заявляет и гарантирует, что до момента такого принятия он получил доступ к полному тексту Соглашения, внимательно ознакомился с его содержанием, понимает юридическую природу возникающих между Сторонами отношений, основные экономические и технические принципы функционирования Платформы, характер Игровых операций и связанные с их совершением последствия.",contentEn:"2.3. By performing an action aimed at accepting this Agreement, the User declares and guarantees that before such acceptance he received access to the full text of the Agreement, carefully read its contents, understands the legal nature of the relations arising between the Parties, the basic economic and technical principles of the functioning of the Platform, the nature of Game Operations and the consequences associated with their implementation."},{type:"paragraph",contentRu:"2.4. Пользователь подтверждает, что до принятия настоящего Соглашения ему была предоставлена разумная и технически доступная возможность ознакомиться с его положениями, отказаться от регистрации и использования Платформы в случае несогласия с ними, а также сохранить, воспроизвести либо иным доступным способом получить копию текста Соглашения для последующего ознакомления.",contentEn:"2.4. The User confirms that before accepting this Agreement, he was given a reasonable and technically accessible opportunity to familiarize himself with its provisions, refuse to register and use the Platform in case of disagreement with them, and also save, reproduce or otherwise obtain a copy of the text of the Agreement for subsequent review."},{type:"paragraph",contentRu:"2.5. Принимая настоящее Соглашение, Пользователь выражает полное, безусловное и безоговорочное согласие соблюдать установленные им условия в течение всего периода использования Платформы, за исключением тех положений, применение которых полностью или частично ограничено либо исключено императивными нормами Применимого законодательства.",contentEn:"2.5. By accepting this Agreement, the User expresses full, unconditional and unreserved agreement to comply with the terms established by him throughout the entire period of use of the Platform, with the exception of those provisions, the application of which is fully or partially limited or excluded by mandatory rules of Applicable Law."},{type:"paragraph",contentRu:"2.6. Пользователь не вправе ссылаться исключительно на фактическое неознакомление с условиями настоящего Соглашения в качестве основания для освобождения от обязательств, возникших вследствие совершенных им после надлежащего предоставления текста Соглашения действий, если иное прямо не предусмотрено Применимым законодательством.",contentEn:"2.6. The User may not rely solely on actual ignorance of the terms of this Agreement as a basis for release from obligations arising as a result of actions taken by him after the proper provision of the text of the Agreement, unless otherwise expressly provided by Applicable Law."},{type:"paragraph",contentRu:"2.7. Использование Платформы, регистрация Аккаунта, Пополнение Внутреннего баланса и совершение Игровых операций допускаются исключительно физическими лицами, достигшими возраста 18 (восемнадцати) лет и обладающими полной дееспособностью, необходимой для самостоятельного заключения и исполнения настоящего Соглашения.",contentEn:"2.7. Only an individual who is at least 18 (eighteen) years old and has the full legal capacity required to enter into and perform this Agreement may use the Platform, register an Account, make a Top-Up or perform a Game Operation."},{type:"paragraph",contentRu:"2.8. Если законодательством государства или территории, нормы которого подлежат обязательному применению к конкретному Пользователю, установлен возраст, превышающий 18 (восемнадцать) лет, для законного использования соответствующих цифровых, развлекательных, игровых либо сопоставимых по своему характеру сервисов или отдельных предусмотренных Платформой механик, минимально допустимым возрастом такого Пользователя признается соответствующий более высокий возраст.",contentEn:"2.8. If the legislation of a state or territory, the norms of which are subject to mandatory application to a specific User, establishes an age exceeding 18 (eighteen) years for the legal use of the relevant digital, entertainment, gaming or comparable services or individual mechanics provided by the Platform, the minimum permissible age of such User is recognized as the corresponding higher age."},{type:"paragraph",contentRu:"2.9. Пользователь заверяет Оператора о том, что на момент регистрации Аккаунта и в течение всего периода использования Платформы он соответствует применимым возрастным требованиям, обладает необходимым объемом дееспособности и вправе самостоятельно, без согласия родителей, опекунов, попечителей или иных законных представителей, заключить настоящее Соглашение и принимать на себя предусмотренные им обязательства.",contentEn:"2.9. The User represents and warrants that, when registering the Account and throughout use of the Platform, the User satisfies all applicable age requirements, has the required legal capacity and may enter into this Agreement and assume its obligations without the consent of a parent, guardian, trustee or other legal representative."},{type:"paragraph",contentRu:"2.10. Лицо, не достигшее минимального возраста, установленного настоящим Соглашением и (или) Применимым законодательством, не вправе регистрировать или использовать Аккаунт, осуществлять Пополнение Внутреннего баланса, совершать Игровые операции, использовать Предметы или иным образом получать доступ к функциональным возможностям Платформы и обязано незамедлительно прекратить использование Сайта.",contentEn:"2.10. A person who has not reached the minimum age established by this Agreement and/or Applicable Law is not entitled to register or use an Account, replenish Internal Balance, make Game Operations, use Items or otherwise access the functionality of the Platform and must immediately stop using the Site."},{type:"paragraph",contentRu:"2.11. Оператор вправе в любое время, в том числе до предоставления доступа к отдельным функциям Платформы либо после начала их использования, запросить у Пользователя сведения и документы, разумно необходимые для подтверждения возраста, личности, дееспособности и соответствия иным установленным настоящим Соглашением критериям допуска.",contentEn:"2.11. The Operator has the right at any time, including before providing access to certain functions of the Platform or after the start of their use, to request from the User information and documents reasonably necessary to confirm age, identity, legal capacity and compliance with other access criteria established by this Agreement."},{type:"paragraph",contentRu:"2.12. Платформа не предназначена для предложения, распространения или использования на территории государств и иных юрисдикций, в которых предоставление либо использование соответствующих функциональных возможностей, включая механики получения заранее неопределенного цифрового результата, совершение Игровых операций, оборот игровых Предметов либо иные предусмотренные Платформой операции, запрещено, существенно ограничено либо требует получения лицензии, разрешения, регистрации, согласования или иного регуляторного статуса, которым Оператор не обладает.",contentEn:"2.12. The Platform is not intended to be offered, distributed or used in any jurisdiction where the relevant functionality, including mechanics generating a digital result not predetermined in advance, Game Operations, transactions in game Items or other Platform operations, is prohibited, materially restricted or requires a license, permit, registration, approval or other regulatory status not held by the Operator."},{type:"paragraph",contentRu:"2.13. Возможность использования Платформы конкретным Пользователем определяется с учетом совокупности применимых к нему правовых требований, включая, в зависимости от обстоятельств, законодательство государства его фактического нахождения, постоянного или временного проживания, гражданства, налогового или иного резидентства, а также требования, связанные с используемым им платежным инструментом и характером конкретной операции.",contentEn:"2.13. The ability to use the Platform by a specific User is determined taking into account the totality of legal requirements applicable to him, including, depending on the circumstances, the legislation of the state of his actual location, permanent or temporary residence, citizenship, tax or other residence, as well as requirements related to the payment instrument used by him and the nature of the specific transaction."},{type:"paragraph",contentRu:"2.14. До регистрации Аккаунта и совершения каждой соответствующей операции Пользователь обязан самостоятельно удостовериться в том, что доступ к Платформе и использование соответствующей функции не запрещены и не ограничены применимыми к нему правовыми нормами, а также что совершение соответствующих действий не требует получения Пользователем или Оператором дополнительного разрешения, отсутствующего на момент совершения операции.",contentEn:"2.14. Before registering an Account and performing each relevant operation, the User must independently verify that access to the Platform and use of the corresponding function are not prohibited or limited by the legal norms applicable to it, and that the performance of the corresponding actions does not require the User or Operator to obtain additional permission that was not available at the time of the operation."},{type:"paragraph",contentRu:"2.15. Оператор не предоставляет Пользователю индивидуальных юридических, налоговых, финансовых или иных профессиональных заключений относительно допустимости использования Платформы на территории конкретной юрисдикции. Размещенная на Платформе информация о территориальной доступности отдельных функций носит общий информационный характер и не освобождает Пользователя от обязанности соблюдать Применимое законодательство.",contentEn:"2.15. The Operator does not provide the User with individual legal, tax, financial or other professional opinions regarding the admissibility of using the Platform in a particular jurisdiction. The information posted on the Platform about the territorial availability of individual functions is of a general informational nature and does not relieve the User of the obligation to comply with the Applicable Law."},{type:"paragraph",contentRu:"2.16. Сам по себе технический доступ Пользователя к Сайту с территории определенного государства или региона, отсутствие автоматической блокировки IP-адреса, возможность регистрации или авторизации, наличие соответствующей языковой версии интерфейса, отображение определенного валютного обозначения, доступность конкретного платежного метода либо возможность инициировать отдельную операцию не являются заверением, гарантией, юридическим заключением или иным подтверждением со стороны Оператора того, что использование Платформы соответствующим Пользователем является безусловно законным в соответствующей юрисдикции.",contentEn:"2.16. In itself, the User’s technical access to the Site from the territory of a certain state or region, the absence of automatic blocking of the IP address, the possibility of registration or authorization, the presence of an appropriate language version of the interface, the display of a certain currency symbol, the availability of a specific payment method or the ability to initiate a separate transaction does not constitute a representation, guarantee, legal opinion or other confirmation on the part of the Operator that the use of the Platform by the relevant User is unconditionally legal in the relevant jurisdiction."},{type:"paragraph",contentRu:"2.17. Пользователю запрещается предпринимать действия, направленные на обход установленных Оператором или третьими лицами возрастных, территориальных, санкционных, комплаенс-, платежных, антифрод- либо иных ограничений доступа к Платформе или отдельным ее функциям.",contentEn:"2.17. The User is prohibited from taking actions aimed at circumventing age, territorial, sanctions, compliance, payment, anti-fraud or other restrictions on access to the Platform or its individual functions established by the Operator or third parties."},{type:"paragraph",contentRu:"2.18. В частности, Пользователю запрещается использовать VPN-сервисы, прокси-серверы, средства подмены или маскирования IP-адреса, технологии изменения либо фальсификации геолокационных данных, учетные данные третьих лиц, фиктивные сведения о месте проживания или нахождения, а равно иные программные, технические или организационные средства, если целью либо фактическим результатом их использования является сокрытие действительного местонахождения Пользователя или обход применимых к нему ограничений.",contentEn:"2.18. In particular, the User is prohibited from using VPN services, proxy servers, means of substituting or masking the IP address, technologies for changing or falsifying geolocation data, credentials of third parties, fictitious information about the place of residence or location, as well as other software, technical or organizational means, if the purpose or actual result of their use is to hide the actual location of the User or bypass the restrictions applicable to him."},{type:"paragraph",contentRu:"2.19. Оператор вправе использовать технические и организационные средства определения и проверки территориальной допустимости обслуживания Пользователя, включая анализ IP-адресов, геолокационных и иных технических признаков, сведений о платежных инструментах, результатов идентификационных и верификационных процедур, а также иные риск-ориентированные методы в объеме, допускаемом Применимым законодательством и документами Оператора о защите персональных данных.",contentEn:"2.19. The Operator may use technical and organizational means of determining and verifying the territorial acceptability of the User’s service, including analysis of IP addresses, geolocation and other technical characteristics, information about payment instruments, results of identification and verification procedures, as well as other risk-based methods to the extent permitted by the Applicable Law and the Operator’s documents on the protection of personal data."},{type:"paragraph",contentRu:"2.20. Оператор вправе вводить, изменять, расширять, сокращать или отменять перечни территорий и категорий Пользователей, для которых использование Платформы или отдельных ее функций ограничено, если соответствующие меры обусловлены требованиями законодательства, регуляторными рисками, санкционными ограничениями, требованиями платежных организаций или иных контрагентов, предотвращением злоупотреблений либо иными обоснованными правовыми, техническими или коммерческими обстоятельствами.",contentEn:"2.20. The Operator may introduce, change, expand, reduce or cancel the lists of territories and categories of Users for which the use of the Platform or its individual functions is limited, if the appropriate measures are determined by legal requirements, regulatory risks, sanction restrictions, requirements of payment organizations or other counterparties, prevention of abuse or other justified legal, technical or commercial circumstances."},{type:"paragraph",contentRu:"2.21. В случае невозможности достоверно установить возраст Пользователя, его личность, место нахождения, страну проживания, применимый к нему правовой режим либо иные обстоятельства, имеющие существенное значение для определения допустимости предоставления соответствующей функции, Оператор вправе временно ограничить или приостановить доступ к отдельным операциям до завершения необходимых проверочных мероприятий.",contentEn:"2.21. If it is impossible to reliably establish the User’s age, identity, location, country of residence, the legal regime applicable to him or other circumstances that are significant for determining the admissibility of providing the corresponding function, the Operator may temporarily limit or suspend access to certain operations until the completion of the necessary verification measures."},{type:"paragraph",contentRu:"2.22. Если после начала использования Платформы соответствующая деятельность становится запрещенной или ограниченной применительно к Пользователю вследствие изменения законодательства, регуляторной практики, санкционного режима, территориальной политики Оператора либо иных юридически значимых обстоятельств, Пользователь обязан незамедлительно прекратить инициирование новых операций, использование ограниченных функций и любые действия, противоречащие соответствующим требованиям.",contentEn:"2.22. If, after starting to use the Platform, the corresponding activity becomes prohibited or limited in relation to the User due to changes in legislation, regulatory practice, sanctions regime, territorial policy of the Operator or other legally significant circumstances, the User shall immediately stop initiating new operations, using limited functions and any actions that contradict the relevant requirements."},{type:"paragraph",contentRu:"2.23. При возникновении обстоятельств, предусмотренных пунктом 2.22 настоящего Соглашения, порядок урегулирования ранее сформированного Внутреннего баланса, Предметов, незавершенных операций и иных существующих на момент введения ограничения учетных позиций определяется Оператором с учетом требований Применимого законодательства, технической возможности исполнения соответствующих действий, обязательных требований платежных организаций, Steam и иных третьих лиц, а также необходимости проведения предусмотренных законом или настоящим Соглашением проверок.",contentEn:"2.23. If the circumstances provided for in clause 2.22 of this Agreement arise, the procedure for settling the previously formed Internal Balance, Items, unfinished transactions and other accounting positions existing at the time of introduction of the limitation is determined by the Operator, taking into account the requirements of Applicable Law, the technical feasibility of performing the relevant actions, the mandatory requirements of payment organizations, Steam and other third parties, as well as the need to carry out checks provided for by law or this Agreement."},{type:"paragraph",contentRu:"2.24. Прекращение или ограничение доступа Пользователя к Платформе по территориальным, возрастным, санкционным, комплаенс- либо иным предусмотренным настоящим Соглашением основаниям не означает автоматического возникновения у Пользователя права требовать совершения технически невозможной, запрещенной законом или ограниченной третьими лицами операции.",contentEn:"2.24. Termination or restriction of the User's access to the Platform on territorial, age, sanctions, compliance or other grounds provided for in this Agreement does not automatically mean that the User may demand the performance of a technically impossible operation, prohibited by law or limited by third parties."},{type:"paragraph",contentRu:"2.25. Платформа предназначена исключительно для личного некоммерческого использования Пользователем, если иное предварительно и прямо не согласовано с Оператором в письменной форме.",contentEn:"2.25. The Platform is intended solely for personal, non-commercial use by the User, unless otherwise previously and expressly agreed upon in writing by the Operator."},{type:"paragraph",contentRu:"2.26. Без предварительного письменного согласия Оператора Пользователю запрещается использовать Платформу в рамках предпринимательской или иной профессиональной деятельности, включая систематическую перепродажу Предметов, управление денежными средствами, Внутренним балансом, Аккаунтами или Предметами третьих лиц, оказание посреднических, агентских, доверительных или аналогичных услуг, организацию коллективного использования Аккаунта либо осуществление иной деятельности, направленной на систематическое извлечение дохода посредством функциональных возможностей Платформы.",contentEn:"2.26. Without the prior written consent of the Operator, the User is prohibited from using the Platform as part of business or other professional activities, including the systematic resale of Items, management of funds, Internal Balance, Accounts or Items of third parties, provision of intermediary, agency, trust or similar services, organization of collective use of the Account, or carrying out other activities aimed at systematically generating income through the functionality of the Platform."},{type:"paragraph",contentRu:"2.27. Оператор вправе до или после предоставления Пользователю доступа к отдельной функции запросить документы, сведения и пояснения, разумно необходимые для подтверждения личности, возраста, страны проживания или нахождения Пользователя, принадлежности используемых платежных инструментов, экономического характера совершаемых операций, источника происхождения денежных средств и (или) иных активов, а также иных обстоятельств, проверка которых необходима для исполнения требований Применимого законодательства, настоящего Соглашения, AML/KYC-политики либо внутренних процедур управления рисками Оператора.",contentEn:"2.27. The Operator has the right, before or after providing the User with access to a particular function, to request documents, information and explanations reasonably necessary to confirm the identity, age, country of residence or location of the User, the ownership of the payment instruments used, the economic nature of the transactions performed, the source of funds and/or other assets, as well as other circumstances, the verification of which is necessary to comply with the requirements of the Applicable Law, this Agreement, the AML/KYC policy or the Operator’s internal risk management procedures."},{type:"paragraph",contentRu:"2.28. Пользователь обязан предоставлять запрошенные в соответствии с настоящим Соглашением сведения и документы в достоверном, актуальном, полном и неискаженном виде и не вправе предоставлять заведомо ложную, вводящую в заблуждение либо относящуюся к третьему лицу информацию с целью прохождения соответствующей проверки.",contentEn:"2.28. The User shall provide the information and documents requested in accordance with this Agreement in a true, current, complete and undistorted form and has no right to provide knowingly false, misleading or information related to a third party in order to undergo the appropriate verification."},{type:"paragraph",contentRu:"2.29. Непредоставление Пользователем разумно запрошенных сведений или документов, предоставление неполной либо противоречивой информации, невозможность подтвердить ее достоверность, а также выявление обстоятельств, требующих дополнительной проверки, могут являться основанием для временного приостановления отдельных операций, ограничения функциональных возможностей Аккаунта либо отказа в совершении конкретной операции до завершения соответствующей проверки в пределах, допускаемых Применимым законодательством.",contentEn:"2.29. Failure by the User to provide reasonably requested information or documents, provision of incomplete or contradictory information, failure to confirm its accuracy, as well as identification of circumstances requiring additional verification, may be grounds for temporary suspension of certain transactions, limitation of the functionality of the Account, or refusal to perform a specific transaction until the completion of the relevant verification to the extent permitted by Applicable Law."},{type:"paragraph",contentRu:"2.30. Пользователь самостоятельно несет ответственность за соблюдение применимых к нему требований законодательства при использовании Платформы. При этом никакое положение настоящего раздела не освобождает Оператора от соблюдения тех обязанностей и ограничений, которые непосредственно возложены на него императивными нормами Применимого законодательства и не могут быть переложены на Пользователя соглашением Сторон.",contentEn:"2.30. The User is solely responsible for compliance with applicable legal requirements when using the Platform. However, no provision of this section relieves the Operator from compliance with those obligations and restrictions that are directly assigned to him by the mandatory rules of Applicable Law and cannot be transferred to the User by agreement of the Parties."},{type:"subtitle",contentRu:"3. Аккаунт и безопасность доступа",contentEn:"3. Account and Access Security",level:1},{type:"paragraph",contentRu:"3.1. Для получения доступа к основным функциональным возможностям Платформы Пользователь обязан пройти авторизацию посредством принадлежащего ему Steam-аккаунта в порядке, предусмотренном соответствующим интерфейсом. Если иное предварительно и прямо не разрешено Оператором в письменной форме, одному Пользователю допускается создание и использование исключительно одного Аккаунта. Создание, регистрация, фактическое использование или контроль нескольких Аккаунтов одним Пользователем, в том числе посредством различных Steam-аккаунтов, устройств, IP-адресов или иных технических средств, может рассматриваться Оператором как нарушение настоящего Соглашения.",contentEn:"3.1. To access the Platform's principal functionality, the User shall authenticate through the User's Steam Account using the applicable interface. Unless the Operator expressly authorizes otherwise in writing in advance, each User may create and use only one Account. Creating, registering, using or controlling multiple Accounts, including through different Steam Accounts, devices, IP addresses or other technical means, may be treated as a breach of this Agreement."},{type:"paragraph",contentRu:"3.2. Аккаунт имеет индивидуальный и персональный характер и предназначен исключительно для использования Пользователем, которому он принадлежит. Пользователю запрещается продавать, отчуждать, передавать, предоставлять во временное пользование, совместно использовать Аккаунт с третьими лицами либо иным образом предоставлять третьим лицам возможность осуществлять действия от имени Пользователя, включая передачу идентификаторов сессии, токенов, ссылок подтверждения, кодов авторизации и иных технических средств доступа. Пользователь обязан использовать исключительно тот Steam-аккаунт, законным владельцем и фактически контролирующим лицом которого он является; Оператор вправе запросить разумно необходимые сведения и доказательства, подтверждающие соответствующий контроль.",contentEn:"3.2. The Account is personal to the User and may be used only by that User. The User may not sell, assign, transfer, lend or share the Account, or allow a third party to act through it, including by sharing session identifiers, tokens, confirmation links, authorization codes or other access credentials. The User shall use only a Steam Account that the User lawfully owns and controls."},{type:"paragraph",contentRu:"3.3. Идентификатор Steam и иные технические сведения, зафиксированные Серверными данными при авторизации Пользователя, совершении Игровой операции или осуществлении иного юридически либо технически значимого действия, используются Оператором для установления связи между Пользователем, его Аккаунтом, совершенными Игровыми операциями, полученными Предметами, Инвентарем и заявками на Вывод. Если иное прямо не предусмотрено функционалом Платформы, соответствующие Серверные данные являются основанием для определения того, к какому Аккаунту и Steam-аккаунту относится конкретная операция.",contentEn:"3.3. The Steam ID and other technical information recorded by Server Data when authorizing the User, performing a Game Operation or performing another legally or technically significant action are used by the Operator to establish a connection between the User, his Account, completed Game Operations, received Items, Inventory and withdrawal requests. Unless otherwise expressly provided for by the functionality of the Platform, the corresponding Server Data is the basis for determining which Account and Steam Account a specific operation relates to."},{type:"paragraph",contentRu:"3.4. Пользователь обязан самостоятельно обеспечивать конфиденциальность и безопасность всех средств, посредством которых может быть получен доступ к Аккаунту, Steam-аккаунту или связанным с ними функциям, включая устройства, учетные данные Steam, электронную почту, средства двухфакторной аутентификации, платежные инструменты, активные пользовательские сессии и иные идентификационные или аутентификационные данные. При возникновении обоснованного подозрения в отношении утраты устройства, компрометации учетных данных, несанкционированного доступа либо совершения действий третьим лицом Пользователь обязан незамедлительно уведомить об этом Оператора посредством предусмотренных Платформой каналов связи.",contentEn:"3.4. The User is responsible for ensuring the confidentiality and security of all means through which the Account, Steam Account or related functions can be accessed, including devices, Steam credentials, email, two-factor authentication, payment instruments, active user sessions and other identification or authentication data. If there is a reasonable suspicion regarding the loss of a device, compromise of credentials, unauthorized access, or the commission of actions by a third party, the User shall immediately notify the Operator about this through the communication channels provided by the Platform."},{type:"paragraph",contentRu:"3.5. До момента фактического получения Оператором уведомления Пользователя о предполагаемой компрометации доступа действия, совершенные после успешного прохождения предусмотренной Платформой процедуры авторизации и подтвержденные Серверными данными, презюмируются совершенными Пользователем либо с его ведома и согласия, если иное не установлено на основании совокупности объективных обстоятельств. Настоящее положение не применяется в той мере, в которой соответствующая презумпция или возложение риска на Пользователя противоречили бы императивным нормам Применимого законодательства.",contentEn:"3.5. Until the Operator actually receives a notification from the User about the alleged compromise of access, actions taken after successful completion of the authorization procedure provided for by the Platform and confirmed by Server Data are presumed to have been committed by the User or with his knowledge and consent, unless otherwise established on the basis of a set of objective circumstances. This provision does not apply to the extent that the corresponding presumption or the assignment of risk to the User would be contrary to the mandatory rules of Applicable Law."},{type:"paragraph",contentRu:"3.6. В целях обеспечения безопасности Пользователя и Платформы, предотвращения мошенничества, несанкционированного доступа и иных злоупотреблений Оператор вправе временно ограничить отдельные функции Аккаунта, приостановить совершение Игровых операций и (или) Вывод, а также потребовать прохождения дополнительной проверки при выявлении нетипичной смены географического местоположения, устройства или сетевых параметров, существенного изменения платежного поведения, использования иного Steam-аккаунта, множественных неуспешных попыток авторизации, признаков использования нескольких Аккаунтов либо иных обстоятельств, объективно указывающих на повышенный риск компрометации или нарушения настоящего Соглашения.",contentEn:"3.6. In order to ensure the safety of the User and the Platform, prevent fraud, unauthorized access and other abuses, the Operator may temporarily limit certain functions of the Account, suspend Game Operations and/or Withdrawal, and also require additional verification if an atypical change in geographic location, device or network parameters is detected, a significant change in payment behavior, the use of a different Steam Account, multiple unsuccessful authorization attempts, signs of the use of multiple Accounts or other circumstances, objectively indicating an increased risk of compromise or violation of this Agreement."},{type:"paragraph",contentRu:"3.7. Восстановление доступа к Аккаунту, снятие защитных ограничений и подтверждение полномочий Пользователя осуществляются в соответствии с установленными Оператором процедурами безопасности и могут предусматривать проверку Steam-профиля, истории авторизаций и операций, сведений о ранее использованных платежных инструментах, технических параметров устройств, документов, подтверждающих личность, и иных разумно необходимых сведений. Оператор вправе не восстанавливать полный доступ до момента получения достаточных оснований полагать, что Аккаунт возвращается под контроль надлежащего Пользователя.",contentEn:"3.7. Restoring access to the Account, removing security restrictions and confirming the User's authority are carried out in accordance with the security procedures established by the Operator and may include checking the Steam profile, history of authorizations and transactions, information about previously used payment instruments, technical parameters of devices, identity documents, and other reasonably necessary information. The Operator has the right not to restore full access until it receives sufficient grounds to believe that the Account is returned to the control of the proper User."},{type:"paragraph",contentRu:"3.8. Steam-аккаунт, зафиксированный Серверными данными как Связанный Steam-аккаунт применительно к конкретному Предмету или Игровой операции, не подлежит последующей замене исключительно по инициативе Пользователя в отношении уже полученных Предметов. Изменение способа авторизации или связанного Steam-аккаунта, если такая возможность технически предусмотрена Платформой и разрешена Оператором, распространяется исключительно на будущие операции и не влечет изменения ранее сформированных Серверных данных, принадлежности результатов совершенных операций либо реквизитов, установленных для Вывода ранее полученных Предметов.",contentEn:"3.8. A Steam Account recorded by Server Data as a Linked Steam Account in relation to a specific Item or Game Operation is not subject to subsequent replacement solely at the initiative of the User in relation to Items already received. Changing the authorization method or the associated Steam Account, if such a possibility is technically provided by the Platform and authorized by the Operator, applies exclusively to future operations and does not entail changes in previously generated Server Data, ownership of the results of completed operations or details established for the Withdrawal of previously received Items."},{type:"paragraph",contentRu:"3.9. До подтверждения каждой Игровой операции Пользователь обязан самостоятельно проверить корректность Steam-аккаунта, посредством которого осуществлена текущая авторизация. Совершение Игровой операции после ошибочной авторизации посредством иного Steam-аккаунта само по себе не возлагает на Оператора обязанность изменять Связанный Steam-аккаунт, переносить Предметы, Внутренний баланс, результаты Игровых операций или иные учетные позиции между Аккаунтами, если такой перенос не предусмотрен функционалом Платформы или обязательными требованиями Применимого законодательства.",contentEn:"3.9. Before confirming each Game Operation, the User shall independently verify the correctness of the Steam Account through which the current authorization was carried out. Performing a Game Operation after an erroneous authorization through another Steam Account does not in itself impose on the Operator the obligation to change the Linked Steam Account, transfer Items, Internal Balance, Game Operations results or other accounting positions between Accounts, unless such transfer is provided for by the functionality of the Platform or the mandatory requirements of the Applicable Law."},{type:"paragraph",contentRu:"3.10. Оператор вправе в целях информационной безопасности, предотвращения злоупотреблений, соблюдения установленных лимитов и ограничений, проведения AML/KYC- и антифрод-проверок, а также расследования предполагаемых нарушений настоящего Соглашения сопоставлять и совместно анализировать сведения об Аккаунтах, имеющих объективные признаки технической, платежной или иной связи. Установление такой связи не влечет обязанности Оператора объединять Аккаунты, Внутренние балансы, Инвентари, Предметы либо иные учетные позиции соответствующих лиц.",contentEn:"3.10. The Operator has the right, for the purposes of information security, prevention of abuse, compliance with established limits and restrictions, conducting AML/KYC and anti-fraud checks, as well as investigation of alleged violations of this Agreement, to compare and jointly analyze information about Accounts that have objective signs of a technical, payment or other connection. The establishment of such a connection does not entail the obligation of the Operator to combine Accounts, Internal Balances, Inventory, Items or other accounting positions of the relevant persons."},{type:"paragraph",contentRu:"3.11. Создание или использование нового Аккаунта после временного ограничения, блокировки или прекращения ранее использовавшегося Пользователем Аккаунта без предварительного письменного разрешения Оператора рассматривается как обход примененной меры и является самостоятельным нарушением настоящего Соглашения. В таком случае Оператор вправе применить к вновь выявленному Аккаунту ограничения, предусмотренные настоящим Соглашением, с учетом характера нарушения, результатов проведенной проверки и требований Применимого законодательства.",contentEn:"3.11. The creation or use of a new Account after temporary restriction, blocking or termination of the Account previously used by the User without the prior written permission of the Operator is considered as a circumvention of the applied measure and is an independent violation of this Agreement. In this case, the Operator may apply to the newly identified Account the restrictions provided for in this Agreement, taking into account the nature of the violation, the results of the verification and the requirements of Applicable Law."},{type:"paragraph",contentRu:"3.12. Пользователь обязан обеспечивать достоверность и актуальность предоставленных Оператору контактных и иных сведений и своевременно актуализировать их при наличии соответствующей технической возможности. Риск неполучения уведомлений вследствие предоставления Пользователем недостоверных или неактуальных сведений несет Пользователь, за исключением случаев, когда Применимое законодательство прямо возлагает соответствующий риск или обязанность надлежащей доставки на Оператора. Оператор не запрашивает у Пользователя пароль от Steam; передача Пользователем третьим лицам пароля, кодов двухфакторной аутентификации, токенов, кодов подтверждения либо иных конфиденциальных средств полного доступа к Steam-аккаунту осуществляется с нарушением требований безопасности и может являться основанием для применения Оператором временной защитной блокировки до выяснения обстоятельств и подтверждения надлежащего контроля над Аккаунтом.",contentEn:"3.12. The User shall keep contact and other information provided to the Operator accurate and current whenever the Platform permits it to be updated. The User bears the risk of not receiving a notice because inaccurate or outdated information was provided, except where Applicable Law allocates that risk or the delivery obligation to the Operator. The Operator never requests the User's Steam password. Sharing a password, two-factor authentication code, token, confirmation code or other credential granting full Steam Account access breaches security requirements and may result in a temporary protective restriction pending verification of proper control."},{type:"subtitle",contentRu:"4. Кейсы и формирование игрового результата",contentEn:"4. Cases and Determination of Game Results",level:1},{type:"paragraph",contentRu:"4.1. Открытие Кейса является Игровой операцией, предполагающей получение Пользователем заранее индивидуально не определенного цифрового результата из совокупности результатов, предусмотренных для соответствующего Кейса. До момента подтверждения такой Игровой операции Пользователь обязан самостоятельно ознакомиться с отображаемой в интерфейсе стоимостью Кейса, перечнем возможных результатов и иной доступной информацией, имеющей значение для принятия решения о совершении операции. Сам факт отображения определенного Предмета в составе возможных результатов, его визуальное выделение, редкость, предполагаемая ценность либо иные характеристики не являются заверением, обещанием или гарантией получения такого Предмета конкретным Пользователем.",contentEn:"4.1. Opening a Case is a Game Operation through which the User receives one digital result from the set of possible results assigned to that Case, with the particular result not predetermined for the User. Before confirmation, the User shall review the displayed Case price, possible results and other material information. Display, visual emphasis, rarity or perceived value of an Item does not guarantee that it will be received."},{type:"paragraph",contentRu:"4.2. Результат открытия Кейса формируется посредством программно-технических средств Платформы и после подтверждения соответствующей Игровой операции фиксируется в Серверных данных Оператора. Для целей определения факта совершения операции и полученного результата юридически и технически значимыми являются Серверные данные, подтверждающие списание предусмотренной стоимости Игровой операции и формирование соответствующего результата, если иное не установлено в результате подтвержденной Технической ошибки. Используемые в интерфейсе визуальные эффекты, анимация открытия Кейса, графические изображения, звуковое сопровождение и иные элементы отображения носят исключительно интерфейсный характер и сами по себе не определяют и не изменяют сформированный результат.",contentEn:"4.2. The Platform's software and hardware generate the result of opening a Case and record it in Server Data after confirmation. Server Data determines whether the operation occurred, the amount debited and the result generated, unless a confirmed Technical Error establishes otherwise. Animation, graphics, sound and other interface elements do not determine or alter the result."},{type:"paragraph",contentRu:"4.3. Если точные вероятности получения отдельных Предметов не отображаются Пользователю в интерфейсе Платформы, отсутствие соответствующей информации не может толковаться как установление равной вероятности получения каждого из возможных результатов, обещание определенной частоты выпадения Предметов, гарантия получения Предмета конкретной категории или стоимости либо гарантия какого-либо соотношения между стоимостью Кейса и стоимостью полученного Предмета. Если раскрытие конкретных вероятностей либо иной информации о механизме формирования результата является обязательным требованием Применимого законодательства, соответствующая Игровая операция не должна предоставляться Пользователю до раскрытия обязательной информации; Оператор вправе полностью или частично ограничить доступ к такой функции для соответствующей юрисдикции.",contentEn:"4.3. If exact probabilities for individual Items are not displayed, that absence does not imply equal probability, promise a particular drop frequency, guarantee an Item of a given category or value, or guarantee any relationship between the Case price and Item value. Where Applicable Law requires disclosure, the Game Operation shall not be made available before the required information is disclosed."},{type:"paragraph",contentRu:"4.4. Прерывание или некорректное отображение визуальной части Игровой операции, включая остановку или ускорение анимации, обновление страницы, закрытие браузера или приложения, переход на другую страницу, прекращение пользовательской сессии, временную потерю интернет-соединения, задержку загрузки интерфейса либо иной сбой на стороне отображения, само по себе не отменяет и не аннулирует Игровую операцию, если Серверные данные достоверно подтверждают корректное списание ее стоимости и надлежащее формирование результата. До момента фиксации такого результата Пользователь не приобретает права требовать предоставления какого-либо конкретного Предмета.",contentEn:"4.4. Interruption or incorrect display of the visual component does not cancel or invalidate a Game Operation if Server Data confirms the correct debit and generation of the result. Until the result is recorded, the User may not demand any particular Item."},{type:"paragraph",contentRu:"4.5. Пользователь осознает и принимает, что стоимость, оценочная ценность, востребованность, редкость и иные экономически значимые характеристики Предмета, полученного в результате открытия Кейса, могут существенно отличаться от стоимости соответствующей Игровой операции, в том числе быть ниже, равными или выше стоимости Кейса. Совершая Игровую операцию, Пользователь принимает присущий соответствующей механике риск получения результата, экономическая ценность которого может оказаться ниже понесенных Пользователем затрат, и, за исключением случаев Технической ошибки либо иных прямо предусмотренных Применимым законодательством оснований, не вправе требовать от Оператора доплаты разницы до стоимости Кейса, замены полученного Предмета, повторного формирования результата, компенсации предполагаемой или ожидаемой стоимости либо возмещения вследствие несоответствия результата субъективным ожиданиям Пользователя. Оператор не предоставляет заверений или прогнозов относительно текущей либо будущей рыночной стоимости Предметов.",contentEn:"4.5. The User accepts that the value, demand, rarity and other economic characteristics of an Item obtained from a Case may be materially lower than, equal to or higher than the Case price. Except in the event of a Technical Error or another right under Applicable Law, the User may not demand payment of a difference, replacement, regeneration or compensation because the outcome did not meet expectations."},{type:"paragraph",contentRu:"4.6. Оператор вправе изменять применительно исключительно к будущим Игровым операциям стоимость Кейсов, состав и характеристики возможных результатов, визуальное оформление, функциональные параметры и иные условия соответствующей игровой механики. Такие изменения не распространяются на надлежащим образом завершенные Игровые операции, за исключением случаев необходимости устранения последствий доказанной Технической ошибки или исполнения обязательных требований Применимого законодательства. Если до окончательного завершения Игровой операции сведения, отображаемые в пользовательском интерфейсе, объективно расходятся с Серверными данными, Оператор вправе приостановить соответствующую операцию для проведения проверки и, исходя из ее результатов, восстановить списанные условные единицы на Внутреннем балансе либо исполнить операцию на условиях, достоверно зафиксированных Серверными данными и надлежащим образом доведенных до Пользователя до момента подтверждения операции.",contentEn:"4.6. For future Game Operations, the Operator may change Case prices, possible results, visual design, functional parameters and other conditions. A change does not affect a properly completed operation except as necessary to remedy a confirmed Technical Error or comply with Applicable Law."},{type:"paragraph",contentRu:"4.7. В отношении отдельных Кейсов, специальных режимов, рекламных, бонусных или иных мероприятий Оператор вправе устанавливать дополнительные условия и специальные правила, которые становятся обязательными для Пользователя при условии предоставления ему возможности ознакомиться с ними до подтверждения соответствующей Игровой операции. Сведения о ранее полученных результатах Пользователя или третьих лиц, ленты выпадений, счетчики, статистические показатели, рекламные и демонстрационные материалы, примеры получения Предметов и иная информация о предыдущих Игровых операциях не являются индивидуальным прогнозом, заверением или гарантией результата последующей Игровой операции. Пользователь не вправе использовать функционал Кейсов в качестве заявленного Оператором способа получения гарантированного дохода, ценового арбитража или осуществления профессиональной торговли Предметами.",contentEn:"4.7. The Operator may establish additional terms for particular Cases, modes, promotions, Bonuses or other campaigns, provided they are available before confirmation. Previous results, live drop feeds, counters, statistics, advertising, demonstrations and examples do not predict, represent or guarantee a later result. The Operator does not market Case functionality as a means of guaranteed income, price arbitrage or professional Item trading."},{type:"paragraph",contentRu:"4.8. При наличии объективных оснований полагать, что результат Игровой операции был сформирован, изменен, продублирован либо получен вследствие Технической ошибки, программного или технического вмешательства, повторной передачи запроса, несанкционированного воздействия на Платформу, использования ошибки программного обеспечения, эксплуатации уязвимости либо иных действий, нарушающих штатный порядок функционирования Платформы, Оператор вправе временно приостановить Вывод, обмен, Автоматическую продажу или иное распоряжение соответствующим Предметом на период, разумно необходимый для проведения технической проверки. По результатам такой проверки Оператор вправе применить последствия, предусмотренные настоящим Соглашением и Применимым законодательством, включая восстановление корректного состояния учетных данных, отмену ошибочно продублированного результата или возврат неправомерно списанных условных единиц, при этом такие меры не должны использоваться для произвольного изменения результата корректно завершенной Игровой операции.",contentEn:"4.8. If objective grounds indicate that a Game Operation result was generated, altered, duplicated or obtained because of a Technical Error, software or technical interference, retransmitted request, unauthorized impact, software defect, exploited vulnerability or other disruption, the Operator may temporarily restrict disposal while it reviews the event. It may restore the correct accounting position, cancel an erroneous duplicate or return an improper debit, but shall not arbitrarily alter a correctly completed result."},{type:"subtitle",contentRu:"5. Игровые функции",contentEn:"5. Game Features",level:1},{type:"paragraph",contentRu:"5.1. Существенные параметры Апгрейда, включая используемый Пользователем Предмет или совокупность Предметов, количество подлежащих использованию условных единиц Внутреннего баланса, целевой Предмет, а также иные предусмотренные соответствующей игровой механикой характеристики и условия, отображаются в интерфейсе Платформы до момента окончательного подтверждения Игровой операции. Пользователь обязан самостоятельно проверить указанные параметры до совершения подтверждающего действия; продолжение операции после предоставления соответствующей информации означает согласие Пользователя с отображенными применительно к такой операции условиями.",contentEn:"5.1. The Platform interface displays the material parameters of an Upgrade before final confirmation, including the Item or Items used, the number of notional units of the Internal Balance to be used, the target Item and other applicable characteristics and conditions. The User shall verify those parameters before confirming the operation; proceeding after they are displayed constitutes agreement to the terms shown for that operation."},{type:"paragraph",contentRu:"5.2. Подтверждая Апгрейд, Пользователь дает Оператору безотзывное, в пределах соответствующей Игровой операции, поручение осуществить списание выбранных и отображенных в интерфейсе Предметов и (или) соответствующего количества условных единиц Внутреннего баланса в целях формирования результата Апгрейда в соответствии с параметрами, действующими и доведенными до сведения Пользователя на момент подтверждения операции. После надлежащего формирования результата такое списание считается окончательным, за исключением случаев подтвержденной Технической ошибки либо иных оснований, прямо предусмотренных Применимым законодательством.",contentEn:"5.2. By confirming the Upgrade, the User gives the Operator an irrevocable, within the relevant Game Operation, instruction to write off the Items selected and displayed in the interface and/or the corresponding number of Internal Balance units in order to generate the result of the Upgrade in accordance with the parameters in force and communicated to the User at the time of confirmation of the operation. After proper formation of the result, such a write-off is considered final, except in cases of a confirmed Technical Error or other grounds expressly provided for by Applicable Law."},{type:"paragraph",contentRu:"5.3. Пользователь осознает и принимает, что Апгрейд может завершиться как получением предусмотренного соответствующей механикой целевого Предмета, так и иным результатом, включая результат, при котором использованный для совершения Апгрейда Предмет прекращает учитываться в Инвентаре без предоставления целевого Предмета, если именно такой результат предусмотрен правилами соответствующей функции. Наступление неуспешного или экономически неблагоприятного для Пользователя результата при условии корректного функционирования Платформы не является Технической ошибкой и само по себе не предоставляет Пользователю права требовать восстановления использованного Предмета, возврата условных единиц, повторного совершения операции, замены результата или выплаты какой-либо компенсации.",contentEn:"5.3. The User understands and accepts that the Upgrade can be completed either by receiving the target Item provided for by the relevant mechanics, or by another result, including the result in which the Item used to perform the Upgrade ceases to be taken into account in the Inventory without providing the target Item, if such a result is provided for by the rules of the corresponding function. The occurrence of an unsuccessful or economically unfavorable result for the User, provided that the Platform is functioning correctly, is not a Technical Error and does not in itself provide the User with the right to demand restoration of the used Item, return of notional units, repeated operation, replacement of the result or payment of any compensation."},{type:"paragraph",contentRu:"5.4. Если применительно к конкретному Апгрейду или иной Игровой операции интерфейс Платформы предусматривает отображение числового, процентного или иного показателя вероятности наступления определенного результата, такой показатель относится исключительно к конкретной операции и параметрам, сформированным непосредственно перед ее подтверждением Пользователем. Указанный показатель не является обещанием фактического наступления соответствующего результата, не создает гарантии успешного завершения операции и не определяет результат любых предыдущих или последующих Игровых операций. Каждая соответствующая операция рассматривается самостоятельно в соответствии с параметрами, применимыми на момент ее подтверждения.",contentEn:"5.4. If, in relation to a specific Upgrade or other Game Operation, the Platform interface provides for the display of a numerical, percentage or other indicator of the probability of a certain result occurring, such an indicator relates exclusively to the specific operation and parameters generated immediately before its confirmation by the User. The indicated indicator is not a promise of the actual occurrence of the corresponding result, does not create a guarantee of successful completion of the operation and does not determine the result of any previous or subsequent Game Operations. Each relevant transaction is considered independently in accordance with the parameters applicable at the time of its confirmation."},{type:"paragraph",contentRu:"5.5. Контракт считается инициированным и подтвержденным Пользователем после выбора предусмотренного интерфейсом количества допустимых Предметов, ознакомления с отображаемыми параметрами и совершения предусмотренного Платформой подтверждающего действия. После корректного формирования результата Контракта использованные для его совершения Предметы окончательно списываются из Инвентаря и прекращают быть доступными для Вывода, обмена, Автоматической продажи, повторного использования либо совершения иных операций. Получение результата Контракта не влечет возникновения у Пользователя права требовать возврата ранее использованных Предметов, кроме случаев подтвержденной Технической ошибки или наличия соответствующей обязанности в силу Применимого законодательства.",contentEn:"5.5. The Contract is considered initiated and confirmed by the User after selecting the number of acceptable Items provided for by the interface, familiarizing with the displayed parameters and performing the confirmatory action provided for by the Platform. After the correct formation of the result of the Contract, the Items used to complete it are finally written off from the Inventory and cease to be available for Withdrawal, exchange, Automatic Sale, reuse or other operations. Receipt of the Contract result does not give rise to the User's right to demand the return of previously used Items, except in cases of a confirmed Technical Error or the presence of a corresponding obligation by virtue of Applicable Law."},{type:"paragraph",contentRu:"5.6. Пользователь принимает, что стоимость, расчетная оценка, рыночная цена, редкость и иные экономические характеристики результата Апгрейда, Контракта или иной Игровой операции могут отличаться, в том числе существенно, от совокупной стоимости Предметов и условных единиц, использованных для совершения соответствующей операции. При условии корректного исполнения Игровой операции такое расхождение является допустимым свойством соответствующей игровой механики и не образует задолженности Оператора перед Пользователем, не является Технической ошибкой и не создает права требовать возмещения разницы, доплаты, замены результата либо иной компенсации, если иное прямо не предусмотрено императивными нормами Применимого законодательства.",contentEn:"5.6. The User accepts that the value, estimated value, market price, rarity and other economic characteristics of the result of an Upgrade, Contract or other Game Operation may differ materially from the aggregate value of the Items and notional units used. If the operation is performed correctly, that difference is an inherent feature of the relevant mechanic, is not a Technical Error and does not entitle the User to payment of the difference, replacement or compensation unless mandatory provisions of Applicable Law require otherwise."},{type:"paragraph",contentRu:"5.7. Оператор вправе устанавливать и изменять применительно к будущим Игровым операциям требования, критерии и ограничения в отношении Предметов и иных учетных единиц, допускаемых к использованию в Апгрейде, Контракте или иной игровой функции, включая ограничения по количеству, категории, типу, редкости, расчетной стоимости, времени или способу получения, источнику происхождения, периоду нахождения в Инвентаре и иным объективно определяемым характеристикам. Оператор вправе также устанавливать минимальные и максимальные значения операций, временные интервалы, количественные лимиты и иные технические параметры соответствующих функций.",contentEn:"5.7. The Operator may establish and change, in relation to future Game Operations, requirements, criteria and restrictions in relation to Items and other accounting units allowed for use in an Upgrade, Contract or other game function, including restrictions on quantity, category, type, rarity, estimated value, time or method of receipt, source, period of stay in the Inventory and other objectively determined characteristics. The Operator also may set minimum and maximum transaction values, time intervals, quantitative limits and other technical parameters of the relevant functions."},{type:"paragraph",contentRu:"5.8. До подтверждения Апгрейда, Контракта или иной Игровой операции Пользователь обязан самостоятельно проверить правильность выбранных Предметов, их количество, отображаемые параметры операции, размер списываемых условных единиц, целевой Предмет и иные существенные характеристики. Ошибочный, случайный или совершенный вследствие невнимательности Пользователя выбор, включая использование Предмета, который Пользователь субъективно считает более редким, ценным или экономически значимым, не является Технической ошибкой и не служит основанием для отмены, изменения или обратного исполнения корректно завершенной Игровой операции.",contentEn:"5.8. Before confirming an Upgrade, Contract or other Game Operation, the User shall independently check the correctness of the selected Items, their quantity, the displayed parameters of the operation, the size of the written off notional units, the target Item and other essential characteristics. An erroneous, accidental or careless choice by the User, including the use of an Item that the User subjectively considers more rare, valuable or economically significant, is not a Technical Error and does not serve as a basis for canceling, changing or reversing a correctly completed Game Operation."},{type:"paragraph",contentRu:"5.9. В целях обеспечения устойчивого и безопасного функционирования Платформы, предотвращения случайного дублирования операций, автоматизированного или программного совершения действий, эксплуатации уязвимостей, мошенничества и иных злоупотреблений Оператор вправе устанавливать технические паузы между операциями, количественные и стоимостные лимиты, дополнительные этапы подтверждения, временные ограничения, процедуры повторной авторизации, проверки безопасности и иные соразмерные защитные механизмы. Наличие таких мер само по себе не свидетельствует о возникновении у Пользователя права на совершение Игровых операций без ограничений либо в каком-либо заранее определенном объеме.",contentEn:"5.9. In order to ensure stable and secure functioning of the Platform, prevent accidental duplication of operations, automated or programmatic actions, exploitation of vulnerabilities, fraud and other abuses, the Operator may establish technical pauses between operations, quantitative and cost limits, additional confirmation stages, time limits, re-authorization procedures, security checks and other adequate protective mechanisms. The presence of such measures does not in itself indicate that the User may carry out Game Operations without restrictions or to any predetermined extent."},{type:"paragraph",contentRu:"5.10. Функциональные возможности Платформы, прямо обозначенные Оператором как тестовые, экспериментальные, временные, сезонные, акционные либо предоставляемые в ограниченном режиме, могут быть изменены, приостановлены или прекращены Оператором применительно к будущему использованию. Если иное не обусловлено Технической ошибкой, требованиями Применимого законодательства или необходимостью устранения последствий нарушения настоящего Соглашения, прекращение или изменение соответствующей функции не затрагивает результаты Игровых операций, надлежащим образом завершенных до вступления соответствующего изменения в силу.",contentEn:"5.10. The functionality of the Platform, which is expressly designated by the Operator as test, experimental, temporary, seasonal, promotional, or provided in a limited mode, may be changed, suspended or terminated by the Operator in relation to future use. Unless otherwise required by a Technical Error, Applicable Law, or to remedy a violation of this Agreement, termination or modification of the applicable feature will not affect Game Operations properly completed prior to the effective date of the modification."},{type:"paragraph",contentRu:"5.11. При внедрении новых игровых механик или иных функциональных возможностей, прямо не поименованных в настоящем Соглашении, к отношениям, возникающим в связи с их использованием, в соответствующей части применяются общие положения настоящего Соглашения о Внутреннем балансе, Предметах, формировании заранее индивидуально не определенного результата, Серверных данных, Технических ошибках, безопасности Аккаунта, запретах и ограничениях использования Платформы, порядке разрешения спорных ситуаций и ответственности Сторон, если специальные условия соответствующей функции не устанавливают иное.",contentEn:"5.11. New game mechanics or other functions not expressly named in this Agreement are governed, to the relevant extent, by the general provisions concerning the Internal Balance, Items, generation of a result not predetermined in advance, Server Data, Technical Errors, Account security, prohibited conduct, dispute resolution and liability, unless the special terms of the new function provide otherwise."},{type:"paragraph",contentRu:"5.12. При наличии объективных признаков того, что Апгрейд, Контракт или иная Игровая операция была совершена либо ее результат сформирован вследствие Технической ошибки, дублирования запроса, программного вмешательства, использования автоматизированных средств, эксплуатации уязвимости или иного нарушения штатного порядка функционирования Платформы, Оператор вправе временно ограничить распоряжение соответствующими Предметами и (или) иными результатами операции на период проведения проверки. По результатам проверки Оператор вправе восстановить корректное состояние учетных данных и применить иные предусмотренные настоящим Соглашением меры, при этом корректно сформированный результат не подлежит произвольному аннулированию или изменению исключительно вследствие его экономической невыгодности для Оператора или Пользователя.",contentEn:"5.12. Where objective evidence indicates that an Upgrade, Contract or other Game Operation, or its result, arose from a Technical Error, duplicate request, software interference, automated means, exploitation of a vulnerability or other disruption of normal Platform operation, the Operator may temporarily restrict disposal of the relevant Items or other results while it investigates. Following the review, the Operator may restore the correct accounting position and apply other measures under this Agreement, but may not arbitrarily cancel or alter a correctly generated result merely because it is economically unfavorable to either Party."},{type:"subtitle",contentRu:"6. Предметы, Инвентарь и правовой статус цифровых объектов",contentEn:"6. Items, Inventory and Legal Status of Digital Objects",level:1},{type:"paragraph",contentRu:"6.1. Отображение Предмета в Инвентаре и наличие соответствующей записи в информационных системах Платформы подтверждают исключительно наличие у Пользователя предусмотренной настоящим Соглашением возможности совершать в отношении такого Предмета доступные на соответствующий момент действия посредством функционала Платформы, включая его использование в Игровых операциях, Вывод либо иное предусмотренное Соглашением распоряжение. Такая запись сама по себе не удостоверяет возникновение у Пользователя права собственности, исключительного права либо иного абсолютного имущественного права на программный код, графическое изображение, дизайн, товарный знак, наименование, аудиовизуальные элементы или иные объекты интеллектуальной собственности, связанные с соответствующим Предметом.",contentEn:"6.1. Display of an Item in the Inventory and a corresponding Platform record confirms only that the User may take the actions with that Item then supported by Platform functionality. The record does not, by itself, establish ownership, an exclusive right or another absolute proprietary right in source code, artwork, designs, trademarks, names, audiovisual elements or other intellectual property associated with the Item."},{type:"paragraph",contentRu:"6.2. Правовой режим Предметов, связанных с компьютерными играми, Steam и иными сторонними цифровыми сервисами, определяется не только настоящим Соглашением, но также применимыми правилами, пользовательскими соглашениями, лицензионными условиями, техническими ограничениями и иными обязательными требованиями Valve Corporation, правообладателя соответствующей компьютерной игры и иных третьих лиц. Оператор не вправе и не принимает на себя обязательство предоставить Пользователю в отношении Предмета больший объем прав, полномочий или технических возможностей, чем допускается соответствующим сторонним сервисом и Применимым законодательством.",contentEn:"6.2. The legal status of Items associated with computer games, Steam and other third-party digital services is governed by this Agreement and by the applicable rules, user agreements, license terms, technical restrictions and other binding requirements of Valve Corporation, the relevant game rightsholder and other third parties. The Operator neither has the right nor assumes an obligation to grant rights or technical capabilities beyond those permitted by the relevant third-party service and Applicable Law."},{type:"paragraph",contentRu:"6.3. До момента успешного завершения Вывода Предмет учитывается и отображается посредством внутренних информационных систем Платформы в соответствии с Серверными данными. Само по себе наличие Предмета в Инвентаре не является гарантией его немедленной либо безусловной передачи на Связанный Steam-аккаунт, поскольку возможность и сроки такой передачи могут зависеть от работоспособности и правил Steam, наличия соответствующего Предмета в технически доступном для передачи состоянии, функционирования Steam-ботов, торговых ограничений, периода блокировки обмена, технического обслуживания сторонних сервисов и иных обстоятельств, полностью или частично находящихся вне разумного контроля Оператора.",contentEn:"6.3. Until the successful completion of the Withdrawal, the Item is taken into account and displayed through the internal information systems of the Platform in accordance with Server Data. The mere presence of an Item in the Inventory does not guarantee its immediate or unconditional transfer to the Linked Steam Account, since the possibility and timing of such transfer may depend on the performance and rules of Steam, the availability of the relevant Item in a technically accessible state for transfer, the functioning of Steam bots, trading restrictions, the period of exchange blocking, technical maintenance of third-party services and other circumstances completely or partially beyond the reasonable control of the Operator."},{type:"paragraph",contentRu:"6.4. При отсутствии установленных настоящим Соглашением, Применимым законодательством, правилами Steam либо примененными Оператором обоснованными ограничениями Пользователь вправе в пределах доступного функционала использовать Предмет в Апгрейде, Контракте или иной Игровой операции, инициировать его Вывод либо оставить соответствующий Предмет в Инвентаре до наступления предусмотренных настоящим Соглашением оснований для Автоматической продажи. Использование Предмета в Апгрейде, Контракте, обмене или иной операции, предусматривающей его расходование, означает согласие Пользователя на окончательное списание соответствующего Предмета после надлежащего формирования результата такой операции.",contentEn:"6.4. Unless a justified restriction applies under this Agreement, Applicable Law, Steam rules or a proportionate measure imposed by the Operator, the User may use an Item through an available Upgrade, Contract or other Game Operation, initiate Withdrawal, or leave it in the Inventory until Automatic Sale applies. Using an Item in an operation that consumes it constitutes consent to its final debit once the result is properly generated."},{type:"paragraph",contentRu:"6.5. Оператор вправе временно приостановить Вывод, использование, обмен, Автоматическую продажу или иное распоряжение конкретным Предметом при наличии объективных оснований для проведения проверки, включая оспаривание связанного с ним платежа, инициирование чарджбэка или процедуры возврата платежа, необходимость проверки источника происхождения денежных средств, выявление признаков мошенничества или несанкционированного доступа, предполагаемую Техническую ошибку, наличие ограничений со стороны Steam либо получение обязательного для исполнения требования суда, государственного, правоохранительного, надзорного или иного компетентного органа. Продолжительность соответствующего ограничения определяется характером и обстоятельствами проверки и не должна превышать срок, объективно необходимый для ее проведения, если иной срок не обусловлен законом или действиями третьих лиц.",contentEn:"6.5. The Operator may temporarily suspend the Withdrawal, use, exchange, Automatic Sale or other disposition of a specific Item if there are objective grounds for conducting an inspection, including disputing the associated payment, initiating a chargeback or chargeback procedure, the need to verify the source of funds, identifying signs of fraud or unauthorized access, a suspected Technical Error, the presence of restrictions on the part of Steam, or receipt of a binding requirement from a court, government, law enforcement, supervisory or other competent authority. The duration of the corresponding restriction is determined by the nature and circumstances of the inspection and should not exceed the period objectively necessary for its implementation, unless a different period is stipulated by law or the actions of third parties."},{type:"paragraph",contentRu:"6.6. Наименование, изображение, категория, редкость, состояние и иные визуальные либо описательные характеристики Предмета отображаются Платформой на основании информации, доступной Оператору из собственных и сторонних информационных систем. При наличии расхождений между отдельными визуальными элементами интерфейса и техническими сведениями о Предмете определяющее значение для идентификации конкретного цифрового объекта имеют его уникальный идентификатор и иные объективные технические характеристики, подтверждаемые совокупностью Серверных данных и данных Steam. Явная ошибка отображения, не повлиявшая на идентичность фактически сформированного цифрового объекта, сама по себе не предоставляет Пользователю права требовать предоставления иного Предмета, если иное не следует из Применимого законодательства.",contentEn:"6.6. The name, image, category, rarity, condition and other visual or descriptive characteristics of the Item are displayed by the Platform based on information available to the Operator from its own and third-party information systems. If there are discrepancies between individual visual interface elements and technical information about the Item, its unique identifier and other objective technical characteristics, confirmed by the aggregate of Server Data and Steam data, are decisive for identifying a specific digital object. An obvious display error that does not affect the identity of the actually generated digital object does not in itself provide the User with the right to demand the provision of a different Item, unless otherwise follows from the Applicable Law."},{type:"paragraph",contentRu:"6.7. Оператор не устанавливает и не гарантирует сохранение какой-либо определенной рыночной, обменной, расчетной или иной стоимости Предмета после его получения Пользователем, наличие или сохранение спроса на соответствующий Предмет, его ликвидность, возможность последующей реализации, обмена либо передачи третьему лицу, а также неизменность правил его оборота или техническую доступность в Steam. Стоимость и востребованность Предметов могут изменяться вследствие рыночных условий, решений Valve Corporation, разработчиков и правообладателей соответствующих игр, изменения характеристик игровых объектов и иных обстоятельств, не находящихся под контролем Оператора.",contentEn:"6.7. The Operator does not establish or guarantee the preservation of any specific market, exchange, estimated or other value of the Item after its receipt by the User, the presence or continuation of demand for the relevant Item, its liquidity, the possibility of subsequent sale, exchange or transfer to a third party, as well as the immutability of the rules of its circulation or technical availability on Steam. The cost and demand for Items may change due to market conditions, decisions of Valve Corporation, developers and copyright holders of the relevant games, changes in the characteristics of game objects and other circumstances beyond the control of the Operator."},{type:"paragraph",contentRu:"6.8. Инвентарь не является услугой бессрочного хранения цифровых объектов, а Оператор не принимает на себя обязательство обеспечивать нахождение Предмета в Инвентаре в течение неопределенного срока исключительно в целях ожидания Пользователем изменения его предполагаемой рыночной стоимости. Предельный период нахождения Предмета в Инвентаре, последствия истечения такого периода и условия Автоматической продажи определяются настоящим Соглашением и (или) специальными правилами, надлежащим образом доведенными до сведения Пользователя.",contentEn:"6.8. Inventory is not a service for the indefinite storage of digital objects, and the Operator does not undertake to ensure that an Item remains in the Inventory for an indefinite period solely for the purpose of waiting for the User to change its estimated market value. The maximum period for an Item to be in the Inventory, the consequences of the expiration of such a period and the terms of the Automatic Sale are determined by this Agreement and/or special rules duly communicated to the User."},{type:"paragraph",contentRu:"6.9. В случае прекращения либо существенного изменения поддержки конкретной компьютерной игры, категории Предметов, соответствующей интеграции со Steam или иным сторонним сервисом, а также при возникновении обстоятельств, объективно препятствующих дальнейшему предоставлению соответствующего функционала, Оператор вправе ограничить или прекратить совершение будущих операций с соответствующими Предметами. В отношении уже отраженных в Инвентаре Предметов Оператор вправе, исходя из технической возможности и требований Применимого законодательства, предоставить Пользователю разумный срок для осуществления доступного Вывода либо применить предусмотренный настоящим Соглашением механизм Автоматической продажи.",contentEn:"6.9. In the event of termination or significant change in support for a specific computer game, category of Items, corresponding integration with Steam or other third-party service, as well as in the event of circumstances that objectively prevent the further provision of the corresponding functionality, the Operator may limit or terminate future transactions with the relevant Items. In relation to Items already reflected in the Inventory, the Operator has the right, based on the technical feasibility and requirements of the Applicable Law, to provide the User with a reasonable period for making an available Withdrawal or to apply the Automatic Sale mechanism provided for in this Agreement."},{type:"paragraph",contentRu:"6.10. Пользователь самостоятельно несет риск изменения стоимости, ликвидности, востребованности и технической доступности Предмета после его получения, а также риск введения Steam, правообладателем соответствующей игры или иным третьим лицом новых ограничений в отношении использования, передачи или обмена соответствующего цифрового объекта. Настоящее положение не освобождает Оператора от ответственности за собственное ненадлежащее исполнение обязательств, если такая ответственность не может быть исключена или ограничена в соответствии с Применимым законодательством.",contentEn:"6.10. The User independently bears the risk of changes in the value, liquidity, demand and technical availability of the Item after its receipt, as well as the risk of introduction by Steam, the copyright holder of the corresponding game or other third party of new restrictions regarding the use, transfer or exchange of the corresponding digital object. This provision does not relieve the Operator from liability for its own improper performance of obligations, unless such liability cannot be excluded or limited in accordance with Applicable Law."},{type:"paragraph",contentRu:"6.11. Пользователь самостоятельно определяет наличие и исполняет налоговые, декларационные, регистрационные и иные публично-правовые обязанности, возникающие непосредственно у него в связи с получением, использованием, передачей, обменом, Выводом или иным распоряжением Предметами, в соответствии с законодательством применимой к нему юрисдикции. Оператор не осуществляет индивидуальное налоговое консультирование Пользователя и не несет обязанности по уплате за Пользователя соответствующих налогов, сборов или иных обязательных платежей, за исключением случаев, когда обязанность по их исчислению, удержанию, декларированию или перечислению прямо и императивно возложена на Оператора Применимым законодательством.",contentEn:"6.11. The User shall determine and comply with any tax, reporting, registration or other public-law obligations arising from the receipt, use, transfer, exchange, Withdrawal or other disposal of Items under laws applicable to the User. The Operator does not provide individual tax advice and is not responsible for paying taxes, fees or other mandatory charges on the User's behalf, except where Applicable Law directly requires the Operator to calculate, withhold, report or remit them."},{type:"subtitle",contentRu:"7. Вывод Предметов",contentEn:"7. Withdrawal of Items",level:1},{type:"paragraph",contentRu:"7.1. Функциональная возможность Вывода предоставляется исключительно в отношении Предметов, для которых такая возможность технически доступна и не ограничена настоящим Соглашением, Применимым законодательством, правилами Steam либо иными применимыми требованиями. Внутренний баланс и учитываемые на нем условные единицы не являются объектом Вывода и, если иное прямо не предусмотрено императивными нормами Применимого законодательства, не подлежат обмену, погашению или выплате в форме денежных средств, электронной или цифровой валюты, криптовалюты, электронных денег либо иного платежного или финансового инструмента.",contentEn:"7.1. Withdrawal is available only for Items for which it is technically supported and not restricted by this Agreement, Applicable Law, Steam rules or other applicable requirements. The Internal Balance and notional units recorded on it are not eligible for Withdrawal and, unless mandatory provisions of Applicable Law require otherwise, may not be exchanged, redeemed or paid out as cash, electronic or digital currency, cryptocurrency, electronic money or another payment or financial instrument."},{type:"paragraph",contentRu:"7.2. Вывод конкретного Предмета допускается исключительно на Связанный Steam-аккаунт, посредством которого Пользователь был надлежащим образом авторизован на Платформе при совершении Игровой операции, непосредственно повлекшей получение соответствующего Предмета. Идентификатор такого Связанного Steam-аккаунта фиксируется Серверными данными в момент совершения соответствующей Игровой операции и, если иное прямо не предусмотрено Применимым законодательством или функционалом Платформы, является единственным допустимым реквизитом для последующего Вывода данного Предмета.",contentEn:"7.2. A particular Item may be withdrawn only to the Linked Steam Account through which the User was properly authenticated when performing the Game Operation that directly produced that Item. The identifier recorded in Server Data at that time is the only permitted destination unless Platform functionality or Applicable Law expressly provides otherwise."},{type:"paragraph",contentRu:"7.3. Передача Предмета на любой Steam-аккаунт, отличный от Связанного Steam-аккаунта, не допускается, в том числе если такой Steam-аккаунт также принадлежит Пользователю либо принадлежит его родственнику, представителю, приобретателю Предмета, посреднику или иному третьему лицу. Оператор не обязан создавать, поддерживать или вручную реализовывать технические исключения из установленного порядка Вывода. Обращение Пользователя с просьбой осуществить Вывод на иной Steam-аккаунт, обойти установленные Steam ограничения либо произвести передачу вне предусмотренного Платформой интерфейса может быть отклонено и при наличии объективных признаков повышенного риска являться основанием для проведения дополнительной проверки безопасности.",contentEn:"7.3. An Item may not be transferred to any Steam Account other than the Linked Steam Account, even if the other account belongs to the User or to the User's relative, representative, purchaser, intermediary or another third party. The Operator need not create a technical exception. A request to use another Steam Account, bypass a Steam restriction or transfer outside the Platform interface may be rejected and may trigger an additional security review."},{type:"paragraph",contentRu:"7.4. До направления запроса на Вывод Пользователь обязан самостоятельно обеспечить наличие всех технических и организационных условий, необходимых для получения Предмета посредством Steam, включая указание действительной и корректной ссылки для обмена, надлежащую настройку Steam Guard и иных предусмотренных Steam средств защиты, возможность получения и принятия торговых предложений, отсутствие применимых периодов удержания (trade hold), торговых блокировок, ограничений Инвентаря, ограничений учетной записи и иных обстоятельств, препятствующих передаче Предмета. Оператор не несет ответственности за невозможность или задержку Вывода, непосредственно обусловленную обстоятельствами на стороне Пользователя или Steam, в той мере, в которой такая ответственность не может быть возложена на Оператора в соответствии с Применимым законодательством.",contentEn:"7.4. Before submitting a Withdrawal request, the User shall ensure that all technical and organizational conditions required by Steam are satisfied, including a valid trade URL, proper Steam Guard settings, the ability to accept trade offers, and the absence of an applicable trade hold, trade lock, Inventory or account restriction. To the extent permitted by Applicable Law, the Operator is not liable for a failure or delay directly attributable to the User or Steam."},{type:"paragraph",contentRu:"7.5. Направление Пользователем запроса на Вывод означает поручение Оператору совершить предусмотренные функционалом Платформы и технически доступные действия, направленные на передачу соответствующего Предмета на Связанный Steam-аккаунт. Вывод считается надлежащим образом завершенным после подтверждения факта передачи соответствующими Серверными данными и, в применимой части, данными Steam. Само по себе направление запроса на Вывод, формирование торгового предложения либо изменение статуса операции в пользовательском интерфейсе до получения технического подтверждения передачи не означает окончательного завершения Вывода.",contentEn:"7.5. The User sending a request for Withdrawal means an instruction to the Operator to perform the actions provided for by the functionality of the Platform and technically available, aimed at transferring the corresponding Item to the Linked Steam Account. Withdrawal is deemed to be properly completed upon confirmation of transmission by the relevant Server Data and, to the extent applicable, Steam Data. The mere sending of a request for Withdrawal, the formation of a trade proposal, or changing the status of the operation in the user interface before receiving technical confirmation of the transfer does not mean the final completion of the Withdrawal."},{type:"paragraph",contentRu:"7.6. Срок исполнения запроса на Вывод зависит от совокупности обстоятельств, включая работоспособность и доступность Steam и его программных интерфейсов, наличие и доступность соответствующих Steam-ботов, технический статус конкретного Предмета, применимые ограничения на его передачу, необходимость проведения проверок безопасности, AML/KYC- и антифрод-процедур, а также иные обстоятельства, находящиеся полностью или частично вне разумного контроля Оператора. Любой срок Вывода, отображаемый в интерфейсе или сообщаемый Пользователю и прямо не обозначенный как гарантированный, является ориентировочным и не представляет собой безусловного обязательства обеспечить передачу Предмета в пределах соответствующего периода.",contentEn:"7.6. The period for executing a Withdrawal request depends on a combination of circumstances, including the operability and availability of Steam and its software interfaces, the availability of the corresponding Steam bots, the technical status of a particular Item, applicable restrictions on its transfer, the need to conduct security checks, AML/KYC and anti-fraud procedures, as well as other circumstances that are wholly or partially beyond the reasonable control of the Operator. Any withdrawal period displayed in the interface or communicated to the User and not expressly stated as guaranteed is indicative and does not constitute an unconditional obligation to ensure the transfer of the Item within the relevant period."},{type:"paragraph",contentRu:"7.7. Если Предмет, соответствующий результату Игровой операции, временно отсутствует у технически доступного для осуществления передачи Steam-бота либо его передача временно невозможна по иным техническим причинам, Оператор вправе отложить исполнение запроса до восстановления технической возможности передачи, вернуть Предмет в доступный внутренний учет Платформы либо предложить Пользователю иной Предмет, сопоставимый по согласованным Сторонами характеристикам. Замена Предмета на иной цифровой объект без согласия Пользователя не допускается, за исключением случаев, когда соответствующее последствие прямо предусмотрено Применимым законодательством.",contentEn:"7.7. If the relevant Item is temporarily unavailable on a Steam bot capable of transfer, or transfer is temporarily impossible for another technical reason, the Operator may postpone the request until transfer becomes possible, return the Item to an available Platform record, or offer a replacement Item with characteristics agreed by the Parties. The Operator may not substitute another digital object without the User's consent unless Applicable Law expressly permits it."},{type:"paragraph",contentRu:"7.8. Пользователь обязан своевременно совершить необходимые действия для принятия корректно сформированного торгового предложения в течение срока, установленного Steam либо доведенного до сведения Пользователя посредством интерфейса Платформы. Непринятие, отклонение, отмена или истечение срока действия торгового предложения по причинам, не зависящим от Оператора, может повлечь необходимость формирования Пользователем повторного запроса на Вывод. Если вследствие таких обстоятельств Предмет продолжает учитываться в Инвентаре, течение предусмотренного настоящим Соглашением срока его нахождения в Инвентаре и применение механизма Автоматической продажи не приостанавливаются автоматически, если иное прямо не предусмотрено интерфейсом Платформы или Применимым законодательством.",contentEn:"7.8. The User shall promptly take the necessary actions to accept a correctly formed trade offer within the period established by Steam or brought to the attention of the User through the Platform interface. Non-acceptance, rejection, cancellation or expiration of a trading offer for reasons beyond the control of the Operator may result in the need for the User to formulate a repeated withdrawal request. If, due to such circumstances, the Item continues to be taken into account in the Inventory, the period of its presence in the Inventory provided for by this Agreement and the application of the Automatic Sale mechanism are not automatically suspended, unless otherwise expressly provided by the Platform interface or Applicable Law."},{type:"paragraph",contentRu:"7.9. В целях предотвращения использования Пополнения и Внутреннего баланса исключительно в качестве механизма транзитного перемещения стоимости, а также в целях управления платежными, антифрод- и иными рисками Оператор вправе, если это допускается Применимым законодательством и соответствующее условие надлежащим образом доведено до сведения Пользователя до Пополнения, устанавливать обязательное требование по достижению минимального объема Игровых операций (далее — «Игровой оборот») до предоставления возможности Вывода Предметов, приобретенных или полученных с использованием соответствующего Пополнения. Размер требуемого Игрового оборота, порядок его исчисления и операции, учитываемые при его выполнении, определяются правилами Платформы, доступными Пользователю до совершения соответствующего Пополнения.",contentEn:"7.9. To prevent use of Top-Ups and the Internal Balance solely for transit movement of value and to manage payment and anti-fraud risks, the Operator may, where permitted by Applicable Law and disclosed before the relevant Top-Up, require a minimum volume of Game Operations (the “Game Turnover”) before Items obtained using that Top-Up may be withdrawn. The required Game Turnover, calculation method and qualifying operations shall be stated in Platform rules available before the Top-Up."},{type:"paragraph",contentRu:"7.10. Если применительно к конкретному Пополнению установлено требование по Игровому обороту, каждое последующее Пополнение может формировать самостоятельный дополнительный объем Игрового оборота либо увеличивать совокупный невыполненный объем в соответствии с правилами учета, заранее доведенными до сведения Пользователя. До выполнения применимого требования Оператор вправе временно ограничить Вывод, обмен либо иной предусмотренный функционалом способ извлечения стоимости из соответствующих результатов операций, однако наличие невыполненного Игрового оборота само по себе не предоставляет Оператору права произвольно уменьшать или аннулировать корректно сформированный Внутренний баланс либо Предметы при отсутствии иного предусмотренного настоящим Соглашением или Применимым законодательством основания.",contentEn:"7.10. If, in relation to a specific Top-Up, a requirement for Game turnover is established, each subsequent Top-Up may form an independent additional volume of Game turnover or increase the total outstanding volume in accordance with the accounting rules communicated to the User in advance. Until the applicable requirement is met, the Operator may temporarily limit the Withdrawal, exchange or other method of extracting value from the corresponding results of operations provided by the functionality, however, the presence of unfulfilled Game turnover in itself does not provide the Operator with the right to arbitrarily reduce or cancel a correctly formed Internal Balance or Items in the absence of any other basis provided for in this Agreement or Applicable Law."},{type:"paragraph",contentRu:"7.11. Оператор вправе временно приостановить исполнение запроса на Вывод на период, объективно необходимый для проведения предусмотренной законом или настоящим Соглашением AML/KYC-, санкционной, антифрод- или иной проверки, подтверждения личности Пользователя и его контроля над Связанным Steam-аккаунтом, проверки принадлежности или правомерности использования платежного инструмента, исследования обстоятельств оспаривания платежа или чарджбэка, проверки источника происхождения денежных средств, расследования предполагаемой Технической ошибки, несанкционированного доступа или иного нарушения, а также для исполнения обязательного требования суда, государственного, правоохранительного, надзорного или иного компетентного органа.",contentEn:"7.11. The Operator may suspend a Withdrawal request for the period objectively necessary to conduct an AML/KYC, sanctions, anti-fraud or other review required by law or this Agreement, including verification of identity, control of the Linked Steam Account, lawful use of a payment instrument, a payment dispute or chargeback, source of funds, a suspected Technical Error, unauthorized access or another breach, or to comply with a binding requirement of a competent authority."},{type:"paragraph",contentRu:"7.12. Пользователь признает, что техническая возможность Вывода зависит от инфраструктуры и правил третьих лиц. Комиссии, периоды удержания, торговые ограничения, требования Steam Guard, ограничения конкретной компьютерной игры, изменения API, прекращение поддержки отдельных Предметов или способов их передачи и иные условия, устанавливаемые Steam, Valve Corporation, правообладателями соответствующих игр либо иными независимыми от Оператора лицами, применяются в соответствии с правилами таких лиц и могут изменяться без участия Оператора. Оператор не гарантирует неизменность или постоянную доступность соответствующей сторонней инфраструктуры.",contentEn:"7.12. The User acknowledges that the technical feasibility of the Withdrawal depends on the infrastructure and rules of third parties. Fees, hold periods, trading restrictions, Steam Guard requirements, restrictions on a specific computer game, API changes, discontinuation of support for certain Items or methods of transfer and other conditions established by Steam, Valve Corporation, the copyright holders of the relevant games or other parties independent of the Operator, are applied in accordance with the rules of such parties and may be changed without the participation of the Operator. The Operator does not guarantee the unchangeability or continuous availability of the relevant third-party infrastructure."},{type:"paragraph",contentRu:"7.13. Оператор предпринимает предусмотренные настоящим Соглашением действия по Выводу исключительно посредством официально поддерживаемых Платформой и технически допустимых способов. Оператор не обязан удовлетворять требования Пользователя о совершении передачи с нарушением правил Steam, обходе технических, территориальных, санкционных, комплаенс- или иных ограничений, использовании не предусмотренных Платформой каналов передачи либо совершении иных действий, способных повлечь нарушение Применимого законодательства, требований третьих лиц или требований безопасности. Отказ Оператора от совершения такой операции сам по себе не является нарушением настоящего Соглашения при условии, что соответствующий отказ основан на объективно применимом ограничении.",contentEn:"7.13. The Operator takes the Withdrawal actions provided for in this Agreement exclusively through officially supported by the Platform and technically acceptable methods. The Operator is not obliged to satisfy the User's requests to make a transfer in violation of Steam rules, bypass technical, territorial, sanctions, compliance or other restrictions, use transfer channels not provided for by the Platform, or perform other actions that could lead to a violation of Applicable Law, third party requirements or security requirements. The Operator's refusal to perform such a transaction does not in itself constitute a violation of this Agreement, provided that the corresponding refusal is based on an objectively applicable restriction."},{type:"subtitle",contentRu:"8. Автоматическая продажа Предметов",contentEn:"8. Automatic Sale of Items",level:1},{type:"paragraph",contentRu:"8.1. Каждый Предмет, зачисленный в Инвентарь и не выведенный либо иным предусмотренным настоящим Соглашением способом не использованный Пользователем до наступления установленного настоящим разделом срока, подлежит Автоматической продаже. Механизм Автоматической продажи является исключительно внутренней функциональной и учетной процедурой Платформы, предназначенной для ограничения периода нахождения Предметов во внутреннем учете и обеспечения функционирования соответствующей цифровой инфраструктуры, и, если иное не следует из императивных требований Применимого законодательства, не является брокерской, дилерской, комиссионной, депозитарной, инвестиционной услугой, услугой доверительного управления либо иной самостоятельной регулируемой финансовой деятельностью.",contentEn:"8.1. Each Item credited to the Inventory that the User has not withdrawn or otherwise used before the deadline in this section is subject to Automatic Sale. Automatic Sale is solely an internal functional and accounting procedure intended to limit the period for which Items remain in the Platform's internal records. Unless mandatory provisions of Applicable Law require otherwise, it is not brokerage, dealing, commission agency, custody, investment management, trust management or another standalone regulated financial activity."},{type:"paragraph",contentRu:"8.2. Принимая настоящее Соглашение и совершая Игровую операцию, результатом которой является зачисление Предмета в Инвентарь, Пользователь предоставляет Оператору заранее выраженное и действующее в отношении каждого такого Предмета поручение по истечении установленного срока без получения дополнительного подтверждения непосредственно перед совершением соответствующего действия автоматически исключить Предмет из Инвентаря и зачислить на Внутренний баланс количество условных единиц, определенное в соответствии с правилами настоящего раздела. До момента фактического совершения Автоматической продажи Пользователь вправе распорядиться Предметом иным доступным способом, включая инициирование Вывода или использование Предмета в разрешенной Игровой операции, при условии отсутствия применимых ограничений.",contentEn:"8.2. By accepting this Agreement and performing a Game Operation that credits an Item to the Inventory, the User gives the Operator a standing instruction, once the prescribed period expires and without further confirmation, to remove the Item automatically from the Inventory and credit the Internal Balance with the number of notional units determined under this section. Until Automatic Sale is completed, the User may dispose of the Item through another available function, subject to applicable restrictions."},{type:"paragraph",contentRu:"8.3. Автоматическая продажа осуществляется посредством автоматизированного запуска соответствующей функции один раз в каждые календарные сутки в 03:00 по всемирному координированному времени (UTC+0). Для определения момента запуска и исчисления предусмотренных настоящим разделом сроков применяются исключительно серверное время Платформы и соответствующие Серверные данные. Часовой пояс Пользователя, локальное время и настройки его устройства, географическое местонахождение, сезонный перевод времени, переход на летнее или зимнее время и иные аналогичные обстоятельства не изменяют установленное расписание Автоматической продажи.",contentEn:"8.3. Automatic Sale is carried out by automatically launching the corresponding function once every calendar day at 03:00 UTC+0. To determine the moment of launch and calculation of the terms provided for in this section, exclusively the Platform’s server time and the corresponding Server Data are used. The User's time zone, local time and device settings, geographic location, seasonal time change, transition to summer or winter time and other similar circumstances do not change the established Automatic Sale schedule."},{type:"paragraph",contentRu:"8.4. В каждый очередной автоматизированный запуск включаются исключительно те Предметы, в отношении которых к моменту такого запуска с момента их зачисления в Инвентарь истекло не менее 24 (двадцати четырех) полных часов. Вследствие применения ежедневного фиксированного времени запуска фактический период нахождения Предмета в Инвентаре до Автоматической продажи составляет не менее 24 часов и при штатном функционировании соответствующего механизма, как правило, менее 48 часов. Если к ближайшему запуску после получения Предмета 24 полных часа еще не истекли, такой Предмет автоматически переносится на следующий предусмотренный расписанием запуск. Соответственно, Предмет, полученный непосредственно до 03:00 UTC+0, не подлежит Автоматической продаже через несколько минут после его получения, а Предмет, полученный непосредственно после 03:00 UTC+0, может находиться в Инвентаре до запуска, следующего через дополнительные календарные сутки после первого пропущенного запуска.",contentEn:"8.4. Each regular automated launch includes only those Items for which, at the time of such launch, at least 24 (twenty-four) full hours have elapsed since they were added to the Inventory. Due to the use of a daily fixed start time, the actual period of the Item being in the Inventory before the Automatic Sale is at least 24 hours and, with the normal operation of the corresponding mechanism, usually less than 48 hours. If 24 full hours have not yet expired by the next launch after receiving the Item, such Item is automatically transferred to the next scheduled launch. Accordingly, an Item received immediately before 03:00 UTC+0 is not subject to Automatic Sale a few minutes after its receipt, and an Item received immediately after 03:00 UTC+0 may remain in the Inventory until the launch following an additional calendar day after the first missed launch."},{type:"paragraph",contentRu:"8.5. Стоимость Предмета для целей Автоматической продажи определяется непосредственно на момент фактического исполнения соответствующей операции на основании применяемой Платформой внутренней оценки с учетом доступной на соответствующий момент информации, которая может включать отображаемую на Сайте стоимость Предмета, доступные рыночные данные, показатели ликвидности и востребованности, характеристики и состояние Предмета, сведения сторонних сервисов и иные используемые Оператором объективно применимые критерии. Стоимость Автоматической продажи может отличаться от стоимости Предмета на момент его первоначального получения, стоимости Кейса или иной Игровой операции, цены аналогичного объекта на Steam Community Market или сторонних торговых площадках, а также от предполагаемой Пользователем текущей или будущей стоимости. Само по себе такое расхождение при отсутствии Технической ошибки не является основанием для возникновения у Оператора обязанности компенсировать Пользователю соответствующую разницу.",contentEn:"8.5. The cost of the Item for the purposes of Automatic Sale is determined immediately at the time of the actual execution of the corresponding operation on the basis of the internal assessment used by the Platform, taking into account information available at the relevant time, which may include the cost of the Item displayed on the Site, available market data, indicators of liquidity and demand, characteristics and condition of the Item, information from third-party services and other objectively applicable criteria used by the Operator. The cost of an Automatic Sale may differ from the cost of the Item at the time of its initial receipt, the cost of a Case or other Game Operation, the price of a similar item on the Steam Community Market or third-party marketplaces, as well as from the current or future cost assumed by the User. Such a discrepancy in itself, in the absence of a Technical Error, does not constitute a basis for the Operator to be obligated to compensate the User for the corresponding difference."},{type:"paragraph",contentRu:"8.6. С момента надлежащего завершения Автоматической продажи соответствующий Предмет окончательно исключается из Инвентаря и прекращает быть доступным Пользователю для Вывода, Апгрейда, Контракта, обмена или совершения иных операций, а определенное в соответствии с пунктом 8.5 настоящего Соглашения количество условных единиц зачисляется на Внутренний баланс. Такие условные единицы имеют тот же внутренний учетный статус и подчиняются тем же ограничениям использования, которые предусмотрены настоящим Соглашением для иных единиц Внутреннего баланса: они не подлежат самостоятельному обратному Выводу в форме денежных средств, криптовалюты, электронных денег или иного платежного средства и могут использоваться исключительно посредством доступного функционала Платформы, включая Кейсы, Апгрейды, Контракты и иные предусмотренные Игровые операции.",contentEn:"8.6. From the moment of proper completion of the Automatic Sale, the corresponding Item is finally excluded from the Inventory and ceases to be available to the User for Withdrawal, Upgrade, Contract, exchange or other transactions, and the number of notional units determined in accordance with clause 8.5 of this Agreement is credited to the Internal Balance. Such notional units have the same internal accounting status and are subject to the same restrictions on use as provided for in this Agreement for other Internal Balance units: they are not subject to independent reverse Withdrawal in the form of cash, cryptocurrency, electronic money or other means of payment and can be used exclusively through the available functionality of the Platform, including Cases, Upgrades, Contracts and other provided Game Operations."},{type:"paragraph",contentRu:"8.7. Начало или продолжение проверки Аккаунта, наличие ограничений со стороны Steam, невыполнение Пользователем установленного Игрового оборота либо иное обстоятельство, препятствующее Выводу Предмета, само по себе не приостанавливает течение срока, предусмотренного для Автоматической продажи, если иное прямо не установлено Оператором, специальными условиями соответствующей проверки или Применимым законодательством. Пользователь обязан учитывать установленный срок нахождения Предмета в Инвентаре при выборе способа распоряжения им. После корректного завершения Автоматической продажи Пользователь не вправе требовать ее отмены, восстановления Предмета в Инвентаре, осуществления последующего Вывода проданного Предмета, применения ранее существовавшей стоимости либо выплаты разницы между фактической стоимостью Автоматической продажи и иной предполагаемой Пользователем стоимостью, за исключением случаев подтвержденной Технической ошибки или наличия соответствующего права в силу императивных норм Применимого законодательства.",contentEn:"8.7. The beginning or continuation of an Account verification, the presence of restrictions on the part of Steam, the User’s failure to fulfill the established Game turnover, or any other circumstance that prevents the Withdrawal of an Item, does not in itself suspend the period provided for the Automatic Sale, unless otherwise expressly established by the Operator, the special conditions of the relevant verification or the Applicable Law. The User shall take into account the established period for the Item to be in the Inventory when choosing a method for disposing of it. After the correct completion of the Automatic Sale, the User has no right to demand its cancellation, restoration of the Item in the Inventory, subsequent Withdrawal of the sold Item, application of a previously existing cost, or payment of the difference between the actual cost of the Automatic Sale and another cost estimated by the User, except in cases confirmed by a Technical Error or the existence of the corresponding right by virtue of mandatory rules of Applicable Law."},{type:"paragraph",contentRu:"8.8. Если предусмотренный пунктом 8.3 настоящего Соглашения автоматизированный запуск полностью или частично не состоялся вследствие Технической ошибки, временной недоступности инфраструктуры, проведения технических работ либо иных объективных технических обстоятельств, Оператор вправе осуществить Автоматическую продажу соответствующих Предметов при ближайшем технически доступном запуске после устранения препятствующих обстоятельств. Такая задержка сама по себе не влечет обязанности Оператора компенсировать изменение рыночной, расчетной или иной стоимости Предмета за период задержки, если иное прямо не предусмотрено Применимым законодательством. Для определения момента зачисления Предмета в Инвентарь, истечения 24-часового периода и момента соответствующего запуска определяющее значение имеют временные метки, содержащиеся в Серверных данных; отображение даты и времени на устройстве Пользователя или в иных сторонних системах носит исключительно информационный характер.",contentEn:"8.8. If the automated launch provided for in clause 8.3 of this Agreement does not take place in whole or in part due to a Technical Error, temporary unavailability of infrastructure, technical work or other objective technical circumstances, the Operator may carry out an Automatic Sale of the relevant Items at the next technically accessible launch after the elimination of the impeding circumstances. Such a delay in itself does not entail the Operator’s obligation to compensate for changes in the market, estimated or other value of the Item during the period of delay, unless otherwise expressly provided by Applicable Law. To determine the moment when an Item is added to the Inventory, the expiration of the 24-hour period and the moment of the corresponding launch, the timestamps contained in the Server Data are of decisive importance; The display of date and time on the User’s device or in other third-party systems is for informational purposes only."},{type:"subtitle",contentRu:"9. Программы лояльности",contentEn:"9. Loyalty Programs",level:1},{type:"paragraph",contentRu:"9.1. Оператор вправе по собственному усмотрению разрабатывать, вводить, проводить, изменять и прекращать бонусные программы, программы лояльности, рекламные и стимулирующие мероприятия, предоставлять промокоды, кэшбэк, бесплатные Кейсы, бонусные условные единицы, персональные предложения, награды и иные формы поощрения (далее совместно — «Бонусы»). Предоставление Бонуса является дополнительной функциональной возможностью Платформы и не образует самостоятельной возмездной услуги Оператора, если иное прямо не предусмотрено специальными правилами соответствующего предложения. Использование Бонусов регулируется настоящим Соглашением, а также специальными условиями конкретной акции, программы или предложения, доведенными до сведения Пользователя до его участия.",contentEn:"9.1. The Operator has the right, at its sole discretion, to develop, introduce, implement, change and terminate bonus programs, loyalty programs, advertising and incentive events, provide promotional codes, cashback, free Cases, bonus notional units, personal offers, rewards and other forms of incentives (hereinafter collectively - “Bonuses”). The provision of a Bonus is an additional functionality of the Platform and does not constitute an independent paid service of the Operator, unless otherwise expressly provided for by the special rules of the relevant offer. The use of Bonuses is governed by this Agreement, as well as the special conditions of a specific promotion, program or offer, brought to the attention of the User prior to his participation."},{type:"paragraph",contentRu:"9.2. Бонусы, включая начисленные в рамках соответствующего предложения условные единицы, не являются денежными средствами, электронной или цифровой валютой, электронными деньгами, финансовым инструментом либо самостоятельным имущественным требованием о выплате денежных средств, не приобретаются Пользователем за отдельную плату и не имеют гарантированной денежной стоимости. Если иное прямо не предусмотрено специальными условиями или императивными нормами Применимого законодательства, Бонусы не подлежат Выводу, возврату, продаже, уступке, дарению, передаче другому Пользователю или третьему лицу, обмену на денежные средства, криптовалюту либо иное средство платежа и могут использоваться исключительно в пределах функционала и на условиях, установленных Оператором.",contentEn:"9.2. Bonuses, including notional units granted under an offer, are not cash, electronic or digital currency, electronic money, a financial instrument or an independent monetary claim. They are not purchased for consideration and have no guaranteed monetary value. Unless special terms or mandatory provisions of Applicable Law provide otherwise, a Bonus cannot be withdrawn, refunded, sold, assigned, gifted, transferred or exchanged for cash, cryptocurrency or another means of payment."},{type:"paragraph",contentRu:"9.3. Применительно к каждому Бонусу Оператор вправе устанавливать любые не запрещенные Применимым законодательством условия его предоставления и использования, включая срок активации и действия, минимальный и (или) максимальный размер Пополнения, требуемый Игровой оборот, очередность расходования условных единиц, перечень учитываемых и исключаемых Игровых операций, ограничения по Кейсам, Апгрейдам, Контрактам и Предметам, территорию действия, максимальное количество участников, критерии соответствия Пользователя, персональный характер предложения, периодичность участия, технические и платежные требования, а также иные условия, объективно связанные с соответствующей программой. Невыполнение любого обязательного условия может повлечь невозможность предоставления, использования либо дальнейшего сохранения соответствующего Бонуса.",contentEn:"9.3. In relation to each Bonus, the Operator may establish any conditions for its provision and use not prohibited by Applicable Law, including the activation and validity period, the minimum and/or maximum size of the Top-Up, the required Game turnover, the order of spending notional units, the list of included and excluded Game Operations, restrictions on Cases, Upgrades, Contracts and Items, validity area, maximum number of participants, User eligibility criteria, personal nature of the offer, frequency of participation, technical and payment requirements, as well as other conditions objectively related to the relevant program. Failure to comply with any mandatory condition may result in the inability to provide, use or continue to maintain the relevant Bonus."},{type:"paragraph",contentRu:"9.4. Порядок учета и расходования Бонусов определяется технической логикой Платформы и специальными правилами соответствующего предложения. Если иное прямо не отображено в интерфейсе либо не предусмотрено специальными условиями, приобретенные Пользователем посредством Пополнения условные единицы могут расходоваться до бонусных условных единиц либо в иной очередности, предусмотренной внутренним алгоритмом учета Платформы. Пользователь не вправе самостоятельно требовать применения иной очередности списания, перераспределения уже совершенных списаний между различными категориями условных единиц либо ретроспективного изменения источника финансирования завершенной Игровой операции.",contentEn:"9.4. The procedure for recording and spending Bonuses is determined by the technical logic of the Platform and the special rules of the corresponding offer. Unless otherwise expressly displayed in the interface or provided for by special conditions, notional units acquired by the User through Top-Up may be spent before bonus notional units or in another order provided for by the internal accounting algorithm of the Platform. The User may not independently demand the use of a different order of write-offs, redistribution of already completed write-offs between different categories of notional units, or a retrospective change in the source of financing for a completed Game Operation."},{type:"paragraph",contentRu:"9.5. Если специальными правилами прямо не предусмотрено иное, право на участие в конкретном бонусном или рекламном предложении предоставляется однократно одному Пользователю. В целях предотвращения множественного участия Оператор вправе учитывать совокупность объективных признаков технической или фактической связанности, включая Аккаунт, Steam-аккаунт, устройство, IP-адрес и иные сетевые идентификаторы, платежный инструмент, контактные данные, а также иные допустимые Применимым законодательством антифрод-признаки. Наличие таких совпадений может являться основанием для дополнительной проверки, но само по себе не должно рассматриваться как безусловное доказательство нарушения без учета совокупности обстоятельств.",contentEn:"9.5. Unless special rules expressly provide otherwise, the right to participate in a specific bonus or promotional offer is granted to one User once. In order to prevent multiple participation, the Operator may take into account a set of objective signs of technical or actual connection, including Account, Steam Account, device, IP address and other network identifiers, payment instrument, contact information, as well as other anti-fraud signs permitted by Applicable Law. The presence of such matches may be the basis for additional verification, but in itself should not be considered as absolute evidence of a violation without taking into account the totality of the circumstances."},{type:"paragraph",contentRu:"9.6. Пользователю запрещается использовать Бонусы способом, противоречащим назначению соответствующего предложения, включая создание или использование дополнительных Аккаунтов, саморефералы, фиктивные приглашения, регистрацию номинальных участников, передачу Аккаунта третьим лицам, согласованные действия нескольких Пользователей, искусственное формирование Игрового оборота, использование автоматизированных средств, эксплуатацию Технических ошибок или уязвимостей, манипулирование условиями акции, инициирование чарджбэка или необоснованного возврата платежа после получения обусловленного таким платежом Бонуса, а также совершение иных действий, основной целью или фактическим результатом которых является получение Бонуса либо связанной с ним экономической выгоды в обход установленных условий.",contentEn:"9.6. The User is prohibited from using Bonuses in a manner contrary to the purpose of the relevant offer, including the creation or use of additional Accounts, self-referrals, fictitious invitations, registration of nominee participants, transfer of the Account to third parties, coordinated actions of several Users, artificial formation of Game turnover, use of automated means, exploitation of Technical Errors or vulnerabilities, manipulation of promotional conditions, initiation of a chargeback or unreasonable return of payment after receiving the Bonus conditional on such payment, as well as performing other actions, the main purpose or actual result of which is to receive the Bonus or the economic benefit associated with it, bypassing the established conditions."},{type:"paragraph",contentRu:"9.7. При наличии объективных признаков возможного злоупотребления Оператор вправе временно приостановить начисление, использование или реализацию соответствующего Бонуса, а также связанные с ним операции на период проведения проверки. Пользователь обязан по разумному запросу Оператора предоставить сведения и документы, необходимые для установления обстоятельств участия в соответствующей программе. До завершения проверки Оператор вправе ограничить Вывод Предметов или иное распоряжение результатами операций в той мере, в которой такие результаты непосредственно связаны с проверяемым Бонусом и существует обоснованный риск их неправомерного получения или отчуждения.",contentEn:"9.7. Where objective indicators suggest abuse, the Operator may suspend grant, use or disposal of the relevant Bonus and related operations while it investigates. At the Operator's reasonable request, the User shall provide information and documents needed to establish the circumstances. Pending completion, the Operator may restrict Withdrawal or other disposal only to the extent directly connected with the Bonus under review and a reasonably identified risk of unlawful receipt or transfer."},{type:"paragraph",contentRu:"9.8. Если по результатам проверки подтверждено нарушение Пользователем условий соответствующей акции, программы лояльности или настоящего Соглашения, Оператор вправе в максимально допустимой Применимым законодательством степени аннулировать неиспользованный Бонус, отменить начисленные вследствие нарушения бонусные условные единицы, скорректировать результаты Игровых операций, непосредственно и доказуемо профинансированных неправомерно полученным Бонусом, а также аннулировать иные начисления или преимущества, находящиеся в непосредственной причинно-следственной связи с установленным нарушением. Такие меры должны быть направлены на восстановление учетного положения, которое существовало бы при отсутствии злоупотребления, и не предоставляют Оператору права произвольно списывать принадлежащие Пользователю учетные позиции, не связанные с соответствующим нарушением.",contentEn:"9.8. If, based on the results of the verification, a violation by the User of the terms of the relevant promotion, loyalty program or this Agreement is confirmed, the Operator has the right, to the maximum extent permitted by Applicable Law, to cancel the unused Bonus, cancel the bonus credits accrued as a result of the violation, adjust the results of Game Operations directly and provably financed by the illegally received Bonus, and also cancel other accruals or benefits that are in a direct cause-and-effect relationship with the established violation. Such measures must be aimed at restoring the accounting position that would exist in the absence of the abuse, and do not provide the Operator with the right to arbitrarily write off accounting positions belonging to the User that are not related to the relevant violation."},{type:"paragraph",contentRu:"9.9. Оператор вправе отказать в предоставлении Бонуса, приостановить прием новых участников, изменить условия либо досрочно прекратить акцию, программу лояльности или иное стимулирующее предложение применительно к будущему участию, если иное не предусмотрено специальными условиями или Применимым законодательством. Такое изменение или прекращение само по себе не является основанием для предъявления Пользователем требований о предоставлении Бонуса, который не был надлежащим образом начислен до вступления соответствующих изменений в силу. Права, приобретенные Пользователем за отдельную плату и не имеющие бонусной природы, не подлежат аннулированию исключительно вследствие прекращения акции, если отсутствует самостоятельное основание, предусмотренное настоящим Соглашением или законом.",contentEn:"9.9. The Operator may refuse to provide a Bonus, suspend the acceptance of new participants, change the conditions or early terminate a promotion, loyalty program or other incentive offer in relation to future participation, unless otherwise provided by special conditions or Applicable Law. Such change or termination in itself does not constitute grounds for the User to claim a Bonus that was not properly accrued before the relevant changes came into force. Rights acquired by the User for a fee and not of a bonus nature are not subject to cancellation solely due to termination of the promotion, unless there is an independent basis provided for by this Agreement or the law."},{type:"paragraph",contentRu:"9.10. Оператор вправе устанавливать срок действия Бонуса, по истечении которого неиспользованный Бонус, бонусные условные единицы, право на бесплатный Кейс, повышенный кэшбэк либо иное предоставленное исключительно в рамках соответствующей программы преимущество автоматически прекращается и может быть исключено из Аккаунта без выплаты Пользователю денежной или иной компенсации, при условии что срок действия и последствия его истечения были надлежащим образом доведены до сведения Пользователя до получения или активации соответствующего Бонуса.",contentEn:"9.10. The Operator may set the validity period of the Bonus, after which the unused Bonus, bonus credit units, the right to a free Case, increased cashback or other benefit provided exclusively within the framework of the relevant program automatically terminates and can be excluded from the Account without payment to the User of monetary or other compensation, provided that the validity period and the consequences of its expiration were duly brought to the attention of the User before receiving or activating the relevant Bonus."},{type:"paragraph",contentRu:"9.11. Рекламные баннеры, уведомления, публикации, электронные сообщения, краткие описания акций и иные маркетинговые материалы могут содержать сокращенное изложение условий соответствующего предложения и подлежат толкованию совместно с его полными правилами. При наличии расхождений между сокращенным рекламным описанием и полными правилами преимущественную силу имеют полные правила соответствующей акции или программы при условии, что они были доступны Пользователю до совершения действия, необходимого для участия, изложены доступным способом и не содержат положений, применение которых вопреки рекламному сообщению являлось бы вводящим в заблуждение или иным образом запрещенным Применимым законодательством.",contentEn:"9.11. Banner advertisements, notices, publications, emails, promotional summaries and other marketing materials may contain abbreviated terms and conditions of the applicable offer and should be construed in conjunction with the full terms and conditions of the applicable offer. If there is a discrepancy between an abbreviated promotional description and the full rules, the full rules for the applicable promotion or program will govern, provided that they are made available to the User prior to taking the action required to participate, are presented in an understandable manner, and do not contain provisions that, if applied contrary to the promotional message, would be misleading or otherwise prohibited by Applicable Law."},{type:"paragraph",contentRu:"9.12. Предоставление Бонуса одному или нескольким Пользователям, неоднократное проведение определенной акции, применение Оператором исключения в конкретном случае либо неприменение им предусмотренной настоящим разделом меры не создают у иных Пользователей права требовать предоставления аналогичного Бонуса, сохранения соответствующей программы в будущем или применения идентичных индивидуальных условий. Оператор сохраняет право дифференцировать предложения по объективным коммерческим, территориальным, техническим, риск-ориентированным и иным критериям, если такая дифференциация не запрещена Применимым законодательством.",contentEn:"9.12. The provision of a Bonus to one or more Users, the repeated holding of a certain promotion, the application by the Operator of an exception in a particular case or its failure to apply the measure provided for in this section does not create the right for other Users to demand the provision of a similar Bonus, the preservation of the corresponding program in the future or the application of identical individual conditions. The Operator retains the right to differentiate offers based on objective commercial, territorial, technical, risk-based and other criteria, unless such differentiation is prohibited by Applicable Law."},{type:"subtitle",contentRu:"10. Возвраты, отмена операций и право отказа",contentEn:"10. Refunds, Cancellation of Operations and Right of Withdrawal",level:1},{type:"paragraph",contentRu:"10.1. Пополнение Аккаунта осуществляется в целях немедленного приобретения условных единиц и их последующего использования в рамках функционала Платформы. Если иное прямо не предусмотрено Применимым законодательством, неиспользованный Внутренний баланс не является денежными средствами, электронными деньгами либо самостоятельным платежным инструментом и не подлежит обратному выводу или обмену на денежные средства.",contentEn:"10.1. A Top-Up credits notional units for immediate use through Platform functionality. Unless Applicable Law expressly provides otherwise, an unused Internal Balance is not cash, electronic money or an independent payment instrument and cannot be withdrawn or redeemed for cash."},{type:"paragraph",contentRu:"10.2. Подтверждая Пополнение, Пользователь поручает Оператору приступить к предоставлению соответствующей цифровой услуги и зачислению условных единиц незамедлительно после подтверждения платежа. В случаях, предусмотренных Применимым законодательством, Пользователь предоставляет отдельное согласие на начало исполнения до истечения установленного законом срока отказа и подтверждает понимание правовых последствий такого согласия, включая утрату права на отказ в предусмотренных законом случаях.",contentEn:"10.2. By confirming the Top-Up, the User instructs the Operator to begin providing the corresponding digital service and crediting notional units immediately after confirmation of the payment. In cases provided for by Applicable Law, the User provides separate consent to begin execution before the expiration of the statutory refusal period and confirms an understanding of the legal consequences of such consent, including the loss of the right to refuse in cases provided for by law."},{type:"paragraph",contentRu:"10.3. С момента использования условных единиц, в том числе для открытия Кейса, совершения Апгрейда или Контракта, а также получения, использования либо распоряжения Предметом соответствующая операция считается окончательной и не может быть отменена исключительно вследствие изменения решения Пользователя, за исключением случаев, когда право на отмену или возврат прямо предусмотрено Применимым законодательством.",contentEn:"10.3. From the moment of using notional units, including for opening a Case, making an Upgrade or Contract, as well as receiving, using or disposing of an Item, the corresponding transaction is considered final and cannot be canceled solely due to a change in the User’s decision, except in cases where the right to cancel or return is expressly provided for by the Applicable Law."},{type:"paragraph",contentRu:"10.4. Ограничения, установленные настоящим разделом, не исключают и не ограничивают императивные права Пользователя, в частности в случаях неоказания оплаченной услуги, двойного или ошибочного списания, несанкционированной платежной операции либо подтвержденной Технической ошибки. Пользователь обязан уведомить Оператора о предполагаемой ошибке без неоправданной задержки, по возможности в течение 72 часов с момента ее обнаружения; пропуск указанного срока сам по себе не прекращает права, предоставленные Пользователю законом, однако может учитываться при оценке обстоятельств и возможности проведения проверки.",contentEn:"10.4. This section does not exclude or limit the User's mandatory rights, including in the event of failure to provide a paid service, a duplicate or erroneous debit, an unauthorized payment or a confirmed Technical Error. The User should notify the Operator without undue delay and, where possible, within 72 hours after discovering a suspected error. Missing that period does not, by itself, extinguish a statutory right but may affect the available evidence and the ability to investigate."},{type:"paragraph",contentRu:"10.5. Если возврат является обязательным в силу Применимого законодательства либо отдельно одобрен Оператором, он осуществляется, как правило, на первоначальное платежное средство и в валюте исходного платежа после проведения необходимых идентификационных, технических, антифрод- и иных предусмотренных законом или требованиями платежных партнеров проверок. Возврат на платежное средство, банковский счет, электронный или криптовалютный кошелек либо адрес третьего лица не допускается, кроме случаев объективной невозможности возврата первоначальным способом и при условии допустимости альтернативного способа законом и соответствующим платежным партнером.",contentEn:"10.5. If a refund is required by Applicable Law or separately approved by the Operator, it is carried out, as a rule, to the original means of payment and in the currency of the original payment after carrying out the necessary identification, technical, anti-fraud and other checks required by law or the requirements of payment partners. Refunds to a means of payment, bank account, electronic or cryptocurrency wallet, or third party address are not permitted, unless it is objectively impossible to return using the original method and provided that an alternative method is permitted by law and the relevant payment partner."},{type:"paragraph",contentRu:"10.6. Для рассмотрения требования о возврате Оператор вправе запросить идентификатор Аккаунта, сведения и документы, подтверждающие соответствующую платежную операцию и принадлежность платежного средства Пользователю, а также иные разумно необходимые сведения. До завершения идентификации Пользователя и проверки обстоятельств операции исполнение требования может быть приостановлено. Оператор стремится предоставить первоначальный ответ в течение 10 рабочих дней с даты получения достаточного комплекта сведений, однако данный срок может быть продлен при необходимости дополнительной проверки, взаимодействия с платежным партнером либо проведения внешнего расследования.",contentEn:"10.6. To consider a refund request, the Operator may request the Account ID, information and documents confirming the relevant payment transaction and the ownership of the payment instrument by the User, as well as other reasonably necessary information. Until the User identification is completed and the circumstances of the transaction are verified, the execution of the request may be suspended. The Operator aims to provide an initial response within 10 business days of receiving sufficient information, but this period may be extended if additional verification, interaction with the payment partner or external investigation is necessary."},{type:"paragraph",contentRu:"10.7. Комиссии, расходы на конвертацию и курсовые разницы, удержанные банками, платежными системами, провайдерами либо иными независимыми третьими лицами, подлежат возмещению только в той части, в которой соответствующие суммы фактически возвращены Оператору либо обязанность их возмещения прямо предусмотрена Применимым законодательством. Возврат не осуществляется путем предоставления иного Предмета, если такой способ отдельно не согласован Пользователем и Оператором после возникновения основания для возврата.",contentEn:"10.7. Commissions, conversion costs and exchange rate differences withheld by banks, payment systems, providers or other independent third parties are subject to reimbursement only to the extent that the corresponding amounts are actually returned to the Operator or the obligation to reimburse them is expressly provided for by Applicable Law. Refunds are not made by providing another Item, unless such a method is separately agreed upon by the User and the Operator after the basis for the return arises."},{type:"paragraph",contentRu:"10.8. Бонусы, промо-балансы и иные безвозмездные начисления не обладают самостоятельной возвратной стоимостью. При возврате Пополнения Оператор вправе, в пределах, допускаемых Применимым законодательством, аннулировать связанные с таким Пополнением неиспользованные бонусы, условные единицы и иные результаты, получение которых непосредственно обусловлено возвращаемым платежом. Сумма одобренного возврата также может быть зачтена в счет подтвержденной задолженности Пользователя, отрицательного баланса, суммы чарджбэка либо документально подтвержденного прямого ущерба, если такой зачет допускается Применимым законодательством.",contentEn:"10.8. Bonuses, promotional balances and other free accruals do not have an independent return value. When returning a Top-Up, the Operator has the right, to the extent permitted by Applicable Law, to cancel unused bonuses, notional units and other results associated with such Top-Up, the receipt of which is directly caused by the returned payment. The amount of an approved refund may also be offset against the User's verified debt, negative balance, chargeback amount, or documented direct loss, if such offset is permitted by Applicable Law."},{type:"paragraph",contentRu:"10.9. Само по себе истечение или неистечение какого-либо фиксированного периода, включая 14 календарных дней с даты платежа, не создает безусловного права на возврат и не исключает его. Наличие, объем и порядок реализации права Пользователя на отказ, отмену операции или возврат определяются характером соответствующей операции, фактом начала или завершения исполнения, применимыми императивными нормами и иными обстоятельствами конкретного случая.",contentEn:"10.9. The expiry or non-expiry of a fixed period, including 14 calendar days after payment, neither creates nor excludes an unconditional right to a refund. Any right to withdraw, cancel an operation or obtain a refund, and the procedure for exercising it, depend on the nature of the operation, whether performance has begun or been completed, applicable mandatory provisions and the circumstances of the case."},{type:"subtitle",contentRu:"11. Чарджбэки, спорные и несанкционированные платежи",contentEn:"11. Chargebacks, Disputed and Unauthorized Payments",level:1},{type:"paragraph",contentRu:"11.1. В случае возникновения сомнений относительно платежа, его суммы, статуса либо правомерности Пользователь обязан, когда это объективно и разумно возможно, до инициирования процедуры чарджбэка или иного платежного спора обратиться в службу поддержки Оператора и предоставить достаточные сведения для идентификации соответствующей операции. Настоящее положение не ограничивает императивные права Пользователя на обращение непосредственно к банку, платежному провайдеру или иному уполномоченному лицу в случаях, предусмотренных Применимым законодательством.",contentEn:"11.1. Where the User has concerns about a payment, its amount, status or lawfulness, the User shall, whenever objectively and reasonably possible, contact the Operator's support service and provide sufficient transaction details before initiating a chargeback or other payment dispute. This does not restrict any mandatory right to contact a bank, payment provider or other authorized person directly under Applicable Law."},{type:"paragraph",contentRu:"11.2. Заведомо ложное заявление о несанкционированном, ошибочном либо не совершенном Пользователем платеже, в частности после фактического зачисления и использования приобретенных условных единиц, совершения операций на Платформе либо получения Предметов за счет соответствующего Пополнения, является существенным нарушением настоящего Соглашения и, при наличии предусмотренных законом оснований, может быть квалифицировано как недобросовестное или мошенническое поведение.",contentEn:"11.2. A knowingly false statement about an unauthorized, erroneous or not made payment by the User, in particular after the actual crediting and use of purchased notional units, completion of transactions on the Platform or receipt of Items through the corresponding Top-Up, is a material violation of this Agreement and, if there are grounds provided for by law, may be qualified as unfair or fraudulent behavior."},{type:"paragraph",contentRu:"11.3. С момента получения уведомления о чарджбэке, оспаривании либо предполагаемой несанкционированности платежа Оператор вправе на период проверки полностью или частично ограничить отдельные функции соответствующего Аккаунта, включая совершение новых операций, использование Внутреннего баланса, распоряжение Предметами и Вывод, исключительно в объеме и на срок, объективно необходимые для предотвращения дальнейшего ущерба, сохранения доказательств и разрешения платежного спора.",contentEn:"11.3. After receiving notice of a chargeback, payment dispute or alleged unauthorized payment, the Operator may restrict relevant Account functions only to the extent and for the period objectively necessary to prevent further loss, preserve evidence and resolve the dispute."},{type:"paragraph",contentRu:"11.4. Если первоначальный платеж впоследствии отменен, возвращен, признан недействительным либо сумма такого платежа списана с Оператора банком, платежной системой или платежным партнером, соответствующее Пополнение считается аннулированным в соответствующей части. Оператор вправе произвести необходимые корректировки учета, включая сторнирование неиспользованных условных единиц и иных начислений, непосредственно связанных с отмененным платежом, в пределах технической возможности и Применимого законодательства.",contentEn:"11.4. If the initial payment is subsequently cancelled, returned, declared invalid, or the amount of such payment is debited from the Operator by a bank, payment system or payment partner, the corresponding Top-Up is considered canceled in the relevant part. The Operator may make the necessary accounting adjustments, including the reversal of unused notional units and other charges directly related to the canceled payment, within the limits of technical feasibility and Applicable Law."},{type:"paragraph",contentRu:"11.5. Если условные единицы, полученные за счет впоследствии отмененного или оспоренного платежа, были полностью или частично использованы до его отмены, Оператор вправе скорректировать Внутренний баланс и результаты непосредственно связанных с таким платежом операций в той мере, в которой это технически возможно, юридически допустимо и необходимо для восстановления положения, существовавшего бы при отсутствии соответствующего платежа.",contentEn:"11.5. If the notional units received from a subsequently canceled or disputed payment were fully or partially used before its cancellation, the Operator may adjust the Internal Balance and the results of transactions directly related to such payment to the extent technically possible, legally permissible and necessary to restore the situation that would have existed in the absence of the relevant payment."},{type:"paragraph",contentRu:"11.6. Если вследствие предусмотренных настоящим разделом корректировок образуется отрицательный Внутренний баланс либо иная подтвержденная задолженность Пользователя перед Оператором, Оператор вправе временно ограничить новые Пополнения, операции, использование отдельных функций Платформы и Вывод до момента погашения такой задолженности либо окончательного разрешения соответствующего платежного спора.",contentEn:"11.6. If, as a result of the adjustments provided for in this section, a negative Internal Balance or other confirmed debt of the User to the Operator is formed, the Operator may temporarily limit new Top-Ups, transactions, the use of certain functions of the Platform and Withdrawal until such debt is repaid or the relevant payment dispute is finally resolved."},{type:"paragraph",contentRu:"11.7. В случае установления умышленного и заведомо необоснованного инициирования Пользователем чарджбэка Оператор вправе потребовать возмещения фактически понесенных и документально подтвержденных комиссий, сборов и иных прямых расходов, начисленных банком, платежной системой или платежным партнером непосредственно в связи с таким чарджбэком, исключительно в той мере, в которой соответствующее требование допускается Применимым законодательством.",contentEn:"11.7. If it is established that the User has intentionally and knowingly unjustified initiation of a chargeback, the Operator may demand reimbursement of actually incurred and documented commissions, fees and other direct expenses accrued by the bank, payment system or payment partner directly in connection with such a chargeback, solely to the extent that the corresponding claim is permitted by Applicable Law."},{type:"paragraph",contentRu:"11.8. Добросовестное оспаривание платежа, обращение Пользователя в банк, платежную организацию, компетентный государственный орган либо использование иных предусмотренных законом способов защиты своих прав само по себе не является нарушением настоящего Соглашения и не влечет безусловного аннулирования всего Внутреннего баланса, конфискации всех Предметов либо применения иных мер, не связанных с предметом соответствующего спора.",contentEn:"11.8. A good-faith payment dispute, an appeal to a bank, payment organization or competent authority, or use of another statutory remedy does not, by itself, breach this Agreement and does not justify unconditional cancellation of the entire Internal Balance, forfeiture of all Items or another measure unrelated to the dispute."},{type:"paragraph",contentRu:"11.9. Для рассмотрения и разрешения платежного спора Оператор вправе предоставлять банкам, платежным системам, эквайерам, платежным провайдерам и иным участвующим в обработке платежа лицам необходимые сведения и доказательства, включая данные об Аккаунте, соответствующих операциях, использовании условных единиц, получении Предметов, технические и Серверные данные, а также иные относящиеся к спору документы, при условии соблюдения Политики конфиденциальности и требований Применимого законодательства.",contentEn:"11.9. To consider and resolve a payment dispute, the Operator may provide banks, payment systems, acquirers, payment providers and other parties involved in payment processing with the necessary information and evidence, including data about the Account, relevant transactions, use of notional units, receipt of Items, technical and Server Data, as well as other documents related to the dispute, subject to compliance with the Privacy Policy and the requirements of Applicable Law."},{type:"paragraph",contentRu:"11.10. После вступления в силу окончательного решения по платежному спору Оператор производит соответствующую корректировку учета и примененных ограничений. Если спор разрешен в пользу Пользователя, ограничения, обусловленные исключительно таким спором, подлежат снятию, а учет — восстановлению в соответствующей части. Если спор разрешен в пользу Оператора либо подтверждено нарушение Пользователем настоящего Соглашения, Оператор вправе применить предусмотренные им меры в объеме, соразмерном установленному нарушению и фактически возникшим последствиям.",contentEn:"11.10. After the final decision on the payment dispute comes into force, the Operator makes appropriate adjustments to the accounting and applied restrictions. If the dispute is resolved in favor of the User, the restrictions caused solely by such a dispute shall be removed, and the accounting shall be restored in the relevant part. If the dispute is resolved in favor of the Operator or a violation by the User of this Agreement is confirmed, the Operator may apply the measures provided for by it in an amount commensurate with the established violation and the actual consequences that arose."},{type:"paragraph",contentRu:"11.11. Независимо от результата отдельного платежного спора Оператор вправе, исходя из объективной оценки платежного, антифрод- и комплаенс-риска, ограничить или отказать в последующих Пополнениях с определенного платежного средства либо установить дополнительные требования к проверке соответствующего Аккаунта или платежного средства, если имеются разумные основания полагать, что их дальнейшее использование создает повышенный риск повторных чарджбэков, несанкционированных операций, мошенничества или иных злоупотреблений.",contentEn:"11.11. Regardless of the outcome of an individual payment dispute, the Operator has the right, based on an objective assessment of payment, anti-fraud and compliance risk, to limit or refuse subsequent Top-Ups from a particular payment instrument or to establish additional requirements for verification of the relevant Account or payment instrument if there are reasonable grounds to believe that their continued use creates an increased risk of repeated chargebacks, unauthorized transactions, fraud or other abuse."},{type:"subtitle",contentRu:"12. Технические ошибки, сбои и доказательственное значение данных",contentEn:"12. Technical Errors, Failures and Evidentiary Value of Data",level:1},{type:"paragraph",contentRu:"12.1. Платформа представляет собой комплексный программно-технический сервис, функционирование которого зависит в том числе от программного обеспечения, серверной инфраструктуры, сетей связи и интеграций с третьими лицами. В процессе эксплуатации возможны временная недоступность отдельных функций, задержки обработки операций, ошибки отображения, рассинхронизация пользовательского интерфейса и Серверных данных, перебои внешних интеграций и иные технические отклонения.",contentEn:"12.1. The Platform is a comprehensive software and hardware service, the functioning of which depends, among other things, on software, server infrastructure, communication networks and integrations with third parties. During operation, there may be temporary unavailability of certain functions, delays in processing operations, display errors, desynchronization of the user interface and Server Data, interruptions in external integrations and other technical deviations."},{type:"paragraph",contentRu:"12.2. Оператор вправе проводить плановые и аварийные технические, профилактические и иные необходимые работы, в связи с чем отдельные функции Платформы могут быть временно ограничены или недоступны, а обработка операций — приостановлена либо поставлена в очередь. При наличии разумной технической возможности информация о существенных плановых работах доводится до сведения Пользователей заблаговременно.",contentEn:"12.2. The Operator may carry out scheduled and emergency technical, preventive and other necessary work, in connection with which certain functions of the Platform may be temporarily limited or unavailable, and the processing of transactions may be suspended or queued. If reasonably technically feasible, information about significant scheduled work will be communicated to Users in advance."},{type:"paragraph",contentRu:"12.3. В случае расхождения между отображаемыми в пользовательском интерфейсе сведениями, включая анимацию, графическое отображение результата, уведомления, локально сохраненные или кэшированные данные, и соответствующими Серверными данными определяющее значение имеют Серверные данные, если в результате проверки не установлена их техническая ошибочность либо Пользователем не представлены достаточные доказательства обратного. Само по себе визуальное или анимационное отображение результата не изменяет фактический результат операции, зафиксированный на стороне сервера.",contentEn:"12.3. In the event of a discrepancy between the information displayed in the user interface, including animation, graphical display of the result, notifications, locally stored or cached data, and the corresponding Server Data, the Server Data shall prevail unless the verification results in a Technical Error or the User provides sufficient evidence to the contrary. The visual or animated display of the result itself does not change the actual result of the operation recorded on the server side."},{type:"paragraph",contentRu:"12.4. Серверные данные, журналы событий и операций, идентификаторы транзакций, временные метки, сведения об изменении Внутреннего баланса, а также относящиеся к соответствующей операции данные платежных партнеров, Steam и иных интегрированных сервисов могут использоваться Оператором в качестве доказательств факта, времени, последовательности и результата совершенных действий. Такие сведения оцениваются в совокупности с иными доступными доказательствами и не ограничивают право Пользователя представить собственные материалы, включая скриншоты, видеозаписи и записи экрана.",contentEn:"12.4. Server Data, event and transaction logs, transaction identifiers, time stamps, information about changes in Internal Balance, as well as data from payment partners, Steam and other integrated services related to the corresponding operation can be used by the Operator as evidence of the fact, time, sequence and result of the actions taken. Such information is assessed in conjunction with other available evidence and does not limit the User’s right to submit their own materials, including screenshots, videos and screen recordings."},{type:"paragraph",contentRu:"12.5. При выявлении дублирования запроса, аномального результата, некорректной цены, повторного либо избыточного начисления или списания, нарушения последовательности обработки данных либо иных обстоятельств, указывающих на вероятную Техническую ошибку, Оператор вправе приостановить соответствующую незавершенную операцию, временно ограничить распоряжение непосредственно связанными с ней активами и провести техническую проверку.",contentEn:"12.5. If a duplicate request, an abnormal result, an incorrect price, a repeated or excessive charge or write-off, a violation of the sequence of data processing, or other circumstances indicating a probable Technical Error are detected, the Operator may suspend the corresponding uncompleted operation, temporarily limit the disposal of assets directly related to it and conduct a technical check."},{type:"paragraph",contentRu:"12.6. Если по результатам проверки подтверждено ошибочное или избыточное начисление условных единиц, Предмета либо иной ценности вследствие Технической ошибки, Оператор вправе аннулировать соответствующее начисление, скорректировать Внутренний баланс и связанные записи либо, насколько это технически возможно и допускается Применимым законодательством, восстановить состояние Аккаунта, существовавшее непосредственно до возникновения ошибки. Сам факт ошибочного отображения или начисления не создает у Пользователя безусловного права на сохранение ценности, получение которой очевидно не соответствовало фактическим условиям операции.",contentEn:"12.6. If, based on the results of the check, an erroneous or excessive accrual of notional units, an Item or other value due to a Technical Error is confirmed, the Operator may cancel the corresponding accrual, adjust the Internal Balance and related entries, or, to the extent technically possible and permitted by Applicable Law, restore the Account state that existed immediately before the error occurred. The very fact of erroneous display or accrual does not create the User’s unconditional right to retain the value, the receipt of which obviously did not correspond to the actual conditions of the transaction."},{type:"paragraph",contentRu:"12.7. Если подтвержденная Техническая ошибка привела к избыточному списанию условных единиц, утрате Предмета либо иному некорректному уменьшению учитываемой на Аккаунте ценности, Оператор производит соответствующую корректировку путем восстановления ошибочно списанного количества условных единиц, Предмета либо иного предусмотренного Платформой результата в пределах технической возможности и с учетом требований Применимого законодательства.",contentEn:"12.7. If a confirmed Technical Error led to an excessive write-off of notional units, the loss of an Item, or another incorrect decrease in the value recorded on the Account, the Operator makes an appropriate adjustment by restoring the erroneously written off number of notional units, an Item, or another result provided for by the Platform, within the limits of technical feasibility and taking into account the requirements of Applicable Law."},{type:"paragraph",contentRu:"12.8. Корректировка последствий Технической ошибки осуществляется исключительно в целях устранения подтвержденного технического отклонения и не является основанием для пересмотра корректно совершенной операции вследствие неблагоприятного для Пользователя результата, последующего изменения рыночной или иной стоимости Предмета либо несоответствия фактического результата субъективным ожиданиям Пользователя.",contentEn:"12.8. Correction of the consequences of a Technical Error is carried out solely for the purpose of eliminating a confirmed technical deviation and is not a basis for revising a correctly completed transaction due to an unfavorable result for the User, a subsequent change in the market or other value of the Item, or a discrepancy between the actual result and the subjective expectations of the User."},{type:"paragraph",contentRu:"12.9. Если подтвержденная Техническая ошибка непосредственно повлияла на последующую последовательность взаимосвязанных операций таким образом, что соответствующие результаты объективно не могли бы возникнуть при отсутствии первоначальной ошибки, Оператор вправе скорректировать или отменить непосредственно связанную с ней цепочку операций. При этом восстановление производится, насколько это технически и юридически возможно, до состояния, максимально приближенного к тому, которое существовало бы при отсутствии соответствующей ошибки.",contentEn:"12.9. If a confirmed Technical Error directly affected the subsequent sequence of interrelated operations in such a way that the corresponding results objectively could not have occurred in the absence of the initial error, the Operator may correct or cancel the chain of operations directly related to it. In this case, restoration is carried out, as far as technically and legally possible, to a state as close as possible to that which would have existed in the absence of the corresponding error."},{type:"paragraph",contentRu:"12.10. Пользователь обязан воздерживаться от умышленного использования очевидной Технической ошибки, неисправности либо уязвимости Платформы и, обнаружив соответствующие обстоятельства, прекратить действия, направленные на извлечение выгоды из такой ошибки, и уведомить службу поддержки. Сознательное продолжение эксплуатации известной Пользователю ошибки может рассматриваться как злоупотребление функционалом Платформы и учитываться Оператором при применении предусмотренных Соглашением мер.",contentEn:"12.10. The User shall refrain from deliberately exploiting an obvious Technical Error, malfunction or vulnerability of the Platform and, upon discovering appropriate circumstances, cease actions aimed at capitalizing on such an error and notify support. Deliberate continuation of exploitation of an error known to the User may be considered an abuse of the functionality of the Platform and will be taken into account by the Operator when applying the measures provided for in the Agreement."},{type:"paragraph",contentRu:"12.11. При проведении технической проверки Оператор вправе запросить у Пользователя сведения, объективно необходимые для установления обстоятельств события, включая приблизительное или точное время его возникновения, идентификатор операции, сведения об устройстве и программном обеспечении, данные о соответствующем платеже, а также имеющиеся скриншоты или видеоматериалы. Непредоставление доступной Пользователю информации не является автоматическим основанием для отказа в рассмотрении обращения, однако может объективно увеличить срок проверки либо ограничить возможность установления обстоятельств события.",contentEn:"12.11. When conducting a technical check, the Operator may request from the User information objectively necessary to establish the circumstances of the event, including the approximate or exact time of its occurrence, transaction identifier, information about the device and software, data on the relevant payment, as well as available screenshots or video materials. Failure to provide information available to the User is not an automatic basis for refusal to consider the application, but it may objectively increase the verification period or limit the possibility of establishing the circumstances of the event."},{type:"paragraph",contentRu:"12.12. Оператор не обязан предоставлять Пользователю исходный код, внутреннюю техническую документацию, сведения об архитектуре Платформы, алгоритмах и моделях антифрод-систем, ключах, средствах информационной безопасности либо иные сведения ограниченного доступа, если их раскрытие способно создать угрозу безопасности Платформы, способствовать обходу механизмов защиты, нарушить права третьих лиц, обязательства конфиденциальности или требования Применимого законодательства.",contentEn:"12.12. The Operator is not obliged to provide the User with source code, internal technical documentation, information about the Platform architecture, algorithms and models of anti-fraud systems, keys, information security tools or other restricted information if their disclosure could create a threat to the security of the Platform, facilitate the bypass of security mechanisms, violate the rights of third parties, confidentiality obligations or the requirements of Applicable Law."},{type:"paragraph",contentRu:"12.13. Если восстановление конкретного Предмета либо первоначального технического состояния объективно невозможно, способ устранения последствий подтвержденной Технической ошибки определяется исходя из характера нарушения, фактического состояния Аккаунта, стоимости соответствующей ценности на момент возникновения ошибки, технической возможности восстановления и требований Применимого законодательства. Последующее изменение стоимости Предмета само по себе не является основанием для увеличения размера соответствующей компенсации.",contentEn:"12.13. If restoring a particular Item or the original technical state is objectively impossible, the remedy for a confirmed Technical Error shall take into account the nature of the error, the actual Account position, the value of the relevant asset when the error occurred, technical feasibility and Applicable Law. A later change in Item value does not, by itself, justify increasing compensation."},{type:"paragraph",contentRu:"12.14. Пользователь обязан принимать разумные и доступные меры для предотвращения увеличения возможных негативных последствий Технической ошибки, включая прекращение повторного совершения идентичных операций при очевидном сбое и своевременное обращение в службу поддержки. При определении последствий соответствующего инцидента может учитываться то, способствовали ли сознательные действия или бездействие Пользователя увеличению ущерба после того, как наличие ошибки стало или должно было стать для него очевидным.",contentEn:"12.14. The User shall take reasonable and available measures to prevent an increase in the possible negative consequences of a Technical Error, including stopping repeated execution of identical operations in the event of an obvious failure and promptly contacting support. In determining the consequences of the relevant incident, consideration may be given to whether the User's conscious actions or omissions contributed to the damage after the presence of the error became or should have become apparent to the User."},{type:"subtitle",contentRu:"13. Обстоятельства вне контроля Оператора",contentEn:"13. Circumstances Beyond the Operator’s Control",level:1},{type:"paragraph",contentRu:"13.1. Функционирование Платформы в определенной степени зависит от надлежащей работы независимых третьих лиц и внешней инфраструктуры, включая Steam и Valve Corporation, разработчиков соответствующих игр, платежные организации, банки, провайдеров платежных услуг, операторов связи, поставщиков облачной и серверной инфраструктуры, информационных и иных технологических сервисов. Оператор не осуществляет полного контроля над деятельностью таких лиц и не гарантирует непрерывность, неизменность либо постоянную доступность предоставляемых ими сервисов.",contentEn:"13.1. The functioning of the Platform to a certain extent depends on the proper operation of independent third parties and external infrastructure, including Steam and Valve Corporation, developers of relevant games, payment organizations, banks, payment service providers, telecom operators, providers of cloud and server infrastructure, information and other technology services. The Operator does not exercise full control over the activities of such persons and does not guarantee the continuity, immutability or constant availability of the services they provide."},{type:"paragraph",contentRu:"13.2. Valve и иные владельцы сторонних сервисов вправе самостоятельно изменять правила и технические условия их использования, ограничивать или приостанавливать торговые функции, устанавливать периоды удержания (trade hold), изменять порядок работы инвентаря, API и иных интеграций, блокировать или ограничивать учетные записи пользователей, а также прекращать предоставление отдельных функций. Оператор не гарантирует сохранение действующих на определенный момент правил, технических возможностей или функциональности таких сервисов.",contentEn:"13.2. Valve and other owners of third-party services may independently change the rules and technical conditions for their use, limit or suspend trading functions, set trade hold periods, change the operation of inventory, APIs and other integrations, block or limit user accounts, and also stop providing certain functions. The Operator does not guarantee the preservation of the rules, technical capabilities or functionality of such services at a certain time."},{type:"paragraph",contentRu:"13.3. Предметы, связанные со Steam или соответствующей игрой, являются цифровыми объектами, существование, использование, передача и иные характеристики которых определяются правилами и технической инфраструктурой соответствующего стороннего сервиса. Если иное прямо не предусмотрено Применимым законодательством, такие Предметы не являются материальными вещами, а их отображение или учет на Платформе сами по себе не изменяют правовой режим, установленный соответствующим сторонним сервисом.",contentEn:"13.3. Items associated with Steam or the applicable game are digital objects whose existence, use, transfer and other characteristics are determined by the rules and technical infrastructure of the relevant third-party service. Unless otherwise expressly provided by Applicable Law, such Items are not tangible things, and their display or accounting on the Platform does not in itself change the legal regime established by the relevant third-party service."},{type:"paragraph",contentRu:"13.4. Пользователь самостоятельно обязан соблюдать Steam Subscriber Agreement, правила соответствующей игры, ограничения Steam и иные применимые условия третьих лиц. Нарушение Пользователем таких условий, включая ограничения торговли или использования Аккаунта Steam, может повлечь невозможность либо задержку Вывода, получения, передачи или последующего использования Предметов и не создает ответственности Оператора, если соответствующие последствия не вызваны действиями или нарушением со стороны Оператора.",contentEn:"13.4. The User is solely responsible for complying with the Steam Subscriber Agreement, the rules of the relevant game, Steam restrictions and other applicable terms and conditions of third parties. Violation by the User of such conditions, including restrictions on trading or use of the Steam Account, may result in the impossibility or delay of the Withdrawal, receipt, transfer or subsequent use of Items and does not create liability for the Operator, unless the corresponding consequences are caused by actions or violation on the part of the Operator."},{type:"paragraph",contentRu:"13.5. Оператор не несет ответственности за блокировку или ограничение Аккаунта Steam, установление trade hold, отмену или отклонение торгового предложения, недоступность либо ограничение инвентаря, изменение характеристик, правил обращения или доступности Предметов, прекращение работы API или иные действия либо решения Valve или другого независимого третьего лица, если такие обстоятельства возникли вне разумного контроля Оператора и не обусловлены нарушением им собственных обязательств.",contentEn:"13.5. The Operator is not responsible for the blocking or restriction of a Steam Account, the establishment of a trade hold, the cancellation or rejection of a trade offer, the unavailability or limitation of inventory, changes in the characteristics, circulation rules or availability of Items, the termination of the API or other actions or decisions of Valve or another independent third party, if such circumstances arose beyond the reasonable control of the Operator and are not caused by a violation of its own obligations."},{type:"paragraph",contentRu:"13.6. Оператор не гарантирует постоянную доступность конкретного Steam-бота, торгового аккаунта, платежного канала, внешнего API или иного технического средства, используемого для взаимодействия со сторонними сервисами. При этом Оператор обязан добросовестно учитывать фактически завершенные операции и устранять подтвержденные ошибки, возникшие непосредственно в собственных системах учета Оператора.",contentEn:"13.6. The Operator does not guarantee the constant availability of a specific Steam bot, trading account, payment channel, external API or other technical tool used to interact with third-party services. At the same time, the Operator shall conscientiously take into account actually completed transactions and eliminate confirmed errors that arose directly in the Operator’s own accounting systems."},{type:"paragraph",contentRu:"13.7. При временной или постоянной недоступности внешней интеграции, прекращении работы соответствующего сервиса либо возникновении внешнего технического ограничения Оператор вправе определить разумный и технически осуществимый способ урегулирования незавершенных операций, включая ожидание восстановления соответствующего функционала, восстановление условных единиц, Автоматическую продажу, замену технического способа исполнения либо иной сопоставимый способ, допускаемый настоящим Соглашением и Применимым законодательством.",contentEn:"13.7. In the event of temporary or permanent unavailability of external integration, cessation of operation of the corresponding service, or the occurrence of an external technical limitation, the Operator may determine a reasonable and technically feasible method for resolving outstanding transactions, including waiting for the restoration of the relevant functionality, restoration of notional units, Automatic Sale, replacement of a technical method of execution, or another comparable method permitted by this Agreement and Applicable Law."},{type:"paragraph",contentRu:"13.8. Временная или постоянная невозможность передачи конкретного Предмета вследствие ограничений Steam, Valve либо иной внешней системы сама по себе не преобразует Внутренний баланс в денежное обязательство Оператора и не предоставляет Пользователю безусловного права требовать его выплаты денежными средствами, если иное прямо не предусмотрено Применимым законодательством.",contentEn:"13.8. Temporary or permanent impossibility of transferring a specific Item due to limitations of Steam, Valve or other external system does not in itself transform the Internal Balance into a monetary obligation of the Operator and does not provide the User with an unconditional right to demand its payment in cash, unless otherwise expressly provided by the Applicable Law."},{type:"paragraph",contentRu:"13.9. Ссылки, интерфейсные переходы и иные способы доступа к сторонним сайтам, приложениям или сервисам могут предоставляться исключительно для обеспечения функциональности Платформы или удобства Пользователя. Если иное прямо не предусмотрено законом, Оператор не контролирует и не несет ответственности за содержание, доступность, безопасность, комиссии, правила использования или самостоятельную обработку данных такими третьими лицами.",contentEn:"13.9. Links, interface transitions and other methods of access to third-party sites, applications or services may be provided solely to ensure the functionality of the Platform or the convenience of the User. Unless otherwise expressly provided by law, the Operator has no control over and is not responsible for the content, availability, security, fees, rules of use or self-processing of data by such third parties."},{type:"paragraph",contentRu:"13.10. Пользователь самостоятельно обеспечивает и оплачивает оборудование, программное обеспечение, интернет-соединение, доступ к Steam и иные технические средства, необходимые для использования Платформы. Оператор не отвечает за невозможность или ненадлежащее использование Платформы, обусловленные неисправностью либо несовместимостью оборудования, программного обеспечения, интернет-соединения или сторонних учетных записей Пользователя.",contentEn:"13.10. The User independently provides and pays for equipment, software, Internet connection, access to Steam and other technical means necessary to use the Platform. The Operator is not responsible for the inability or improper use of the Platform due to malfunction or incompatibility of equipment, software, Internet connection or third-party User accounts."},{type:"paragraph",contentRu:"13.11. Оператор и соответствующие третьи лица являются самостоятельными участниками правоотношений в пределах предоставляемых ими сервисов. Если прямо не предусмотрено иное, настоящее Соглашение не создает агентских, партнерских или иных представительских отношений между Оператором и Valve либо иным сторонним поставщиком и не предоставляет Пользователю право требовать от такого третьего лица исполнения обязательств Оператора или от Оператора — исполнения обязательств соответствующего третьего лица.",contentEn:"13.11. The Operator and relevant third parties are independent participants in legal relations within the scope of the services they provide. Except as expressly provided otherwise, this Agreement does not create an agency, partnership or other representative relationship between the Operator and Valve or any other third party supplier and does not provide the User with the right to require such third party to perform the obligations of the Operator or from the Operator to perform the obligations of the relevant third party."},{type:"subtitle",contentRu:"14. Запрещенные действия Пользователя",contentEn:"14. Prohibited User Conduct",level:1},{type:"paragraph",contentRu:"14.1. Пользователь обязан использовать Платформу добросовестно, лично, в соответствии с ее назначением, настоящим Соглашением и Применимым законодательством. Пользователь не вправе совершать действия, направленные на обход установленных Оператором правил, ограничений, механизмов безопасности, контроля и управления рисками.",contentEn:"14.1. The User shall use the Platform in good faith, personally, in accordance with its purpose, this Agreement and Applicable Law. The User may not take actions aimed at circumventing the rules, restrictions, security mechanisms, control and risk management established by the Operator."},{type:"paragraph",contentRu:"14.2. Запрещается создание или использование нескольких Аккаунтов одним Пользователем, если иное прямо не разрешено Оператором, передача, продажа, аренда Аккаунта или предоставление доступа к нему третьим лицам, совместное управление Аккаунтом, регистрация с использованием данных подставного или иного третьего лица, а также подключение или использование Steam-аккаунта, которым Пользователь не вправе распоряжаться.",contentEn:"14.2. The User may not create or use multiple Accounts unless the Operator expressly permits it; transfer, sell, rent or share an Account; jointly control an Account; register using nominee or third-party data; or connect or use a Steam Account that the User does not lawfully control."},{type:"paragraph",contentRu:"14.3. Запрещается осуществлять Пополнение с использованием украденного, поддельного, недействительного, скомпрометированного либо принадлежащего третьему лицу платежного средства без надлежащего согласия его законного владельца, а равно использовать платежные реквизиты, документы или идентификационные данные, полученные незаконным путем либо предоставленные Оператору с целью введения его или платежного партнера в заблуждение.",contentEn:"14.3. The User may not make a Top-Up using a stolen, counterfeit, invalid, compromised or third-party payment method without the lawful owner's valid consent, or use unlawfully obtained payment details, documents or identification data, or information submitted to mislead the Operator or a payment partner."},{type:"paragraph",contentRu:"14.4. Запрещается использовать Платформу в качестве платежного, расчетного или транзитного инструмента, в том числе для передачи ценности между третьими лицами, обналичивания средств, сокрытия или искажения их происхождения, проведения транзитных операций, арбитража платежных инструментов, легализации доходов, финансирования противоправной деятельности либо обхода платежных, санкционных, комплаенс- или иных установленных ограничений.",contentEn:"14.4. It is prohibited to use the Platform as a payment, settlement or transit instrument, including for transferring value between third parties, cashing out funds, concealing or distorting their origin, conducting transit operations, arbitration of payment instruments, money laundering, financing illegal activities, or circumventing payment, sanction, compliance or other established restrictions."},{type:"paragraph",contentRu:"14.5. Запрещается использовать VPN, прокси-серверы, средства подмены IP-адреса или геолокации, эмуляцию устройств, поддельные либо недостоверные документы, чужие идентификационные данные и иные технические или организационные средства, если целью или фактическим результатом такого использования является обход территориальных, возрастных, санкционных, платежных, идентификационных или иных ограничений, применяемых Оператором или предусмотренных Применимым законодательством.",contentEn:"14.5. It is prohibited to use VPN, proxy servers, IP address or geolocation spoofing tools, device emulation, fake or unreliable documents, other people’s identification data and other technical or organizational means if the purpose or actual result of such use is to bypass territorial, age, sanctions, payment, identification or other restrictions applied by the Operator or provided for by Applicable Law."},{type:"paragraph",contentRu:"14.6. Запрещается осуществлять несанкционированное вмешательство в программное обеспечение или инфраструктуру Платформы, включая декомпиляцию, обратную разработку, изменение или подмену запросов и ответов, внедрение программного кода, обход средств аутентификации или безопасности, несанкционированный доступ, перехват данных, DDoS-атаки, создание чрезмерной нагрузки на API, а также поиск, сканирование или эксплуатацию уязвимостей без предварительного разрешения Оператора, кроме случаев и в пределах, прямо допускаемых Применимым законодательством.",contentEn:"14.6. You are prohibited from tampering with the software or infrastructure of the Platform, including decompiling, reverse engineering, modifying or substituting requests and responses, code injection, bypassing authentication or security measures, unauthorized access, data interception, DDoS attacks, creating excessive load on the API, or searching, scanning or exploiting vulnerabilities without the prior permission of the Operator, except in cases and to the extent expressly permitted by Applicable Law."},{type:"paragraph",contentRu:"14.7. Запрещается использование ботов, скриптов, макросов, автокликеров, эмуляторов, специализированных расширений и иных средств автоматизации для совершения Игровых операций, получения или сбора наград, массового направления запросов, автоматизированного управления Аккаунтом либо получения преимуществ перед иными Пользователями, если соответствующая автоматизация прямо не предусмотрена функционалом Платформы или предварительно не разрешена Оператором.",contentEn:"14.7. The User may not use bots, scripts, macros, autoclickers, emulators, specialized extensions or other automation to perform Game Operations, obtain rewards, send mass requests, manage an Account automatically or gain an advantage over other Users, unless the automation is expressly supported by Platform functionality or authorized by the Operator in advance."},{type:"paragraph",contentRu:"14.8. Запрещается сознательно использовать Технические ошибки, уязвимости, задержки обновления цен, дублирование операций, рассинхронизацию данных, некорректное начисление, ошибочное отображение либо иные технические отклонения с целью получения условных единиц, Предметов, преимуществ или иного результата, который Пользователь знал либо с учетом обстоятельств разумно должен был понимать как ошибочный.",contentEn:"14.8. It is prohibited to knowingly use Technical Errors, vulnerabilities, delays in price updates, duplication of operations, data desynchronization, incorrect accrual, erroneous display or other technical deviations in order to obtain notional units, Items, benefits or other results that the User knew or, given the circumstances, reasonably should have understood as erroneous."},{type:"paragraph",contentRu:"14.9. Запрещаются сговор с другими Пользователями, манипулирование операциями или результатами, создание фиктивной активности, искусственное формирование показателей, обход установленных лимитов, а также недобросовестное или многократное использование бонусных, промо-, реферальных программ, механизмов возврата или иных стимулирующих функций способом, не соответствующим их назначению.",contentEn:"14.9. Conspiracy with other Users, manipulation of transactions or results, creation of fictitious activity, artificial formation of indicators, circumvention of established limits, as well as unfair or repeated use of bonus, promotional, referral programs, return mechanisms or other incentive functions in a manner inconsistent with their purpose are prohibited."},{type:"paragraph",contentRu:"14.10. Без предварительного письменного согласия Оператора запрещается принимать денежные средства или иные ценности третьих лиц для последующего использования на Платформе, управлять чужими Аккаунтами в коммерческих или посреднических целях, продавать или иным образом предоставлять третьим лицам обещание осуществления Вывода, а также организовывать на базе Платформы не предусмотренные ее функционалом посреднические, обменные, расчетные или иные коммерческие услуги.",contentEn:"14.10. Without the Operator's prior written consent, the User may not accept third-party funds or assets for use on the Platform, manage another person's Account for commercial or intermediary purposes, sell or promise a Withdrawal service to a third party, or use the Platform to provide intermediary, exchange, settlement or other unsupported commercial services."},{type:"paragraph",contentRu:"14.11. Запрещается выдавать себя за Оператора, его работника, представителя службы поддержки, платежного партнера либо другого Пользователя, использовать сходные до степени смешения обозначения, создавать фишинговые или имитационные сайты, страницы и интерфейсы, распространять заведомо ложные сообщения от имени Оператора либо иным способом вводить третьих лиц в заблуждение относительно своей связи с Платформой.",contentEn:"14.11. The User may not impersonate the Operator, its employee, support representative, payment partner or another User; use confusingly similar branding; create phishing or imitation sites, pages or interfaces; issue knowingly false statements in the Operator's name; or otherwise mislead a third party about the User's association with the Platform."},{type:"paragraph",contentRu:"14.12. Без соответствующего разрешения запрещается осуществлять систематическое автоматизированное копирование, парсинг, скрейпинг, массовое извлечение, воспроизведение, распространение либо коммерческое использование программных элементов, баз данных, текстов, дизайна, графических материалов и иных объектов Платформы, за исключением случаев, когда соответствующее действие прямо допускается Применимым законодательством.",contentEn:"14.12. Without appropriate permission, it is prohibited to carry out systematic automated copying, parsing, scraping, mass extraction, reproduction, distribution or commercial use of program elements, databases, texts, designs, graphic materials and other objects of the Platform, except in cases where the corresponding action is expressly permitted by Applicable Law."},{type:"paragraph",contentRu:"14.13. Запрещается использовать Платформу для совершения противоправных действий, нарушения интеллектуальных, имущественных, персональных или иных прав третьих лиц, распространения вредоносного программного обеспечения, осуществления мошенничества, незаконной рекламы, угроз либо иной деятельности, запрещенной Применимым законодательством.",contentEn:"14.13. It is prohibited to use the Platform to commit illegal acts, violate intellectual, property, personal or other rights of third parties, distribute malicious software, commit fraud, illegal advertising, threats or other activities prohibited by Applicable Law."},{type:"paragraph",contentRu:"14.14. Пользователь обязан прекратить соответствующее действие после получения обоснованного уведомления Оператора о том, что оно нарушает настоящее Соглашение либо создает существенную угрозу безопасности, стабильности или законному функционированию Платформы. Пользователь вправе обратиться в службу поддержки для получения разъяснений и оспаривания соответствующего ограничения в предусмотренном Оператором порядке.",contentEn:"14.14. The User shall terminate the corresponding action upon receipt of reasonable notification from the Operator that it violates this Agreement or creates a significant threat to the security, stability or legal functioning of the Platform. The User may contact the support service to obtain clarification and challenge the relevant restriction in the manner prescribed by the Operator."},{type:"paragraph",contentRu:"14.15. Попытка совершения любого из запрещенных настоящим разделом действий может рассматриваться как нарушение независимо от достижения предполагаемого результата, если совокупность Серверных данных и иных объективных обстоятельств разумно подтверждает направленность действий Пользователя на совершение соответствующего нарушения.",contentEn:"14.15. An attempt to commit any of the actions prohibited by this section may be considered a violation, regardless of the achievement of the intended result, if the totality of Server Data and other objective circumstances reasonably confirms the direction of the User’s actions to commit the corresponding violation."},{type:"paragraph",contentRu:"14.16. При выявлении предполагаемого нарушения Оператор вправе учитывать совокупность доступных технических, платежных, поведенческих и иных объективных признаков. Существенные имущественные последствия не должны применяться исключительно на основании необъясненного автоматического сигнала системы контроля без проведения разумной проверки обстоятельств, за исключением временных обеспечительных мер, необходимых для предотвращения непосредственного ущерба, мошенничества или дальнейшего нарушения.",contentEn:"14.16. When identifying an alleged violation, the Operator may take into account the totality of available technical, payment, behavioral and other objective signs. Significant economic consequences should not be imposed solely on the basis of an unexplained automatic control signal without a reasonable examination of the circumstances, except for interim measures necessary to prevent immediate harm, fraud or further infringement."},{type:"subtitle",contentRu:"15. KYC, AML/CFT",contentEn:"15. KYC and AML/CFT",level:1},{type:"paragraph",contentRu:"15.1. В целях обеспечения безопасности Платформы, предотвращения мошенничества, неправомерного использования платежных средств, легализации (отмывания) доходов, финансирования терроризма, обхода санкционных ограничений и иных противоправных действий Оператор вправе применять риск-ориентированные процедуры идентификации, верификации, мониторинга и проверки Пользователей и совершаемых ими операций (KYC, AML/CFT, sanctions screening и anti-fraud controls) в объеме, предусмотренном Применимым законодательством, требованиями платежных партнеров и обоснованной оценкой соответствующих рисков.",contentEn:"15.1. In order to ensure the security of the Platform, prevent fraud, misuse of payment instruments, launder proceeds, finance terrorism, bypass sanctions restrictions and other illegal actions, the Operator may apply risk-based procedures for identifying, verifying, monitoring and checking Users and their transactions (KYC, AML/CFT, sanctions screening and anti-fraud controls) to the extent provided for by Applicable Law, the requirements of payment partners and a reasonable assessment of the relevant risks."},{type:"paragraph",contentRu:"15.2. Используя Платформу, Пользователь подтверждает, что денежные средства и иные ценности, используемые им в связи с Платформой, имеют законное происхождение, а Пользователь обладает необходимыми правами и полномочиями в отношении каждого используемого платежного средства, Steam-аккаунта, документа, идентификационных данных и иных предоставляемых сведений. Пользователь не вправе предоставлять сведения или документы третьих лиц без надлежащего правового основания.",contentEn:"15.2. By using the Platform, the User represents that all funds and other assets used in connection with it are from lawful sources and that the User has the necessary rights and authority over each payment method, Steam Account, document, identifier and other item of information provided. The User may not provide third-party information or documents without a valid legal basis."},{type:"paragraph",contentRu:"15.3. Оператор вправе инициировать первоначальную или повторную проверку Пользователя, в частности при регистрации или использовании Аккаунта, совершении Пополнения, достижении установленных стоимостных или операционных лимитов, запросе Вывода, существенном изменении географических или платежных параметров, возникновении платежного спора, выявлении необычной либо аномальной активности, получении информации о возможном нарушении или при наличии иного объективного риск-индикатора.",contentEn:"15.3. The Operator may initiate an initial or re-verification of the User, in particular when registering or using an Account, making a Deposit, reaching established value or transaction limits, requesting a Withdrawal, a significant change in geographic or payment parameters, the occurrence of a payment dispute, identifying unusual or anomalous activity, receiving information about a possible violation, or if there is another objective risk indicator."},{type:"paragraph",contentRu:"15.4. В рамках проверки Оператор вправе запросить сведения и документы, разумно необходимые для идентификации Пользователя, подтверждения законности и экономического характера соответствующих операций, включая документ, удостоверяющий личность, подтверждение адреса, сведения об источнике средств и, когда это обоснованно уровнем риска, источнике благосостояния, банковскую или иную платежную выписку, подтверждение владения платежным средством, селфи, прохождение видеоверификации или проверки присутствия (liveness check), сведения о Steam-аккаунте, а также пояснения относительно отдельных операций.",contentEn:"15.4. As part of the verification, the Operator may request information and documents reasonably necessary to identify the User, confirm the legality and economic nature of the relevant transactions, including an identification document, proof of address, information about the source of funds and, when justified by the level of risk, the source of wealth, a bank or other payment statement, proof of ownership of a means of payment, a selfie, a video verification or liveness check, information about the Steam Account, as well as explanations regarding individual transactions."},{type:"paragraph",contentRu:"15.5. Объем и глубина проверки определяются с учетом характера и размера операций, выявленных риск-факторов, требований соответствующего платежного или верификационного партнера и Применимого законодательства. Оператор вправе повторно запросить документы или сведения, если ранее предоставленная информация утратила актуальность, не позволяет завершить проверку, содержит существенные расхождения либо после ее предоставления возникли новые обстоятельства или риск-индикаторы.",contentEn:"15.5. The scope and depth of the review is determined taking into account the nature and size of the transactions, identified risk factors, the requirements of the relevant payment or verification partner and Applicable Law. The Operator may re-request documents or information if the previously provided information is no longer relevant, does not allow the verification to be completed, contains significant discrepancies, or new circumstances or risk indicators have arisen after its provision."},{type:"paragraph",contentRu:"15.6. До завершения необходимой проверки Оператор вправе временно полностью или частично ограничить Пополнения, Игровые операции, Вывод, распоряжение Предметами и иные функции Аккаунта в объеме и на срок, разумно необходимые для проведения проверки, предотвращения возможного ущерба, соблюдения требований Применимого законодательства или выполнения обязательных требований платежных и иных уполномоченных партнеров.",contentEn:"15.6. Until the completion of the necessary verification, the Operator may temporarily completely or partially limit Top-Ups, Game Operations, Withdrawals, disposal of Items and other functions of the Account to the extent and for a period reasonably necessary to conduct the verification, prevent possible damage, comply with the requirements of Applicable Law or fulfill the mandatory requirements of payment and other authorized partners."},{type:"paragraph",contentRu:"15.7. Необоснованный отказ или уклонение Пользователя от прохождения необходимой проверки, систематическое непредоставление запрошенных сведений, предоставление существенно противоречивой, недостоверной, вводящей в заблуждение либо предположительно поддельной информации может являться основанием для сохранения соответствующих ограничений, отказа в совершении отдельных операций или прекращения обслуживания Пользователя после разумной оценки обстоятельств и в пределах, допускаемых Применимым законодательством.",contentEn:"15.7. An unjustified refusal or failure to complete required verification, repeated failure to provide requested information, or provision of materially contradictory, inaccurate, misleading or apparently fraudulent information may justify maintaining relevant restrictions, refusing a transaction or terminating service after a reasonable assessment and to the extent permitted by Applicable Law."},{type:"paragraph",contentRu:"15.8. Пользователю запрещается прямо или косвенно использовать Платформу в интересах либо по поручению лица, в отношении которого применяются обязательные для Оператора санкционные или иные ограничительные меры, а также совершать действия, направленные на сокрытие соответствующего лица, происхождения или назначения средств, фактического участника операции либо на обход применимых санкционных ограничений.",contentEn:"15.8. The User is prohibited from directly or indirectly using the Platform in the interests of or on behalf of a person in respect of whom sanctions or other restrictive measures are mandatory for the Operator, as well as from taking actions aimed at concealing the relevant person, the origin or purpose of funds, the actual participant in the transaction, or to circumvent the applicable sanctions restrictions."},{type:"paragraph",contentRu:"15.9. Оператор вправе осуществлять проверку Пользователя, предоставленных им идентификационных данных, платежных реквизитов и иных связанных с операциями сведений по доступным Оператору законным источникам, включая применимые санкционные перечни, сведения о политически значимых лицах (PEP), антифрод-базы, данные верификационных и платежных партнеров, а также иные источники, использование которых допускается Применимым законодательством.",contentEn:"15.9. The Operator may check the User, the identification data provided by him, payment details and other information related to transactions using legal sources available to the Operator, including applicable sanctions lists, information about politically exposed persons (PEP), anti-fraud databases, data from verification and payment partners, as well as other sources, the use of which is permitted by Applicable Law."},{type:"paragraph",contentRu:"15.10. Персональные данные, документы и иная информация, полученные в рамках предусмотренных настоящим разделом проверок, обрабатываются в соответствии с Политикой конфиденциальности и Применимым законодательством и могут храниться в течение сроков, необходимых для выполнения установленных законом обязанностей, разрешения споров, подтверждения проведенных проверок, предотвращения мошенничества и защиты законных интересов Оператора и третьих лиц.",contentEn:"15.10. Personal data, documents and other information received as part of the checks provided for in this section are processed in accordance with the Privacy Policy and Applicable Law and may be stored for periods necessary to fulfill statutory obligations, resolve disputes, confirm checks carried out, prevent fraud and protect the legitimate interests of the Operator and third parties."},{type:"paragraph",contentRu:"15.11. Оператор вправе передавать сведения, относящиеся к Пользователю и его операциям, компетентным государственным органам, платежным организациям, банкам, верификационным и иным уполномоченным лицам при наличии соответствующего правового основания, обязательного требования или законного запроса. Оператор вправе ограничить раскрытие Пользователю информации о проводимой проверке, ее методах, результатах или передаче сведений, если такое раскрытие запрещено законом, способно воспрепятствовать проверке или расследованию либо создать риск обхода механизмов безопасности и контроля.",contentEn:"15.11. Where supported by an appropriate legal basis, binding requirement or lawful request, the Operator may disclose information about the User and the User's transactions to competent authorities, payment organizations, banks, verification providers and other authorized recipients. It may withhold details where disclosure is prohibited by law, could prejudice a review or investigation, or creates a risk of circumvention of security controls."},{type:"paragraph",contentRu:"15.12. Выявление риск-индикатора, совпадения в базе данных либо иной подозрительной активности само по себе не означает установления нарушения со стороны Пользователя. Необходимость направления сообщений компетентным органам, блокирования операций, сохранения ограничений и принятия иных мер определяется Оператором исходя из конкретных обстоятельств и требований Применимого законодательства; настоящее Соглашение не устанавливает безусловной обязанности применять одинаковые меры при каждом выявленном подозрении.",contentEn:"15.12. Identification of a risk indicator, a match in the database, or other suspicious activity does not in itself mean the establishment of a violation on the part of the User. The need to send messages to the competent authorities, block transactions, maintain restrictions and take other measures is determined by the Operator based on the specific circumstances and requirements of Applicable Law; This Agreement does not establish an unconditional obligation to apply the same measures for each identified suspicion."},{type:"paragraph",contentRu:"15.13. После устранения обстоятельств, послуживших основанием для проверки или временных ограничений, Оператор снимает соответствующие ограничения в разумный срок, если отсутствуют иные законные основания для их сохранения. В случае подтверждения нарушения Оператор вправе применить предусмотренные настоящим Соглашением и Применимым законодательством меры, соразмерные характеру нарушения, установленному риску и его фактическим последствиям.",contentEn:"15.13. After eliminating the circumstances that served as the basis for verification or temporary restrictions, the Operator removes the corresponding restrictions within a reasonable time, unless there are other legal grounds for maintaining them. If a violation is confirmed, the Operator may apply measures provided for in this Agreement and Applicable Law, commensurate with the nature of the violation, the established risk and its actual consequences."},{type:"paragraph",contentRu:"15.14. Проведение проверки в соответствии с настоящим разделом является стандартной мерой управления рисками и само по себе не означает обвинения Пользователя в совершении противоправных действий. Такие процедуры применяются в целях защиты Платформы, ее Пользователей, платежных партнеров и иных третьих лиц, а также обеспечения соблюдения применимых правовых и договорных требований.",contentEn:"15.14. Conducting a check in accordance with this section is a standard risk management measure and does not in itself mean accusing the User of committing illegal actions. These procedures are used to protect the Platform, its Users, payment partners and other third parties, and to ensure compliance with applicable legal and contractual requirements."},{type:"subtitle",contentRu:"16. Мониторинг",contentEn:"16. Monitoring",level:1},{type:"paragraph",contentRu:"16.1. В целях обеспечения безопасности Платформы, предотвращения мошенничества и иных злоупотреблений, исполнения настоящего Соглашения и соблюдения Применимого законодательства Оператор вправе осуществлять автоматизированный и ручной мониторинг Аккаунтов, платежей, Игровых операций, устройств, сетевых и технических параметров, а также иных объективных признаков, позволяющих выявлять взаимосвязанные Аккаунты, аномальную активность и потенциальные нарушения.",contentEn:"16.1. In order to ensure the security of the Platform, prevent fraud and other abuses, execute this Agreement and comply with the Applicable Law, the Operator may carry out automated and manual monitoring of Accounts, payments, Game Operations, devices, network and technical parameters, as well as other objective signs that allow identifying interconnected Accounts, abnormal activity and potential violations."},{type:"paragraph",contentRu:"16.2. При наличии разумных оснований полагать, что Аккаунт, операция или действия Пользователя могут быть связаны с нарушением настоящего Соглашения, мошенничеством, Технической ошибкой, несанкционированным платежом, угрозой безопасности либо иной противоправной деятельностью, Оператор вправе инициировать проверку, сохранить относящиеся к соответствующему событию данные и доказательства, запросить у Пользователя необходимые сведения и объяснения, а также применить временные обеспечительные меры.",contentEn:"16.2. If there are reasonable grounds to believe that the User's Account, transaction or actions may be associated with a violation of this Agreement, fraud, Technical Error, unauthorized payment, security threat or other illegal activity, the Operator may initiate an audit, retain data and evidence related to the relevant event, request the necessary information and explanations from the User, and apply temporary interim measures."},{type:"paragraph",contentRu:"16.3. На период проведения проверки Оператор вправе временно ограничить Пополнения, Игровые операции, использование Внутреннего баланса, распоряжение Предметами, Вывод либо иные непосредственно затронутые функции Аккаунта. Объем и продолжительность таких ограничений должны соответствовать характеру предполагаемого риска и могут изменяться по мере получения и оценки дополнительной информации.",contentEn:"16.3. During the period of verification, the Operator may temporarily limit Top-Ups, Game Operations, use of Internal Balance, disposal of Items, Withdrawals or other directly affected functions of the Account. The extent and duration of such restrictions should be consistent with the nature of the risk anticipated and may change as additional information is obtained and assessed."},{type:"paragraph",contentRu:"16.4. По результатам проверки Оператор вправе прекратить применение временных ограничений либо, в зависимости от характера и тяжести установленного нарушения, вынести предупреждение, аннулировать неправомерно полученный бонус или иное начисление, скорректировать ошибочную операцию, ограничить использование отдельных функций Платформы, установить дополнительные требования к проверке, прекратить дальнейшее обслуживание Пользователя либо применить иные предусмотренные настоящим Соглашением и Применимым законодательством соразмерные меры.",contentEn:"16.4. Based on the results of the inspection, the Operator may terminate the application of temporary restrictions or, depending on the nature and severity of the established violation, issue a warning, cancel an unlawfully received bonus or other accrual, correct an erroneous operation, limit the use of certain functions of the Platform, establish additional verification requirements, terminate further service to the User, or apply other proportionate measures provided for in this Agreement and the Applicable Law."},{type:"paragraph",contentRu:"16.5. Аннулирование или корректировка конкретного Предмета, начисления либо операции допускается, если в результате разумной проверки установлена их непосредственная связь с подтвержденной Технической ошибкой, мошенничеством, несанкционированным или впоследствии отмененным платежом, эксплуатацией уязвимости, злоупотреблением функционалом Платформы либо иным нарушением, без которого соответствующий результат не был бы получен.",contentEn:"16.5. Cancellation or adjustment of a specific Item, accrual or transaction is permitted if, as a result of a reasonable verification, their direct connection is established with a confirmed Technical Error, fraud, unauthorized or subsequently canceled payment, exploitation of a vulnerability, abuse of the functionality of the Platform or other violation, without which the corresponding result would not have been obtained."},{type:"paragraph",contentRu:"16.6. Само по себе обращение Пользователя с претензией, добросовестное инициирование платежного спора, использование предусмотренного законом механизма защиты прав либо наличие неподтвержденного подозрения не является достаточным основанием для безусловного аннулирования всего Внутреннего баланса, всех Предметов или иных принадлежащих Пользователю результатов операций.",contentEn:"16.6. The User's filing of a claim, the initiation of a payment dispute in good faith, the use of a mechanism for protecting rights provided by law, or the presence of an unconfirmed suspicion in itself is not a sufficient basis for the unconditional cancellation of the entire Internal Balance, all Items or other results of operations belonging to the User."},{type:"paragraph",contentRu:"16.7. При подтвержденном нарушении Оператор вправе, если это допускается Применимым законодательством, произвести удержание, сторнирование или зачет в размере, необходимом для аннулирования ошибочного либо неправомерного начисления, покрытия отмененного платежа, устранения отрицательного баланса и возмещения документально подтвержденного прямого ущерба, непосредственно возникшего вследствие соответствующего нарушения. Такие меры не должны превышать размер соответствующей задолженности или установленного ущерба, если иное прямо не предусмотрено законом.",contentEn:"16.7. In the event of a confirmed violation, the Operator has the right, if permitted by Applicable Law, to make a withholding, reversal or offset in the amount necessary to cancel the erroneous or improper accrual, cover the canceled payment, eliminate the negative balance and compensate for documented direct damages that directly arose as a result of the relevant violation. Such measures should not exceed the amount of the relevant debt or established damage, unless otherwise expressly provided by law."},{type:"paragraph",contentRu:"16.8. Оператор вправе окончательно прекратить обслуживание и закрыть либо заблокировать Аккаунт в случае существенного или неоднократного нарушения настоящего Соглашения, подтвержденного мошенничества или иного противоправного поведения, обхода ранее примененных ограничений, необоснованного отказа от обязательной проверки, создания существенной угрозы безопасности Платформы или третьих лиц, а также если дальнейшее обслуживание Пользователя объективно невозможно без нарушения Применимого законодательства или обязательных требований соответствующего платежного партнера.",contentEn:"16.8. The Operator may permanently terminate service and close or block the Account in the event of a significant or repeated violation of this Agreement, confirmed fraud or other illegal behavior, circumvention of previously applied restrictions, unreasonable refusal of mandatory verification, creation of a significant threat to the security of the Platform or third parties, and also if further service to the User is objectively impossible without violating the Applicable Law or the mandatory requirements of the relevant payment partner."},{type:"paragraph",contentRu:"16.9. При прекращении или существенном ограничении обслуживания Оператор вправе не раскрывать Пользователю конкретные алгоритмы, правила антифрод-систем, внутренние риск-индикаторы, методы выявления взаимосвязанных Аккаунтов и иные сведения, раскрытие которых способно создать угрозу безопасности либо способствовать обходу механизмов контроля. По запросу Пользователя Оператор, насколько это допускается законом и требованиями безопасности, вправе сообщить общую категорию обстоятельств, послуживших основанием для принятого решения.",contentEn:"16.9. Upon termination or significant limitation of service, the Operator has the right not to disclose to the User specific algorithms, rules of anti-fraud systems, internal risk indicators, methods for identifying interconnected Accounts and other information, the disclosure of which could create a security threat or contribute to bypassing control mechanisms. At the User's request, the Operator, to the extent permitted by law and security requirements, may report the general category of circumstances that served as the basis for the decision."},{type:"paragraph",contentRu:"16.10. Пользователь вправе направить в службу поддержки мотивированное возражение относительно примененной меры и предоставить документы, сведения или иные доказательства, имеющие значение для пересмотра решения. Такое обращение подлежит рассмотрению Оператором либо уполномоченным им лицом, обладающим возможностью оценить представленные материалы и, при наличии достаточных оснований, изменить или отменить первоначально принятое решение.",contentEn:"16.10. The User may submit a reasoned objection to support and provide evidence relevant to review of the measure. The objection shall be considered by the Operator or an authorized reviewer capable of assessing the material and, where sufficient grounds exist, modifying or reversing the original decision."},{type:"paragraph",contentRu:"16.11. Ограничения, установленные в отношении одного Аккаунта, могут быть распространены на иные Аккаунты только при наличии объективных технических, идентификационных, платежных или иных данных, указывающих на общий контроль над такими Аккаунтами, их использование в рамках совместного нарушения либо создание или использование дополнительного Аккаунта с целью обхода ранее примененных мер.",contentEn:"16.11. Restrictions established in relation to one Account can be extended to other Accounts only if there is objective technical, identification, payment or other data indicating common control over such Accounts, their use as part of a joint violation, or the creation or use of an additional Account to circumvent previously applied measures."},{type:"paragraph",contentRu:"16.12. В рамках проведения проверок, предотвращения и расследования нарушений Оператор вправе взаимодействовать с платежными организациями, банками, верификационными и антифрод-провайдерами, Valve, соответствующими правообладателями, поставщиками технических сервисов и компетентными государственными органами, а также передавать им необходимые сведения при наличии надлежащего правового основания и с соблюдением Политики конфиденциальности и Применимого законодательства.",contentEn:"16.12. As part of inspections, prevention and investigation of violations, the Operator may interact with payment organizations, banks, verification and anti-fraud providers, Valve, relevant copyright holders, technical service providers and competent government bodies, as well as transfer the necessary information to them if there is an appropriate legal basis and in compliance with the Privacy Policy and Applicable Law."},{type:"paragraph",contentRu:"16.13. Если по результатам проверки предполагаемое нарушение не подтверждено, Оператор снимает обусловленные исключительно такой проверкой ограничения и, при необходимости, восстанавливает корректное состояние учета в разумный срок. Изменение рыночной, торговой или иной внешней стоимости Предметов в период обоснованной проверки само по себе не создает права на компенсацию соответствующей разницы, кроме случаев, когда такая компенсация прямо предусмотрена Применимым законодательством.",contentEn:"16.13. If a review does not confirm the suspected breach, the Operator shall remove restrictions caused solely by that review and, where necessary, restore the correct accounting position within a reasonable time. A change in an Item's external value during a reasonable review does not, by itself, entitle the User to the difference unless Applicable Law expressly provides otherwise."},{type:"paragraph",contentRu:"16.14. Независимо от иных положений настоящего раздела Оператор вправе незамедлительно применять необходимые технические и обеспечительные меры без предварительного уведомления Пользователя, если промедление способно привести к продолжению кибератаки, утечке или компрометации данных, массовому мошенничеству, несанкционированному выводу ценностей, нарушению безопасности Платформы либо иному непосредственному и существенному ущербу. После устранения непосредственной угрозы необходимость и объем дальнейших ограничений подлежат пересмотру с учетом фактически установленных обстоятельств.",contentEn:"16.14. The Operator may apply necessary technical and security measures immediately and without prior notice where delay could allow a cyberattack, data leak or compromise, mass fraud, unauthorized transfer of assets, a Platform security breach or other direct and material harm to continue. Once the immediate threat is removed, continuing restrictions shall be reviewed against the established facts."},{type:"subtitle",contentRu:"17. Интеллектуальная собственность и персональные данные",contentEn:"17. Intellectual Property and Personal Data",level:1},{type:"paragraph",contentRu:"17.1. Исключительные и иные права на Платформу и составляющие ее объекты, включая программное обеспечение, исходный и объектный код, архитектуру, интерфейсы, дизайн, тексты, графические элементы, базы данных, структуру, подбор и расположение материалов, принадлежат Оператору либо соответствующим правообладателям и охраняются в соответствии с Применимым законодательством и применимыми международными соглашениями.",contentEn:"17.1. All intellectual property and other proprietary rights in the Platform and its components, including software, source and object code, architecture, interfaces, designs, text, graphics, databases and the selection and arrangement of materials, belong to the Operator or the relevant rightsholder and are protected by Applicable Law and applicable international agreements."},{type:"paragraph",contentRu:"17.2. На период существования Аккаунта и при условии соблюдения настоящего Соглашения Оператор предоставляет Пользователю ограниченное, неисключительное, непередаваемое, несублицензируемое и отзывное право использовать доступный функционал и интерфейс Платформы исключительно для личных некоммерческих целей и в пределах ее предусмотренного назначения. Такое право не означает передачу Пользователю каких-либо исключительных прав на Платформу или ее отдельные элементы.",contentEn:"17.2. While the Account remains open and the User complies with this Agreement, the Operator grants the User a limited, non-exclusive, non-transferable, non-sublicensable and revocable right to use the available Platform interface and functionality solely for personal, non-commercial purposes and as intended. No intellectual property right is transferred to the User."},{type:"paragraph",contentRu:"17.3. Если иное прямо не разрешено Оператором или Применимым законодательством, Пользователь не вправе воспроизводить, копировать, модифицировать, адаптировать, распространять, публиковать, лицензировать, отчуждать, коммерчески использовать материалы Платформы, создавать на их основе производные продукты, а также удалять, скрывать или изменять сведения об авторских правах, товарных знаках и иных обозначениях правообладателей.",contentEn:"17.3. Unless the Operator or Applicable Law expressly permits otherwise, the User may not reproduce, copy, modify, adapt, distribute, publish, license, transfer or commercially exploit Platform materials; create derivative works from them; or remove, conceal or alter copyright, trademark or other proprietary notices."},{type:"paragraph",contentRu:"17.4. Товарные знаки, коммерческие обозначения, логотипы и иные объекты интеллектуальной собственности Valve, Steam, разработчиков соответствующих игр и иных третьих лиц, а также связанные с ними наименования, изображения и визуальные представления Предметов принадлежат соответствующим правообладателям. Использование таких объектов в рамках Платформы не означает передачу Оператору или Пользователю каких-либо прав на них сверх объема, допускаемого соответствующим правообладателем и Применимым законодательством, и само по себе не свидетельствует о наличии партнерства, спонсорства или одобрения Платформы соответствующим правообладателем.",contentEn:"17.4. Trademarks, trade names, logos and other intellectual property of Valve, Steam, game developers and other third parties, and related names, images and Item representations, belong to their respective owners. Their use on the Platform transfers no right beyond the scope permitted by the rightsholder and does not imply partnership, sponsorship or approval."},{type:"paragraph",contentRu:"17.5. Если Пользователь добровольно направляет Оператору предложения, отзывы, комментарии, идеи или рекомендации относительно функциональности и развития Платформы, Оператор вправе учитывать и использовать такие материалы для совершенствования Платформы без выплаты отдельного вознаграждения, если Пользователь и Оператор предварительно и прямо не согласовали иные условия. Настоящее положение не распространяется на персональные данные и иные сведения, правовой режим которых определяется Применимым законодательством.",contentEn:"17.5. If the User voluntarily submits suggestions, feedback, comments, ideas or recommendations about the Platform, the Operator may use them to improve it without separate compensation unless the Parties expressly agreed otherwise in advance. This clause does not apply to personal data or other information governed by a distinct legal regime."},{type:"paragraph",contentRu:"17.6. Сбор, использование, хранение, передача и иная обработка персональных данных Пользователя осуществляются в соответствии с применимой Политикой конфиденциальности и Применимым законодательством. Политика конфиденциальности является самостоятельным документом и определяет, в частности, категории обрабатываемых данных, цели и правовые основания обработки, категории получателей, применимые сроки хранения, порядок трансграничной передачи, а также предусмотренные законом права субъектов персональных данных.",contentEn:"17.6. The Operator collects, uses, stores, transfers and otherwise processes the User's personal data in accordance with the Privacy Policy and Applicable Law. The Privacy Policy is a separate document and describes the categories of data, purposes and legal bases of processing, recipient categories, retention periods, cross-border transfers and statutory rights of data subjects."},{type:"paragraph",contentRu:"17.7. При наличии отдельного, предварительного, свободно выраженного и однозначного согласия Пользователя Оператор вправе направлять на подтвержденный адрес электронной почты информационные и маркетинговые сообщения, включая сведения о бонусах, промокодах, новостях Платформы, персонализированных и специальных предложениях. Такое согласие предоставляется посредством активного подтверждающего действия в интерфейсе Платформы и не является условием регистрации Аккаунта или использования функций, непосредственно не связанных с соответствующей рассылкой, если иное прямо не допускается Применимым законодательством.",contentEn:"17.7. The Operator may send informational and marketing communications to the User's verified email address, including information about Bonuses, promotional codes, Platform news and personalized or special offers, only where the User has given separate, prior, freely given and unambiguous consent. Consent shall be provided through an affirmative action in the Platform interface and shall not be a condition of Account registration or access to unrelated functions unless Applicable Law expressly permits otherwise."},{type:"paragraph",contentRu:"17.8. В целях оформления и администрирования подписки Оператор может обрабатывать адрес электронной почты, идентификаторы и иные необходимые данные Аккаунта, сведения о настройках и статусе подписки, факте и времени предоставления либо отзыва согласия, а также технические данные, необходимые для подтверждения адреса, доставки сообщений и учета взаимодействия с ними. Правовым основанием такой обработки является согласие Пользователя, а в случаях, прямо предусмотренных Применимым законодательством, — иное применимое правовое основание, указанное в Политике конфиденциальности.",contentEn:"17.8. To create and administer the subscription, the Operator may process the User's email address, Account identifiers and other necessary Account data, subscription settings and status, the fact and time of giving or withdrawing consent, and technical data required to verify the address, deliver communications and record interactions. The legal basis is the User's consent or another basis expressly permitted by Applicable Law and identified in the Privacy Policy."},{type:"paragraph",contentRu:"17.9. Пользователь вправе в любое время отказаться от получения маркетинговых сообщений посредством ссылки «Отписаться», размещенной в соответствующем электронном письме, изменения настроек уведомлений в Аккаунте либо обращения в службу поддержки. Отказ от маркетинговой рассылки не влияет на законность обработки, осуществленной до отзыва согласия, и не прекращает направление сервисных, транзакционных, технических и иных сообщений, необходимых для исполнения настоящего Соглашения, обеспечения безопасности Аккаунта или выполнения требований Применимого законодательства.",contentEn:"17.9. The User may opt out of marketing communications at any time through the 'Unsubscribe' link in the relevant email, Account notification settings or support. Opting out does not affect processing before consent was withdrawn and does not stop service, transactional, technical or other communications required to perform this Agreement, protect the Account or comply with Applicable Law."},{type:"paragraph",contentRu:"17.10. После получения отказа Оператор прекращает направление маркетинговых сообщений без неоправданной задержки с учетом разумного срока, необходимого для технического обновления настроек рассылки. Сведения о факте отказа могут сохраняться в объеме и в течение срока, необходимых для соблюдения волеизъявления Пользователя, предотвращения повторной отправки сообщений без нового согласия, подтверждения исполнения требований Применимого законодательства и защиты законных интересов Оператора.",contentEn:"17.10. After receiving an opt-out request, the Operator shall stop marketing communications without undue delay, allowing a reasonable period for technical updates. Opt-out records may be retained as necessary to honor the User's choice, prevent renewed communications without fresh consent, demonstrate compliance and protect legitimate interests."},{type:"paragraph",contentRu:"17.11. Для подтверждения адреса электронной почты, управления подпиской и доставки сообщений Оператор вправе привлекать поставщиков соответствующих технологических услуг, включая OneSignal и подключенного поставщика услуг электронной почты. Категории передаваемых данных, конкретные получатели, цели и правовые основания обработки, места обработки, условия трансграничной передачи и применимые сроки хранения определяются Политикой конфиденциальности и Применимым законодательством.",contentEn:"17.11. The Operator may engage technology providers, including OneSignal and the connected email service provider, to verify email addresses, manage subscriptions and deliver communications. The data categories, recipients, purposes and legal bases, processing locations, cross-border transfer conditions and retention periods are governed by the Privacy Policy and Applicable Law."},{type:"paragraph",contentRu:"17.12. В связи с предоставлением и обеспечением функционирования Платформы Оператор может обрабатывать предусмотренные Политикой конфиденциальности сведения, включая Steam ID и иные идентификаторы связанных учетных записей, данные Аккаунта, IP-адрес и сетевые параметры, сведения об устройстве и программном обеспечении, cookie и аналогичные идентификаторы, платежные и транзакционные идентификаторы, историю операций, обращения в службу поддержки, а также сведения и документы, полученные в рамках идентификационных, KYC, AML/CFT, санкционных и антифрод-проверок.",contentEn:"17.12. In operating the Platform, the Operator may process information described in the Privacy Policy, including Steam ID and related account identifiers, Account data, IP address and network parameters, device and software information, cookies and similar identifiers, payment and transaction identifiers, transaction history, support communications, and information and documents obtained through identification, KYC, AML/CFT, sanctions and anti-fraud checks."},{type:"paragraph",contentRu:"17.13. В целях обеспечения безопасности Платформы, предотвращения мошенничества и злоупотреблений, выявления аномальной активности и управления рисками Оператор вправе использовать автоматизированные средства анализа и принятия решений в пределах, допускаемых Применимым законодательством. Оператор не обязан раскрывать алгоритмы, модели, параметры, риск-индикаторы и иные технические сведения в объеме, который способен облегчить обход механизмов контроля, создать угрозу информационной безопасности либо нарушить права и законные интересы третьих лиц.",contentEn:"17.13. To secure the Platform, prevent fraud and abuse, detect abnormal activity and manage risk, the Operator may use automated analysis and decision-making to the extent permitted by Applicable Law. It need not disclose algorithms, models, parameters, risk indicators or other technical information where doing so could facilitate circumvention, threaten information security or infringe third-party rights."},{type:"paragraph",contentRu:"17.14. В случаях, когда Применимое законодательство предоставляет Пользователю право получить информацию об автоматизированной обработке, заявить предусмотренное законом возражение, потребовать пересмотра решения либо вмешательства уполномоченного лица, соответствующее право может быть реализовано посредством каналов и в порядке, указанных в Политике конфиденциальности.",contentEn:"17.14. Where Applicable Law gives the User a right to information about automated processing, to object, to request human review or another intervention, the User may exercise that right through the channels and procedure stated in the Privacy Policy."},{type:"paragraph",contentRu:"17.15. Прекращение использования Платформы, закрытие или удаление Аккаунта не влечет автоматического и немедленного уничтожения всех связанных с Пользователем данных. Оператор вправе или обязан продолжить хранение отдельных сведений в течение срока, необходимого для выполнения требований Применимого законодательства, исполнения юридических обязанностей, предотвращения и расследования мошенничества, разрешения споров и претензий, подтверждения совершенных операций, установления, осуществления или защиты юридических требований и иных законных целей, предусмотренных Политикой конфиденциальности.",contentEn:"17.15. Stopping use of the Platform or closing or deleting the Account does not automatically require immediate deletion of all User-related data. The Operator may be entitled or required to retain information for as long as necessary to comply with Applicable Law, perform legal obligations, prevent or investigate fraud, resolve claims, evidence transactions, establish, exercise or defend legal claims, or pursue another legitimate purpose described in the Privacy Policy."},{type:"paragraph",contentRu:"17.16. Пользователь обязан предоставлять Оператору достоверные сведения и гарантирует наличие законного основания для передачи предоставляемых им данных и документов. Пользователь не вправе предоставлять документы, персональные данные, платежные реквизиты или иные сведения третьего лица без его надлежащего согласия либо иного применимого правового основания, за исключением случаев, когда предоставление соответствующих сведений прямо требуется Применимым законодательством.",contentEn:"17.16. The User shall provide accurate information and warrants that a valid legal basis exists for any data or document supplied to the Operator. The User may not provide a third party's document, personal data, payment details or other information without that person's valid consent or another applicable legal basis, unless Applicable Law expressly requires the disclosure."},{type:"subtitle",contentRu:"18. Доступность Платформы, гарантии и ограничение ответственности",contentEn:"18. Platform Availability, Warranties and Limitation of Liability",level:1},{type:"paragraph",contentRu:"18.1. Платформа и ее функциональные возможности предоставляются на условиях «как есть» (as is) и «по мере доступности» (as available). В максимальной степени, допускаемой Применимым законодательством, Оператор не предоставляет каких-либо прямо не предусмотренных настоящим Соглашением гарантий, при этом настоящее положение не исключает и не ограничивает обязательные гарантии и иные права Пользователя, от которых невозможно отказаться в силу Применимого законодательства.",contentEn:"18.1. The Platform and its functionality are provided on an “as is” and “as available” basis. To the maximum extent permitted by Applicable Law, the Operator does not provide any guarantees not expressly provided for in this Agreement, and this provision does not exclude or limit mandatory guarantees and other rights of the User that cannot be waived by virtue of Applicable Law."},{type:"paragraph",contentRu:"18.2. Оператор не гарантирует непрерывную, безошибочную или полностью защищенную от технических сбоев работу Платформы, а также постоянную доступность конкретной функции, Предмета, способа Пополнения или Вывода, Steam-бота, платежного канала либо сторонней интеграции. Временное ограничение или прекращение доступности отдельных элементов Платформы само по себе не является нарушением обязательств Оператора, если соответствующее обстоятельство находится вне его разумного контроля либо связано с проведением необходимых технических или обеспечительных мероприятий.",contentEn:"18.2. The Operator does not warrant that the Platform will operate continuously, without error or free from every technical failure, or that a particular function, Item, Top-Up or Withdrawal method, Steam bot, payment channel or third-party integration will remain continuously available. Temporary restriction or unavailability is not, by itself, a breach where it is beyond the Operator's reasonable control or results from necessary technical or security measures."},{type:"paragraph",contentRu:"18.3. Оператор применяет разумные и соответствующие характеру деятельности организационные и технические меры, направленные на обеспечение безопасности Платформы и обрабатываемых данных. При этом упоминание либо использование определенных платежных технологий, банков, платежных систем или провайдеров не означает заявления Оператора о самостоятельном соответствии стандартам PCI DSS, Visa Secure (Verified by Visa), Mastercard Identity Check (Mastercard SecureCode) либо иным отраслевым стандартам, если такое соответствие прямо не подтверждено применимым к Оператору документом или сертификацией.",contentEn:"18.3. The Operator applies organizational and technical measures that are reasonable and appropriate to the nature of the activity, aimed at ensuring the security of the Platform and the processed data. However, the mention or use of certain payment technologies, banks, payment systems or providers does not imply a statement by the Operator of independent compliance with PCI DSS, Visa Secure (Verified by Visa), Mastercard Identity Check (Mastercard SecureCode) or other industry standards, unless such compliance is directly confirmed by a document or certification applicable to the Operator."},{type:"paragraph",contentRu:"18.4. Оператор не несет ответственности за действия или бездействие Пользователя, включая передачу третьим лицам паролей, кодов подтверждения или иных средств аутентификации, недостаточную защиту устройства или Steam-аккаунта, установку или использование вредоносного либо скомпрометированного программного обеспечения, а также иные обстоятельства, возникшие на стороне Пользователя и находящиеся вне разумного контроля Оператора. Настоящее ограничение не применяется в той мере, в которой соответствующий ущерб непосредственно обусловлен нарушением обязанностей самим Оператором.",contentEn:"18.4. The Operator is not responsible for the actions or inaction of the User, including the transfer of passwords, confirmation codes or other means of authentication to third parties, insufficient protection of the device or Steam Account, installation or use of malicious or compromised software, as well as other circumstances that arose on the User’s side and are beyond the reasonable control of the Operator. This limitation does not apply to the extent that the corresponding damage is directly attributable to the violation of duties by the Operator itself."},{type:"paragraph",contentRu:"18.5. Оператор не контролирует и не гарантирует сохранение определенной рыночной стоимости, ликвидности, характеристик, редкости или доступности Предметов. Оператор также не гарантирует получение Пользователем прибыли или иной экономической выгоды, окупаемость Пополнения, получение Предмета определенной стоимости либо возможность передачи или Вывода конкретного Предмета в выбранный Пользователем момент, если соответствующий результат зависит от функционала Платформы, рыночных условий, действий Valve, разработчика игры или иных обстоятельств вне разумного контроля Оператора.",contentEn:"18.5. The Operator does not control or guarantee the maintenance of a particular market value, liquidity, characteristics, rarity or availability of Items. The Operator also does not guarantee that the User will receive a profit or other economic benefit, the recoupment of the Deposit, the receipt of an Item of a certain value, or the possibility of transferring or withdrawing a specific Item at the time chosen by the User, if the corresponding result depends on the functionality of the Platform, market conditions, actions of Valve, the game developer or other circumstances beyond the reasonable control of the Operator."},{type:"paragraph",contentRu:"18.6. В максимальной степени, допускаемой Применимым законодательством, Оператор не несет ответственности за косвенные, последующие, специальные, штрафные или предполагаемые убытки, упущенную выгоду или доход, утрату ожидаемой экономической возможности или шанса, последующее изменение рыночной стоимости Предметов, репутационный вред и иные потери, не являющиеся непосредственным и разумно предвидимым следствием установленного нарушения Оператором настоящего Соглашения.",contentEn:"18.6. To the fullest extent permitted by Applicable Law, the Operator shall not be liable for indirect, consequential, special, punitive or speculative loss, loss of profit or revenue, loss of an anticipated economic opportunity, subsequent changes in Item value, reputational harm, or other loss that is not a direct and reasonably foreseeable consequence of the Operator's established breach."},{type:"paragraph",contentRu:"18.7. Если требование Пользователя непосредственно связано с одной конкретной операцией, совокупная ответственность Оператора в связи с такой операцией в максимально допустимой Применимым законодательством степени ограничивается размером фактически понесенного и документально подтвержденного прямого ущерба и в любом случае не превышает сумму, фактически уплаченную Пользователем Оператору в связи с соответствующей спорной операцией.",contentEn:"18.7. If the User's claim is directly related to one specific transaction, the Operator's aggregate liability in connection with such transaction, to the maximum extent permitted by Applicable Law, is limited to the amount of direct damages actually suffered and documented and in any case does not exceed the amount actually paid by the User to the Operator in connection with the relevant disputed transaction."},{type:"paragraph",contentRu:"18.8. Если требование невозможно разумно отнести к одной конкретной операции, совокупная ответственность Оператора по всем взаимосвязанным требованиям, возникшим вследствие одного события или серии связанных событий в течение соответствующего двенадцатимесячного периода, в максимально допустимой законом степени ограничивается общей суммой платежей, фактически произведенных Пользователем в пользу Оператора в течение трех месяцев, непосредственно предшествовавших событию, послужившему основанием для требования.",contentEn:"18.8. If a claim cannot be reasonably attributed to one specific transaction, the aggregate liability of the Operator for all related claims arising out of a single event or series of related events during the relevant twelve month period shall, to the maximum extent permitted by law, be limited to the total amount of payments actually made by the User to the Operator during the three months immediately preceding the event giving rise to the claim."},{type:"paragraph",contentRu:"18.9. Ограничения и исключения ответственности, предусмотренные настоящим разделом, не применяются в отношении мошенничества или умышленного неправомерного поведения Оператора, ответственности за смерть или причинение вреда здоровью вследствие небрежности в случаях, предусмотренных законом, нарушения иных обязательств, ответственность за которые не может быть исключена или ограничена соглашением сторон, а также в иных случаях, когда соответствующее ограничение прямо запрещено Применимым законодательством.",contentEn:"18.9. The exclusions and limitations in this section do not apply to the Operator's fraud or willful misconduct, death or personal injury caused by negligence where law so provides, any other liability that cannot be excluded or limited by agreement, or any circumstance in which Applicable Law expressly prohibits the exclusion or limitation."},{type:"paragraph",contentRu:"18.10. Пользователь обязан принимать разумные и доступные меры, направленные на предотвращение и уменьшение возможного ущерба, в частности прекратить совершение повторных операций после выявления очевидной ошибки или иной проблемы и своевременно уведомить Оператора о соответствующих обстоятельствах. В пределах, допускаемых Применимым законодательством, Оператор не несет ответственности за ту часть ущерба, которая возникла или увеличилась вследствие необоснованного непринятия Пользователем разумных мер по его предотвращению или уменьшению.",contentEn:"18.10. The User shall take reasonable available steps to prevent or mitigate loss, including stopping repeated transactions after an obvious error and promptly notifying the Operator. To the extent permitted by Applicable Law, the Operator is not liable for the portion of loss caused or increased by the User's unreasonable failure to take those steps."},{type:"paragraph",contentRu:"18.11. Никакое положение настоящего раздела не освобождает Оператора от обязанности произвести необходимую корректировку собственной подтвержденной Технической ошибки в учете, исполнить вступившее в силу обязательное решение компетентного органа либо предоставить Пользователю средство правовой защиты, которое является обязательным и не может быть исключено или ограничено в соответствии с Применимым законодательством.",contentEn:"18.11. Nothing in this section relieves the Operator of its obligation to correct the effects of a confirmed Technical Error in its own records, comply with a binding decision of a competent authority, or provide any mandatory remedy that cannot be excluded or limited under Applicable Law."},{type:"paragraph",contentRu:"18.12. Оператор не несет ответственности за неисполнение или задержку исполнения обязательств в той мере, в которой они непосредственно вызваны чрезвычайными и находящимися вне его разумного контроля обстоятельствами, включая стихийные бедствия, пожары, военные действия, массовые беспорядки, действия или запреты государственных органов, обязательные санкционные ограничения, масштабные перебои связи или энергоснабжения, существенные кибератаки, прекращение или существенное ограничение работы Steam, платежной, банковской, облачной или иной критически необходимой внешней инфраструктуры, а также иные сопоставимые непредотвратимые обстоятельства (форс-мажор).",contentEn:"18.12. The Operator is not responsible for failure to perform or delay in fulfilling obligations to the extent that they are directly caused by extraordinary circumstances beyond its reasonable control, including natural disasters, fires, military actions, riots, actions or prohibitions of government authorities, mandatory sanctions restrictions, large-scale communications or power outages, significant cyber attacks, termination or significant limitation of the operation of Steam, payment, banking, cloud or other critical external infrastructure, as well as other comparable unavoidable circumstances (force majeure)."},{type:"paragraph",contentRu:"18.13. Сторона, исполнению обязательств которой препятствуют обстоятельства форс-мажора, освобождается от ответственности исключительно на период действия и в объеме фактического влияния соответствующих обстоятельств. Такая сторона обязана, насколько это разумно возможно, принимать меры для ограничения последствий соответствующего события, восстановления исполнения и надлежащего исполнения обязательств, которые не затронуты обстоятельствами форс-мажора.",contentEn:"18.13. A Party prevented from performing by force majeure is relieved from liability only for the duration and to the extent of the event's actual effect. So far as reasonably possible, that Party shall mitigate the consequences, resume affected performance and continue to perform obligations not affected by the event."},{type:"paragraph",contentRu:"18.14. В пределах, допускаемых Применимым законодательством, Пользователь обязан возместить Оператору фактически понесенные и документально подтвержденные прямые убытки, обязательные комиссии и обоснованные требования третьих лиц, непосредственно возникшие вследствие доказанного умышленного мошенничества Пользователя, использования им незаконного или несанкционированного платежного средства, нарушения прав третьих лиц либо умышленного обхода или нарушения механизмов безопасности Платформы. Обязанность по возмещению не распространяется на убытки в той части, в которой они вызваны действиями или нарушением Оператора, применением необоснованных или несоразмерных мер либо иными обстоятельствами, за которые Пользователь не несет ответственности согласно Применимому законодательству.",contentEn:"18.14. To the extent permitted by Applicable Law, the User shall compensate the Operator for actual and documented direct losses, mandatory fees and reasonable claims of third parties that directly arose as a result of the User's proven intentional fraud, use of an illegal or unauthorized means of payment, violation of the rights of third parties, or deliberate circumvention or violation of the Platform's security mechanisms. The obligation to compensate does not apply to losses to the extent that they are caused by the actions or violation of the Operator, the use of unreasonable or disproportionate measures, or other circumstances for which the User is not responsible according to Applicable Law."},{type:"paragraph",contentRu:"18.15. Каждое предусмотренное настоящим разделом исключение или ограничение ответственности применяется самостоятельно и исключительно в максимальной степени, допускаемой Применимым законодательством. Признание отдельного ограничения полностью или частично недействительным, неисполнимым либо неприменимым не влияет на действительность остальных положений настоящего раздела и не должно толковаться как расширяющее их содержание сверх прямо предусмотренного настоящим Соглашением.",contentEn:"18.15. Each exclusion or limitation of liability provided in this section shall apply independently and solely to the maximum extent permitted by Applicable Law. The recognition of a particular restriction as wholly or partially invalid, unenforceable or inapplicable does not affect the validity of the remaining provisions of this section and should not be construed as expanding their content beyond what is expressly provided for in this Agreement."},{type:"subtitle",contentRu:"19. Заключительные положения",contentEn:"19. Final Provisions",level:1},{type:"paragraph",contentRu:"19.1. До обращения в суд Пользователю рекомендуется направить Оператору письменную претензию через официальный канал поддержки, указав сведения, достаточные для идентификации Пользователя и спорной операции, включая Steam ID, идентификатор Аккаунта или операции, дату события, описание обстоятельств и заявляемое требование. Если обязательный досудебный порядок установлен Применимым законодательством, его соблюдение осуществляется в соответствии с соответствующими императивными требованиями. Претензии, связанные с предполагаемой Технической ошибкой, должны направляться без неоправданной задержки, по возможности в течение 72 часов с момента ее обнаружения; указанный срок носит рекомендательный характер и не сокращает установленные законом сроки предъявления требований или исковой давности.",contentEn:"19.1. Before going to court, the User is recommended to send a written claim to the Operator through the official support channel, indicating information sufficient to identify the User and the disputed transaction, including Steam ID, Account or transaction identifier, date of the event, description of the circumstances and the stated claim. If mandatory pre-trial procedure is established by Applicable Law, its compliance is carried out in accordance with the relevant mandatory requirements. Claims related to an alleged Technical Error must be made without undue delay, if possible within 72 hours of discovery; the specified period is advisory in nature and does not reduce the statutory deadlines for filing claims or the limitation period."},{type:"paragraph",contentRu:"19.2. Оператор подтверждает получение претензии посредством доступного канала связи и стремится предоставить содержательный ответ в течение 30 календарных дней с момента получения достаточной для рассмотрения информации. Срок может быть обоснованно продлен, если этого требуют сложность технической, платежной или иной проверки, необходимость получения дополнительных сведений, участие платежного партнера, Valve или иного третьего лица либо требования Применимого законодательства.",contentEn:"19.2. The Operator acknowledges receipt of the claim through an available communication channel and strives to provide a meaningful response within 30 calendar days from the date of receipt of information sufficient for consideration. The period may be reasonably extended if required by the complexity of technical, payment or other verification, the need to obtain additional information, the involvement of a payment partner, Valve or other third party, or the requirements of Applicable Law."},{type:"paragraph",legalBlock:"governingLaw"},{type:"paragraph",contentRu:"19.4. Настоящая редакция Соглашения вступает в силу 11 августа 2026 года либо, если ее фактическая публикация на Сайте состоялась позднее указанной даты, с даты такой публикации, и действует до вступления в силу последующей редакции. Новая редакция применяется к действиям, Пополнениям, Игровым операциям, Выводам и иным юридически значимым событиям, совершенным после даты ее вступления в силу, а также к продолжающимся отношениям в части последующего использования Аккаунта, Внутреннего баланса, Инвентаря, незавершенных операций, проверок и обращений.",contentEn:"19.4. This edition of the Agreement comes into force on August 11, 2026, or, if its actual publication on the Site took place later than the specified date, from the date of such publication, and is valid until the subsequent edition comes into force. The new edition applies to actions, Top-Ups, Game Operations, Withdrawals and other legally significant events committed after the date of its entry into force, as well as to ongoing relations in terms of subsequent use of the Account, Internal Balance, Inventory, unfinished operations, checks and requests."},{type:"paragraph",contentRu:"19.5. Операции и иные юридически значимые действия, полностью завершенные до вступления в силу новой редакции, оцениваются с учетом условий Соглашения и норм права, применимых на момент их совершения. Новая редакция не применяется таким образом, чтобы задним числом устанавливать новое нарушение, новую обязанность или дополнительную ответственность Пользователя либо прекращать уже возникшее у него право. При этом процедурные положения действующей редакции, касающиеся проведения проверки, предоставления сведений, временных обеспечительных мер и оценки доказательств, могут применяться к продолжающемуся спору относительно ранее совершенной операции, если такое применение не ухудшает императивные права Пользователя и не устанавливает ретроспективную ответственность.",contentEn:"19.5. A transaction or other legally significant act completed before a new version took effect shall be assessed under the Agreement and law applicable when it occurred. A new version shall not retroactively create a breach, obligation or additional liability, or extinguish an accrued User right. Procedural provisions may apply to an ongoing dispute about an earlier transaction only if they do not impair a mandatory User right or impose retrospective liability."},{type:"paragraph",contentRu:"19.6. В целях выявления и расследования Технических ошибок, дублирования операций, чарджбэков, мошенничества, злоупотреблений и иных нарушений Оператор вправе анализировать относящиеся к соответствующей проверке Серверные данные, платежи, начисления, Игровые операции и иные действия, совершенные в течение 12 месяцев до даты начала проверки, а также за более длительный период, если обязанность или право на такую проверку предусмотрены Применимым законодательством. Корректировка ранее совершенной операции допускается, если соответствующая возможность была предусмотрена применявшимися к ней условиями, непосредственно следует из закона либо необходима для устранения подтвержденной ошибки, вследствие которой Пользователь объективно не приобрел соответствующего права или ценности.",contentEn:"19.6. In order to identify and investigate Technical Errors, duplication of transactions, chargebacks, fraud, abuse and other violations, the Operator may analyze Server Data, payments, charges, Game Operations and other actions related to the relevant verification, performed within 12 months before the start date of the verification, as well as for a longer period, if the obligation or right to such verification is provided for by Applicable Law. Correction of a previously completed transaction is permitted if the corresponding possibility was provided for by the conditions applied to it, directly follows from the law, or is necessary to eliminate a confirmed error, as a result of which the User objectively did not acquire the corresponding right or value."},{type:"paragraph",contentRu:"19.7. Оператор вправе изменять и дополнять настоящее Соглашение. Существенные изменения, ухудшающие договорное положение Пользователя, применяются на будущее после предоставления разумного предварительного уведомления и, когда это требуется Применимым законодательством, получения отдельного согласия Пользователя. Продолжение использования Платформы после вступления изменений в силу рассматривается как принятие новой редакции исключительно в тех случаях и юрисдикциях, где такая форма согласия юридически допустима. Изменения могут вступать в силу без предварительного периода уведомления, если это объективно необходимо для соблюдения закона или обязательного требования компетентного органа, предотвращения мошенничества, устранения существенной уязвимости либо восстановления безопасного функционирования Платформы, при условии отсутствия неправомерного ретроспективного ухудшения прав Пользователя.",contentEn:"19.7. The Operator may amend and supplement this Agreement. Significant changes that impair the User's contractual position will apply for the future after providing reasonable prior notice and, where required by Applicable Law, obtaining the User's separate consent. Continued use of the Platform after changes come into force is considered acceptance of the new version only in those cases and jurisdictions where such a form of consent is legally permissible. Changes may take effect without a prior notice period if this is objectively necessary to comply with the law or a mandatory requirement of a competent authority, prevent fraud, eliminate a significant vulnerability or restore the secure functioning of the Platform, provided that there is no unlawful retrospective impairment of the User's rights."},{type:"paragraph",contentRu:"19.8. Оператор вправе хранить сведения о редакциях Соглашения и доказательства их принятия Пользователем, включая дату и время, идентификатор Аккаунта, номер или иной идентификатор версии документа, IP-адрес и иные допустимые технические сведения. Если Пользователь не согласен с новой редакцией, он обязан прекратить совершение новых операций после ее вступления в силу и вправе запросить закрытие Аккаунта. Урегулирование существующего Внутреннего баланса, Предметов, незавершенных операций, задолженности и продолжающихся проверок осуществляется в соответствии с применимыми условиями Соглашения и обязательными нормами закона и само по себе не предполагает автоматической выплаты Внутреннего баланса денежными средствами.",contentEn:"19.8. The Operator may retain versions of this Agreement and evidence of User acceptance, including the date and time, Account ID, version identifier, IP address and other permitted technical information. A User who rejects a new version shall stop initiating new transactions after it takes effect and may request Account closure. Existing positions remain subject to the applicable terms and mandatory law and do not automatically become payable in cash."},{type:"paragraph",contentRu:"19.9. Оператор вправе прекратить предоставление Платформы полностью либо прекратить или существенно ограничить ее предоставление на определенной территории. Если иное не обусловлено требованиями закона, компетентного органа, безопасности или иными обстоятельствами, требующими незамедлительных действий, Оператор предоставляет Пользователям разумное предварительное уведомление и, насколько это технически и юридически возможно, возможность завершить доступные незавершенные операции и распорядиться соответствующими Предметами.",contentEn:"19.9. The Operator may stop providing the Platform completely or to stop or significantly limit its provision in a certain territory. Unless otherwise required by law, competent authority, security or other circumstances requiring immediate action, the Operator shall provide Users with reasonable advance notice and, to the extent technically and legally possible, the opportunity to complete available pending transactions and dispose of the relevant Items."},{type:"paragraph",contentRu:"19.10. Пользователь вправе запросить закрытие или удаление Аккаунта после завершения обязательных проверок, платежных споров и незавершенных операций, препятствующих такому удалению. До закрытия Аккаунта Пользователю может быть предоставлен разумный срок для использования доступного Внутреннего баланса и распоряжения Предметами предусмотренными Платформой способами. Закрытие или удаление Аккаунта само по себе не преобразует Внутренний баланс в денежное требование к Оператору и не создает обязанности осуществить его денежный вывод, если иное прямо не предусмотрено Применимым законодательством. Сам факт подачи запроса на удаление Аккаунта не является самостоятельным основанием для конфискации принадлежащих Пользователю ценностей.",contentEn:"19.10. The User may request Account closure or deletion after completion of any mandatory review, payment dispute or pending transaction that prevents closure. The User may be given a reasonable period to use the available Internal Balance and dispose of Items through supported methods. Closure does not convert the Internal Balance into a monetary claim or require cash payment unless Applicable Law provides otherwise, and a deletion request is not a ground for forfeiting the User's assets."},{type:"paragraph",contentRu:"19.11. Оператор вправе передать настоящее Соглашение, а также связанные с ним права и обязанности своему правопреемнику, аффилированному лицу либо приобретателю соответствующего бизнеса или существенной части активов при условии сохранения предусмотренных законом прав Пользователя и направления уведомления, если оно требуется Применимым законодательством. Пользователь не вправе уступать или иным образом передавать свои права и обязанности по настоящему Соглашению третьему лицу без предварительного согласия Оператора, если иное не предусмотрено обязательными нормами закона.",contentEn:"19.11. The Operator may assign this Agreement and related rights and obligations to a successor, affiliate or acquirer of the relevant business or a material part of its assets, provided that statutory User rights are preserved and any notice required by Applicable Law is given. The User may not assign or transfer rights or obligations without the Operator's prior consent unless mandatory law provides otherwise."},{type:"paragraph",contentRu:"19.12. Нереализация или несвоевременная реализация Оператором какого-либо права или средства защиты не является отказом от такого права и не препятствует его последующей реализации. Если отдельное положение настоящего Соглашения признано недействительным, незаконным или неисполнимым, оно применяется в максимально допустимом законом объеме либо, когда это возможно, заменяется допустимым положением, наиболее близким к его первоначальной законной цели, без прекращения действия остальных положений Соглашения.",contentEn:"19.12. A failure or delay by the Operator in exercising a right or remedy is not a waiver and does not prevent later exercise. If a provision is invalid, illegal or unenforceable, it shall be enforced to the fullest lawful extent and, where possible, construed to achieve its original lawful purpose; the remaining provisions remain effective."},{type:"paragraph",contentRu:"19.13. Настоящее Соглашение совместно со специальными правилами, Политикой конфиденциальности и иными документами, прямо включенными в него посредством ссылки, образует соглашение сторон по регулируемому ими предмету и заменяет предшествующие договоренности в соответствующей части с учетом установленных настоящим разделом правил действия условий во времени. В случае противоречия между настоящим Соглашением и специальными правилами приоритет имеют специальные правила исключительно в отношении регулируемого ими специального вопроса, если прямо не установлено иное.",contentEn:"19.13. This Agreement, together with the special rules, Privacy Policy and other documents expressly incorporated by reference, constitutes the agreement between the Parties on the matters it covers and supersedes prior agreements to that extent. Special rules prevail only for the specific matter they govern, unless expressly stated otherwise."},{type:"paragraph",contentRu:"19.14. Уведомления Оператора могут направляться посредством интерфейса Платформы или Аккаунта, публикации на Сайте, электронной почты либо иного канала связи, предоставленного Пользователем или предусмотренного функционалом Платформы. Юридически значимые обращения Пользователя направляются посредством официальных каналов связи Оператора, опубликованных на Сайте. Пользователь обязан обеспечивать актуальность предоставленных контактных данных и самостоятельно контролировать сообщения, направленные посредством предусмотренных настоящим Соглашением каналов.",contentEn:"19.14. The Operator may deliver notices through the Platform or Account interface, by publication on the Site, by email, or through another communication channel provided by the User or supported by Platform functionality. The User shall send legally significant communications through the Operator's official contact channels published on the Site and shall keep contact details current."},{type:"paragraph",contentRu:"19.15. Настоящее Соглашение составлено на английском языке. Приоритет при толковании условий имеет англоязычная редакция в той мере, в которой подобное правило о приоритете допускается Применимым законодательством.",contentEn:"19.15. This Agreement is written in English. The English language version has priority in interpreting the terms to the extent that such a rule of priority is permitted by Applicable Law."},{type:"paragraph",contentRu:"19.16. Положения настоящего Соглашения, которые по своей природе предназначены для применения после прекращения использования Платформы или закрытия Аккаунта, включая положения о платежных спорах и чарджбэках, Серверных данных и доказательствах, интеллектуальной собственности, защите данных в пределах применимых сроков хранения, ответственности и возмещении убытков, применимом праве и разрешении споров, сохраняют силу после прекращения отношений в объеме и на срок, необходимые для окончательного урегулирования возникших между сторонами прав и обязанностей.",contentEn:"19.16. The provisions of this Agreement, which by their nature are intended to apply after termination of use of the Platform or closure of the Account, including provisions regarding payment disputes and chargebacks, Server Data and evidence, intellectual property, data protection within the applicable retention periods, liability and indemnification, Applicable Law and dispute resolution, shall survive termination of the relationship to the extent and for the period necessary for the final settlement of the rights and obligations arising between the parties."}]],858469);let o="User Agreement (TOS)",r="Version dated 31 August 2026",i="Before registering an Account on the Platform, adding funds and/or other assets supported by the Platform, or performing any Game Operation, the User shall carefully review this Agreement in full and assess the legal, financial and other consequences of accepting it.";e.s(["tosPageTranslations",0,{ru:{backButton:"Вернуться",warningText:"До момента осуществления регистрации учетной записи на Платформе, внесения денежных средств и (или) иных предусмотренных функционалом Платформы активов, а равно до совершения любых Игровых операций Пользователь обязан внимательно и в полном объеме ознакомиться с условиями настоящего Соглашения и оценить правовые, имущественные и иные последствия его принятия.",pageTitle:"Пользовательское соглашение (TOS)",version:"Редакция от 31 августа 2026 года"},en:{backButton:"Go back",warningText:i,pageTitle:o,version:r},ka:{backButton:"უკან დაბრუნება",warningText:i,pageTitle:o,version:r},kk:{backButton:"Артқа қайту",warningText:i,pageTitle:o,version:r},uz:{backButton:"Orqaga qaytish",warningText:i,pageTitle:o,version:r},ro:{backButton:"Înapoi",warningText:i,pageTitle:o,version:r},hu:{backButton:"Vissza",warningText:i,pageTitle:o,version:r},tr:{backButton:"Geri dön",warningText:i,pageTitle:o,version:r},pl:{backButton:"Wróć",warningText:i,pageTitle:o,version:r},mn:{backButton:"Буцах",warningText:i,pageTitle:o,version:r},pt:{backButton:"Voltar",warningText:i,pageTitle:o,version:r}}],693179)}]);

